import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { listCompetitors, addCompetitor, deleteCompetitor } from "../db/boards";

interface Competitor {
  id: string;
  name: string;
  domain: string;
}

export function Competitors() {
  const { id } = useParams<{ id: string }>();
  const [competitors, setCompetitors] = useState<Competitor[]>([]);
  const [loading, setLoading] = useState(true);
  const [adding, setAdding] = useState(false);
  const [name, setName] = useState("");
  const [domain, setDomain] = useState("");

  const load = async () => {
    if (!id) return;
    setLoading(true);
    const list = await listCompetitors(id).catch(() => []);
    setCompetitors(list as Competitor[]);
    setLoading(false);
  };

  useEffect(() => {
    load();
  }, [id]);

  const handleAdd = async () => {
    if (!id || !name.trim() || !domain.trim()) return;
    setAdding(true);
    await addCompetitor(id, { name: name.trim(), domain: domain.trim() });
    setName("");
    setDomain("");
    setAdding(false);
    await load();
  };

  const handleDelete = async (compId: string) => {
    if (!id) return;
    await deleteCompetitor(id, compId);
    setCompetitors((prev) => prev.filter((c) => c.id !== compId));
  };

  if (loading) {
    return (
      <div className="flex min-h-[40vh] items-center justify-center text-[var(--shell-text-muted)]">
        데이터 로딩 중...
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-[1400px] space-y-6">
      <header>
        <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">
          Competitor Analysis
        </div>
        <h1 className="mt-2 text-3xl font-semibold text-[var(--shell-text)]">
          경쟁사 관리
        </h1>
        <p className="mt-2 text-sm text-[var(--shell-text-muted)]">
          경쟁사를 등록하고 AI 답변 내 노출 현황을 비교합니다.
        </p>
      </header>

      {/* Add competitor form */}
      <section className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
        <div className="text-[11px] uppercase tracking-[0.18em] text-[var(--shell-text-soft)]">
          경쟁사 추가
        </div>
        <div className="mt-3 flex flex-wrap items-end gap-3">
          <label className="block flex-1">
            <div className="mb-1 text-[11px] text-[var(--shell-text-soft)]">
              이름
            </div>
            <input
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="경쟁사 이름"
              className="shell-input w-full rounded-[10px] px-3 py-2 text-sm"
            />
          </label>
          <label className="block flex-1">
            <div className="mb-1 text-[11px] text-[var(--shell-text-soft)]">
              도메인
            </div>
            <input
              value={domain}
              onChange={(e) => setDomain(e.target.value)}
              placeholder="example.com"
              className="shell-input w-full rounded-[10px] px-3 py-2 text-sm"
            />
          </label>
          <button
            type="button"
            onClick={handleAdd}
            disabled={adding || !name.trim() || !domain.trim()}
            className="shell-button-primary rounded-xl px-4 py-2.5 text-sm font-medium disabled:opacity-50"
          >
            {adding ? "추가 중..." : "추가"}
          </button>
        </div>
      </section>

      {/* Competitor list */}
      <section className="space-y-3">
        <div className="text-[11px] uppercase tracking-[0.18em] text-[var(--shell-text-soft)]">
          등록된 경쟁사 ({competitors.length})
        </div>

        {competitors.length > 0 ? (
          <div className="grid gap-3 md:grid-cols-2 lg:grid-cols-3">
            {competitors.map((comp) => (
              <article
                key={comp.id}
                className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]"
              >
                <div className="flex items-start justify-between gap-3">
                  <div className="min-w-0">
                    <div className="text-base font-medium text-[var(--shell-text)]">
                      {comp.name}
                    </div>
                    <div className="mt-1 truncate text-sm text-[var(--shell-text-muted)]">
                      {comp.domain}
                    </div>
                  </div>
                  <button
                    type="button"
                    onClick={() => handleDelete(comp.id)}
                    className="shrink-0 rounded-lg border border-[var(--shell-danger)]/30 px-2.5 py-1.5 text-xs text-[var(--shell-danger)] transition-colors hover:bg-[var(--shell-danger)]/10"
                  >
                    삭제
                  </button>
                </div>
              </article>
            ))}
          </div>
        ) : (
          <div className="shell-transition rounded-[18px] border border-dashed border-[var(--shell-border)] bg-[var(--shell-panel)] p-8 text-center text-sm text-[var(--shell-text-muted)]">
            등록된 경쟁사가 없습니다. 위 폼에서 경쟁사를 추가하세요.
          </div>
        )}
      </section>
    </div>
  );
}
