import {
  collection,
  doc,
  addDoc,
  getDoc,
  getDocs,
  deleteDoc,
  updateDoc,
  setDoc,
  query,
  where,
  orderBy,
  limit,
  onSnapshot,
  serverTimestamp,
  arrayUnion,
  arrayRemove,
  type Unsubscribe,
} from "firebase/firestore";
import { db } from "../config/firebase";
import {
  COLLECTIONS,
  type Board,
  type BoardDocument,
  type SnsConnection,
  type SnsDraftRun,
  type GbpReview,
  type Competitor,
  type GoogleKeywordAnalysis,
  type NaverKeywordAnalysis,
} from "./collections";

function extractDomain(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url;
  }
}

// ── Board CRUD ─────────────────────────────────────────────

export async function listBoards(userId: string): Promise<Board[]> {
  const q = query(
    collection(db, COLLECTIONS.boards),
    where("userId", "==", userId),
  );
  const snap = await getDocs(q);
  const boards = snap.docs.map((d) => ({
    id: d.id,
    ...d.data(),
    createdAt: d.data().createdAt?.toDate?.() ?? new Date(),
    completedAt: d.data().completedAt?.toDate?.() ?? undefined,
  })) as Board[];
  boards.sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());
  return boards;
}

export async function getBoard(boardId: string): Promise<Board | null> {
  const snap = await getDoc(doc(db, COLLECTIONS.boards, boardId));
  if (!snap.exists()) return null;
  const data = snap.data();
  return {
    id: snap.id,
    ...data,
    createdAt: data.createdAt?.toDate?.() ?? new Date(),
    completedAt: data.completedAt?.toDate?.() ?? undefined,
  } as Board;
}

export async function createBoard(userId: string, url: string): Promise<string> {
  const domain = extractDomain(url);
  const ref = await addDoc(collection(db, COLLECTIONS.boards), {
    url,
    domain,
    siteName: domain,
    userId,
    status: "pending",
    stepStatus: {},
    createdAt: serverTimestamp(),
  });
  return ref.id;
}

export async function deleteBoard(boardId: string): Promise<void> {
  await deleteDoc(doc(db, COLLECTIONS.boards, boardId));
}

export async function updateBoard(
  boardId: string,
  data: Partial<Omit<Board, "id" | "createdAt">>,
): Promise<void> {
  await updateDoc(doc(db, COLLECTIONS.boards, boardId), data);
}

// ── Board subscription ─────────────────────────────────────

export function subscribeBoard(
  boardId: string,
  callback: (board: Board | null) => void,
): Unsubscribe {
  return onSnapshot(doc(db, COLLECTIONS.boards, boardId), (snap) => {
    if (!snap.exists()) {
      callback(null);
      return;
    }
    const data = snap.data();
    callback({
      id: snap.id,
      ...data,
      createdAt: data.createdAt?.toDate?.() ?? new Date(),
      completedAt: data.completedAt?.toDate?.() ?? undefined,
    } as Board);
  });
}

// ── Documents ──────────────────────────────────────────────

export async function getDocument(
  boardId: string,
  docKey: string,
): Promise<BoardDocument | null> {
  const snap = await getDoc(doc(db, COLLECTIONS.documents(boardId), docKey));
  if (!snap.exists()) return null;
  return { key: snap.id, ...snap.data() } as BoardDocument;
}

export async function listDocuments(boardId: string): Promise<BoardDocument[]> {
  const snap = await getDocs(collection(db, COLLECTIONS.documents(boardId)));
  return snap.docs.map((d) => ({ key: d.id, ...d.data() }) as BoardDocument);
}

