// ── Error journal ─────────────────────────────────────────

export interface ErrorJournalEntry {
  id: string;
  severity: "warning" | "error";
  category: "firestore" | "parse" | "llm";
  worker: string;
  functionName: string;
  message: string;
  detail: string;
  context: Record<string, unknown>;
  createdAt: Date | null;
}

export async function listErrorJournal(
  boardId: string,
  count = 50,
): Promise<ErrorJournalEntry[]> {
  const q = query(
    collection(db, COLLECTIONS.errorJournal(boardId)),
    orderBy("createdAt", "desc"),
    limit(count),
  );
  const snap = await getDocs(q);
  return snap.docs.map((d) => {
    const data = d.data();
    return {
      id: d.id,
      severity: data.severity,
      category: data.category,
      worker: data.worker,
      functionName: data.functionName,
      message: data.message,
      detail: data.detail,
      context: data.context ?? {},
      createdAt: data.createdAt?.toDate?.() ?? null,
    } as ErrorJournalEntry;
  });
}

// ── Live events subscription ───────────────────────────────

export function subscribeLiveEvents(
  boardId: string,
  callback: (data: Record<string, unknown> | null) => void,
): Unsubscribe {
  return onSnapshot(
    doc(db, COLLECTIONS.boards, boardId, "live_events", "status"),
    (snap) => {
      callback(snap.exists() ? (snap.data() as Record<string, unknown>) : null);
    },
  );
}

