// ── Keyword management ────────────────────────────────────

export async function addKeyword(
  boardId: string,
  category: "site" | "competitor" | "recommended" | "local",
  keyword: string,
): Promise<void> {
  await updateDoc(doc(db, COLLECTIONS.boards, boardId), {
    [`classifiedKeywords.${category}`]: arrayUnion({ keyword, custom: true }),
  });
}

export async function removeKeyword(
  boardId: string,
  category: "site" | "competitor" | "recommended" | "local",
  entry: { keyword: string; [key: string]: unknown },
): Promise<void> {
  await updateDoc(doc(db, COLLECTIONS.boards, boardId), {
    [`classifiedKeywords.${category}`]: arrayRemove(entry),
  });
}

