import { useEffect, useState, useCallback } from "react";
import { Link, useParams } from "react-router-dom";
import { listDocuments, getDocument, getCustomerProfile, saveCustomerProfile } from "../db/boards";
import type { BoardDocument } from "../db/collections";

type DocTab = "documents" | "profile" | "brand-kit";

export function Documents() {
  const { id, docKey } = useParams<{ id: string; docKey?: string }>();
  const [documents, setDocuments] = useState<BoardDocument[]>([]);
  const [selected, setSelected] = useState<BoardDocument | null>(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<DocTab>("documents");
  const [profile, setProfile] = useState<Record<string, any>>({});
  const [brandKit, setBrandKit] = useState<Record<string, any>>({});
  const [saving, setSaving] = useState(false);

  const load = useCallback(async () => {
    if (!id) return;
    setLoading(true);
    const [docs, cp] = await Promise.all([
      listDocuments(id).catch(() => []),
      getCustomerProfile(id).catch(() => null),
    ]);
    setDocuments(docs);
    if (cp) {
      setProfile(cp.profile as Record<string, any> ?? cp);
      setBrandKit(cp.brandKit as Record<string, any> ?? {});
    }
    setLoading(false);
  }, [id]);

  useEffect(() => { load(); }, [load]);

  useEffect(() => {
    if (!id || !docKey) { setSelected(null); return; }
    getDocument(id, docKey).catch(() => null).then((doc) => setSelected(doc));
  }, [id, docKey]);

  const handleSaveProfile = async () => {
    if (!id) return;
    setSaving(true);
    await saveCustomerProfile(id, { profile, brandKit });
    setSaving(false);
  };

  if (loading) {
    return <div className="flex min-h-[40vh] items-center justify-center text-[var(--shell-text-muted)]">Loading...</div>;
  }

  return (
    <div className="mx-auto max-w-[1400px] space-y-6">
      <header>
        <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">Knowledge Base</div>
        <h1 className="mt-2 text-3xl font-semibold text-[var(--shell-text)]">Documents</h1>
        <p className="mt-2 text-sm text-[var(--shell-text-muted)]">Analysis documents and customer profile management.</p>
      </header>

      {/* Tabs */}
      <div className="flex gap-1 border-b border-[var(--shell-border)]">
        {([["documents", "Documents"], ["profile", "Profile"], ["brand-kit", "Brand Kit"]] as const).map(([key, label]) => (
          <button key={key} onClick={() => setActiveTab(key)}
            className={`shell-transition border-b-2 px-4 py-2.5 text-xs ${activeTab === key ? "border-[var(--shell-accent)] text-[var(--shell-accent)]" : "border-transparent text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"}`}
          >{label}</button>
        ))}
      </div>

      {activeTab === "documents" && (
        <div className="grid gap-4 lg:grid-cols-[280px_1fr]">
          <aside className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-4 shadow-[var(--shell-shadow)]">
            <div className="mb-3 text-[11px] uppercase tracking-[0.18em] text-[var(--shell-text-soft)]">Documents ({documents.length})</div>
            {documents.length > 0 ? (
              <nav className="space-y-1">
                {documents.map((doc) => (
                  <Link key={doc.key} to={`/board/${id}/documents/${doc.key}`}
                    className={`block rounded-xl px-3 py-2.5 text-sm transition-colors ${
                      docKey === doc.key
                        ? "border border-[var(--shell-accent)]/40 bg-[var(--shell-accent-soft)] text-[var(--shell-accent)]"
                        : "text-[var(--shell-text-muted)] hover:bg-[var(--shell-panel-soft)] hover:text-[var(--shell-text)]"
                    }`}
                  >{doc.title || doc.key}</Link>
                ))}
              </nav>
            ) : (
              <div className="py-6 text-center text-xs text-[var(--shell-text-muted)]">No documents yet.</div>
            )}
          </aside>

          <section>
            {selected ? (
              <article className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
                <h2 className="text-lg font-semibold text-[var(--shell-text)]">{selected.title || selected.key}</h2>
                {selected.body && (
                  <div className="mt-4 whitespace-pre-wrap text-sm leading-7 text-[var(--shell-text-muted)]">{selected.body}</div>
                )}
                {selected.data && Object.keys(selected.data).length > 0 && (
                  <div className="mt-6 rounded-[14px] border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4">
                    <div className="mb-2 text-[11px] uppercase tracking-[0.18em] text-[var(--shell-text-soft)]">Structured Data</div>
                    <pre className="overflow-x-auto text-xs leading-5 text-[var(--shell-text-muted)]">{JSON.stringify(selected.data, null, 2)}</pre>
                  </div>
                )}
              </article>
            ) : (
              <div className="shell-transition rounded-[18px] border border-dashed border-[var(--shell-border)] bg-[var(--shell-panel)] p-8 text-center text-sm text-[var(--shell-text-muted)]">
                {documents.length > 0 ? "Select a document from the list." : "No documents generated yet. Complete onboarding to generate."}
              </div>
            )}
          </section>
        </div>
      )}

      {activeTab === "profile" && (
        <div className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
          <h2 className="text-sm font-medium text-[var(--shell-text)]">Customer Profile</h2>
          <div className="mt-4 grid gap-4 md:grid-cols-2">
            <ProfileField label="Company Name" value={profile.companyName || ""} onChange={(v) => setProfile({ ...profile, companyName: v })} />
            <ProfileField label="Industry" value={profile.industry || ""} onChange={(v) => setProfile({ ...profile, industry: v })} />
            <ProfileField label="Target Audience" value={profile.targetAudience || ""} onChange={(v) => setProfile({ ...profile, targetAudience: v })} multiline />
            <ProfileField label="USPs" value={profile.usps || ""} onChange={(v) => setProfile({ ...profile, usps: v })} multiline />
            <ProfileField label="Brand Voice" value={profile.brandVoice || ""} onChange={(v) => setProfile({ ...profile, brandVoice: v })} multiline />
            <ProfileField label="Notes" value={profile.notes || ""} onChange={(v) => setProfile({ ...profile, notes: v })} multiline />
          </div>
          <div className="mt-4">
            <button onClick={handleSaveProfile} disabled={saving} className="shell-button-primary rounded-xl px-4 py-2.5 text-sm font-medium disabled:opacity-50">
              {saving ? "Saving..." : "Save Profile"}
            </button>
          </div>
        </div>
      )}

      {activeTab === "brand-kit" && (
        <div className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
          <h2 className="text-sm font-medium text-[var(--shell-text)]">Brand Kit</h2>
          <div className="mt-4 grid gap-4 md:grid-cols-2">
            <ProfileField label="Logo URL" value={brandKit.logoUrl || ""} onChange={(v) => setBrandKit({ ...brandKit, logoUrl: v })} />
            <ProfileField label="Primary Color" value={brandKit.primaryColor || ""} onChange={(v) => setBrandKit({ ...brandKit, primaryColor: v })} />
            <ProfileField label="Font Preferences" value={brandKit.fontPreferences || ""} onChange={(v) => setBrandKit({ ...brandKit, fontPreferences: v })} />
            <ProfileField label="Tone Guidelines" value={brandKit.toneGuidelines || ""} onChange={(v) => setBrandKit({ ...brandKit, toneGuidelines: v })} multiline />
            <ProfileField label="Color Palette" value={brandKit.colorPalette || ""} onChange={(v) => setBrandKit({ ...brandKit, colorPalette: v })} multiline />
          </div>
          <div className="mt-4">
            <button onClick={handleSaveProfile} disabled={saving} className="shell-button-primary rounded-xl px-4 py-2.5 text-sm font-medium disabled:opacity-50">
              {saving ? "Saving..." : "Save Brand Kit"}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

function ProfileField({ label, value, onChange, multiline }: { label: string; value: string; onChange: (v: string) => void; multiline?: boolean }) {
  const cls = "shell-input w-full rounded-[10px] px-3 py-2 text-sm";
  return (
    <label className="block">
      <div className="mb-1 text-[11px] text-[var(--shell-text-soft)]">{label}</div>
      {multiline ? (
        <textarea value={value} onChange={(e) => onChange(e.target.value)} rows={3} className={cls} />
      ) : (
        <input value={value} onChange={(e) => onChange(e.target.value)} className={cls} />
      )}
    </label>
  );
}
