import { useEffect, useRef } from "react";

export interface ConsoleEntry {
  id: string;
  type: "info" | "success" | "error" | "search" | "warning" | "step";
  message: string;
  timestamp: number;
}

interface ConsoleLogProps {
  entries: ConsoleEntry[];
}

function getPrefix(type: ConsoleEntry["type"]) {
  switch (type) {
    case "success":
      return "\u2713";
    case "error":
      return "\u2717";
    case "search":
      return ">";
    case "warning":
      return "!";
    case "step":
      return "#";
    default:
      return ">";
  }
}

function getColor(type: ConsoleEntry["type"]) {
  switch (type) {
    case "success":
      return "text-[var(--shell-positive)]";
    case "error":
      return "text-[var(--shell-danger)]";
    case "search":
      return "text-[var(--shell-secondary)]";
    case "warning":
      return "text-[var(--shell-warning)]";
    case "step":
      return "text-[var(--shell-accent)]";
    default:
      return "text-[var(--shell-text-muted)]";
  }
}

export function ConsoleLog({ entries }: ConsoleLogProps) {
  const endRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [entries.length]);

  return (
    <div className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-main)] p-4 font-mono text-xs">
      <div className="mb-3 flex items-center gap-2 text-[var(--shell-text-muted)]">
        <span className="inline-block h-2.5 w-2.5 rounded-full bg-[var(--shell-danger)]/60" />
        <span className="inline-block h-2.5 w-2.5 rounded-full bg-[var(--shell-secondary)]/60" />
        <span className="inline-block h-2.5 w-2.5 rounded-full bg-[var(--shell-positive)]/60" />
        <span className="ml-2">GEO Insight Terminal</span>
      </div>
      <div className="max-h-[400px] space-y-1 overflow-y-auto">
        {entries.map((entry) => (
          <div key={entry.id} className={`console-line ${getColor(entry.type)}`}>
            <span className="mr-2">{getPrefix(entry.type)}</span>
            {entry.message}
          </div>
        ))}
        <div ref={endRef} />
      </div>
    </div>
  );
}
