import { NavLink } from "react-router-dom";

interface BoardSectionTabItem {
  label: string;
  to: string;
}

interface BoardSectionTabsProps {
  items: BoardSectionTabItem[];
}

export function BoardSectionTabs({ items }: BoardSectionTabsProps) {
  return (
    <div className="flex flex-wrap gap-2">
      {items.map((item) => (
        <NavLink
          key={item.to}
          to={item.to}
          className={({ isActive }) =>
            `rounded-md border px-3 py-2 text-sm transition-colors ${
              isActive
                ? "border-emerald-500/40 bg-emerald-500/10 text-emerald-200"
                : "border-[var(--shell-border)] bg-[var(--shell-panel)] text-[var(--shell-text-muted)] hover:border-[var(--shell-border-strong)] hover:text-[var(--shell-text)]"
            }`
          }
        >
          {item.label}
        </NavLink>
      ))}
    </div>
  );
}
