import { useRef, useEffect } from "react";

interface CompetitorPopoverProps {
  competitor: {
    name: string;
    domain?: string;
    description?: string;
    features?: string[];
    positioning?: string;
    strengths?: string;
    weaknesses?: string;
    location?: string;
    source?: string;
  };
  position: { x: number; y: number };
}

export function CompetitorPopover({ competitor, position }: CompetitorPopoverProps) {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!ref.current) return;
    const el = ref.current;
    const rect = el.getBoundingClientRect();
    if (rect.right > window.innerWidth) {
      el.style.left = `${position.x - rect.width - 8}px`;
    }
    if (rect.bottom > window.innerHeight) {
      el.style.top = `${position.y - rect.height - 8}px`;
    }
  }, [position]);

  const hasStrengths = !!competitor.strengths;
  const hasWeaknesses = !!competitor.weaknesses;
  const borderColor = hasStrengths && !hasWeaknesses
    ? "border-[var(--shell-positive)]/40"
    : hasWeaknesses && !hasStrengths
      ? "border-[var(--shell-danger)]/40"
      : "border-[var(--shell-border)]";

  return (
    <div
      ref={ref}
      className={`fixed z-[9999] w-72 rounded-xl border ${borderColor} bg-[var(--shell-panel)] p-4 shadow-xl`}
      style={{ top: position.y + 8, left: position.x + 8 }}
    >
      <div className="flex items-center justify-between gap-2">
        <div className="text-sm font-semibold text-[var(--shell-text)]">{competitor.name}</div>
        {competitor.source && (
          <span className="rounded-full bg-[var(--shell-panel-strong)] px-2 py-0.5 text-[9px] text-[var(--shell-text-muted)]">{competitor.source}</span>
        )}
      </div>

      {competitor.domain && <div className="mt-0.5 text-[11px] text-[var(--shell-text-muted)]">{competitor.domain}</div>}

      {competitor.description && (
        <div className="mt-2 text-xs leading-relaxed text-[var(--shell-text-muted)]">{competitor.description}</div>
      )}

      {competitor.features && competitor.features.length > 0 && (
        <div className="mt-2 flex flex-wrap gap-1">
          {competitor.features.slice(0, 6).map((f) => (
            <span key={f} className="rounded bg-[var(--shell-panel-strong)] px-1.5 py-0.5 text-[10px] text-[var(--shell-text-muted)]">{f}</span>
          ))}
        </div>
      )}

      {competitor.strengths && (
        <div className="mt-2">
          <div className="text-[10px] uppercase tracking-[0.1em] text-[var(--shell-positive)]">Strengths</div>
          <div className="mt-0.5 text-[11px] leading-relaxed text-[var(--shell-text)]">{competitor.strengths}</div>
        </div>
      )}

      {competitor.weaknesses && (
        <div className="mt-2">
          <div className="text-[10px] uppercase tracking-[0.1em] text-[var(--shell-danger)]">Weaknesses</div>
          <div className="mt-0.5 text-[11px] leading-relaxed text-[var(--shell-text)]">{competitor.weaknesses}</div>
        </div>
      )}

      {competitor.positioning && (
        <div className="mt-2">
          <div className="text-[10px] uppercase tracking-[0.1em] text-[var(--shell-text-soft)]">Positioning</div>
          <div className="mt-0.5 text-[11px] leading-relaxed text-[var(--shell-text-muted)]">{competitor.positioning}</div>
        </div>
      )}

      {competitor.location && (
        <div className="mt-2 text-[11px] text-[var(--shell-text-soft)]">{competitor.location}</div>
      )}
    </div>
  );
}
