import { useState, useRef, useEffect } from "react";
import { useParams } from "react-router-dom";
import { Send } from "lucide-react";
import { useCommand } from "../hooks/useCommand";
import { listLlmAnswers } from "../db/boards";

interface Message {
  id: string;
  role: "user" | "cmo";
  content: string;
  timestamp: number;
}

const GREETING: Message = {
  id: "greeting",
  role: "cmo",
  content:
    "Hi, I'm your AI CMO. Ask me anything about your brand, SEO strategy, GEO optimization, or competitors.\n\nI can help with:\n- Content strategy and recommendations\n- Keyword analysis insights\n- Competitive positioning\n- GEO visibility improvements",
  timestamp: Date.now(),
};

export function Chat() {
  const { id } = useParams<{ id: string }>();
  const [input, setInput] = useState("");
  const [messages, setMessages] = useState<Message[]>([GREETING]);
  const { execute, isRunning, status, result, reset } = useCommand(id);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!id) return;
    listLlmAnswers(id, 20).then((answers) => {
      if (answers.length === 0) return;
      const history: Message[] = answers
        .reverse()
        .flatMap((a: any) => {
          const out: Message[] = [];
          if (a.question) out.push({ id: `q-${a.id}`, role: "user", content: a.question, timestamp: a.createdAt?.toMillis?.() ?? Date.now() });
          if (a.answer) out.push({ id: `a-${a.id}`, role: "cmo", content: a.answer, timestamp: a.createdAt?.toMillis?.() ?? Date.now() });
          return out;
        });
      if (history.length > 0) setMessages([GREETING, ...history]);
    });
  }, [id]);

  useEffect(() => {
    if (status === "complete" && result) {
      const answer = (result as any).answer || (result as any).text || JSON.stringify(result);
      setMessages((prev) => [
        ...prev,
        { id: `cmo-${Date.now()}`, role: "cmo", content: answer, timestamp: Date.now() },
      ]);
      reset();
    }
  }, [status, result, reset]);

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: "smooth" });
  }, [messages, isRunning]);

  function handleSend(e: React.FormEvent) {
    e.preventDefault();
    const text = input.trim();
    if (!text || isRunning) return;

    setMessages((prev) => [
      ...prev,
      { id: `user-${Date.now()}`, role: "user", content: text, timestamp: Date.now() },
    ]);
    setInput("");
    execute("ask_llm", { question: text });
  }

  return (
    <div className="mx-auto flex h-[calc(100vh-4rem)] max-w-[900px] flex-col">
      <header className="shrink-0 pb-4">
        <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">AI Assistant</div>
        <h1 className="mt-2 text-3xl font-semibold text-[var(--shell-text)]">Talk to AI CMO</h1>
      </header>

      <div ref={scrollRef} className="flex-1 space-y-4 overflow-y-auto rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.role === "user" ? "justify-end" : "justify-start"}`}>
            <div
              className={`max-w-[70%] whitespace-pre-wrap rounded-2xl px-4 py-3 text-sm leading-relaxed ${
                msg.role === "user"
                  ? "bg-[var(--shell-accent)] text-white"
                  : "border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)]"
              }`}
            >
              {msg.content}
            </div>
          </div>
        ))}
        {isRunning && (
          <div className="flex justify-start">
            <div className="flex items-center gap-2 rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3 text-sm text-[var(--shell-text-soft)]">
              <span className="inline-block h-2 w-2 animate-pulse rounded-full bg-[var(--shell-accent)]" />
              Thinking...
            </div>
          </div>
        )}
      </div>

      <form onSubmit={handleSend} className="mt-4 flex gap-3">
        <input
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="Ask your CMO anything..."
          className="shell-input flex-1 rounded-xl px-4 py-3 text-sm"
        />
        <button
          type="submit"
          disabled={!input.trim() || isRunning}
          className="shell-button-primary grid h-12 w-12 shrink-0 place-items-center rounded-xl disabled:opacity-40"
        >
          <Send className="h-4 w-4" />
        </button>
      </form>
    </div>
  );
}
