import { useEffect, useState } from "react";
import { Link, useParams } from "react-router-dom";
import { listSeoAudits, getDocument } from "../db/boards";
import { useCommand } from "../hooks/useCommand";

interface Violation {
  rule: string;
  file: string;
  severity: "error" | "warning";
  message: string;
  suggestion?: string;
}

interface SeoAuditData {
  score: number;
  geoScore: number;
  errors: number;
  warnings: number;
  totalViolations: number;
  violations: Violation[];
  categories: Record<string, { errors: number; warnings: number }>;
}

function severityLabel(v: Violation) {
  return v.severity === "error" ? "긴급" : "중요";
}

export function Problems() {
  const { id } = useParams<{ id: string }>();
  const [audit, setAudit] = useState<SeoAuditData | null>(null);
  const [loading, setLoading] = useState(true);
  const cmd = useCommand(id);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    Promise.all([
      listSeoAudits(id, 1),
      getDocument(id, "seo-audit"),
    ]).then(([audits]) => {
      if (audits[0]) setAudit(audits[0] as unknown as SeoAuditData);
      setLoading(false);
    });
  }, [id]);

  const violations = audit?.violations ?? [];
  const sorted = [...violations].sort((a, b) => {
    if (a.severity === "error" && b.severity !== "error") return -1;
    if (a.severity !== "error" && b.severity === "error") return 1;
    return 0;
  });

  const high = sorted.filter((v) => v.severity === "error");
  const geoScore = audit?.geoScore ?? 0;

  const handleReanalyze = async () => {
    await cmd.execute("run_seo_audit");
    if (id) {
      const audits = await listSeoAudits(id, 1);
      if (audits[0]) setAudit(audits[0] as unknown as SeoAuditData);
    }
  };

  if (loading) {
    return (
      <div className="flex min-h-[40vh] items-center justify-center text-[var(--shell-text-muted)]">
        데이터 로딩 중...
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-[1400px] space-y-6">
      <header className="flex items-end justify-between gap-4">
        <div>
          <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">
            Problem Solving
          </div>
          <h1 className="mt-2 text-3xl font-semibold text-[var(--shell-text)]">
            Problems
          </h1>
          <p className="mt-2 text-sm text-[var(--shell-text-muted)]">
            SEO/GEO 최적화를 막는 문제를 우선순위, 영향도 기준으로 정리합니다.
          </p>
        </div>
        <button
          type="button"
          onClick={handleReanalyze}
          disabled={cmd.isRunning}
          className="shell-transition rounded-xl border border-[var(--shell-warning)]/40 bg-[var(--shell-warning)]/10 px-4 py-2.5 text-sm text-[var(--shell-warning)] disabled:opacity-50"
        >
          {cmd.isRunning ? "재분석 중..." : "문제 재분석"}
        </button>
      </header>

      {/* Metric cards */}
      <section className="grid gap-3 md:grid-cols-4">
        <MetricCard label="미해결 문제" value={`${sorted.length}`} />
        <MetricCard
          label="긴급 문제"
          value={`${high.length}`}
          tone="danger"
        />
        <MetricCard
          label="경고"
          value={`${sorted.length - high.length}`}
          tone="warning"
        />
        <MetricCard
          label="GEO 점수"
          value={`${geoScore}`}
          tone="positive"
        />
      </section>

      {/* Category breakdown */}
      {audit?.categories && Object.keys(audit.categories).length > 0 && (
        <section className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
          <div className="text-[11px] uppercase tracking-[0.18em] text-[var(--shell-text-soft)]">
            카테고리별 현황
          </div>
          <div className="mt-3 flex flex-wrap gap-3">
            {Object.entries(audit.categories).map(([cat, counts]) => (
              <div
                key={cat}
                className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-2.5"
              >
                <div className="text-sm font-medium text-[var(--shell-text)]">
                  {cat}
                </div>
                <div className="mt-1 text-xs text-[var(--shell-text-soft)]">
                  <span className="text-[var(--shell-danger)]">
                    {counts.errors} 오류
                  </span>
                  {" / "}
                  <span className="text-[var(--shell-warning)]">
                    {counts.warnings} 경고
                  </span>
                </div>
              </div>
            ))}
          </div>
        </section>
      )}

      {/* Violation list */}
      <section className="grid gap-4 lg:grid-cols-2">
        {sorted.length > 0 ? (
          sorted.map((v, i) => (
            <article
              key={`${v.rule}-${i}`}
              className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]"
            >
              <div className="flex items-start justify-between gap-4">
                <div className="min-w-0">
                  <div className="flex flex-wrap items-center gap-2">
                    <span
                      className={`rounded-full px-2.5 py-1 text-[11px] ${
                        v.severity === "error"
                          ? "bg-[var(--shell-danger)]/15 text-[var(--shell-danger)]"
                          : "bg-[var(--shell-warning)]/15 text-[var(--shell-warning)]"
                      }`}
                    >
                      {severityLabel(v)}
                    </span>
                    <span className="text-[11px] uppercase text-[var(--shell-text-soft)]">
                      {v.rule}
                    </span>
                  </div>
                  <h2 className="mt-3 text-base font-semibold text-[var(--shell-text)]">
                    {v.message}
                  </h2>
                  {v.file && (
                    <div className="mt-1 truncate text-xs text-[var(--shell-text-soft)]">
                      {v.file}
                    </div>
                  )}
                </div>
              </div>
              {v.suggestion && (
                <div className="mt-4 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3 text-sm leading-6 text-[var(--shell-text-muted)]">
                  {v.suggestion}
                </div>
              )}
              <div className="mt-4 flex items-center justify-end">
                <Link
                  to={`/board/${id}/actions`}
                  className="rounded-xl border border-[var(--shell-accent)]/40 bg-[var(--shell-accent)]/10 px-3 py-1.5 text-xs text-[var(--shell-accent)]"
                >
                  액션으로 전환
                </Link>
              </div>
            </article>
          ))
        ) : (
          <div className="shell-transition rounded-[18px] border border-dashed border-[var(--shell-border)] bg-[var(--shell-panel)] p-8 text-center text-sm text-[var(--shell-text-muted)] lg:col-span-2">
            현재 표시할 문제가 없습니다. 재분석을 실행하면 최신 데이터
            기준으로 다시 판단합니다.
          </div>
        )}
      </section>
    </div>
  );
}

function MetricCard({
  label,
  value,
  tone = "neutral",
}: {
  label: string;
  value: string;
  tone?: "neutral" | "danger" | "warning" | "positive";
}) {
  const colorClass =
    tone === "danger"
      ? "text-[var(--shell-danger)]"
      : tone === "warning"
        ? "text-[var(--shell-warning)]"
        : tone === "positive"
          ? "text-[var(--shell-positive)]"
          : "text-[var(--shell-text)]";
  return (
    <div className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
      <div className="text-[11px] uppercase tracking-[0.18em] text-[var(--shell-text-soft)]">
        {label}
      </div>
      <div className={`mt-2 text-3xl font-semibold ${colorClass}`}>{value}</div>
    </div>
  );
}
