import { useState, useRef } from "react";
import type { Board } from "../../../db/collections";

interface DiagnosisIconBarProps {
  board: Board | null;
  onOpenRobotsModal: () => void;
}

type IconStatus = "green" | "orange" | "red" | "gray";

interface IconItem {
  key: string;
  label: string;
  fullName: string;
  desc: string;
  status: IconStatus;
  detail?: string;
}

export function DiagnosisIconBar({ board, onOpenRobotsModal }: DiagnosisIconBarProps) {
  const [hoveredIcon, setHoveredIcon] = useState<string | null>(null);
  const [robotsTab, setRobotsTab] = useState<"current" | "recommended">("current");
  const hoverTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const si = board?.siteInfo;
  const det = si?.trackingStatus;
  const gb = si?.googleBusiness;
  const aiCrawlers = si?.aiCrawlers;
  const sf = si?.siteFiles;
  const meta = det?.meta || {};

  const blockedBots = aiCrawlers?.crawlers?.filter((c) => c.status === "blocked").map((c) => c.name) || [];

  const items: IconItem[] = [
    {
      key: "ga4", label: "GA4", fullName: "Google Analytics",
      desc: "AI 검색에서 유입되는 트래픽을 채널별로 분석합니다.",
      status: (det?.ga4Id || det?.gtmId) ? "orange" : det ? "red" : "gray",
      detail: det?.ga4Id || (det?.gtmId ? `${det.gtmId} (GTM)` : undefined),
    },
    {
      key: "nsv", label: "NSV", fullName: "Naver Site Verification",
      desc: "네이버에 사이트 소유권을 인증합니다.",
      status: meta["naver-site-verification"] ? "green" : det ? "red" : "gray",
    },
    {
      key: "gsv", label: "GSV", fullName: "Google Site Verification",
      desc: "Google에 사이트 소유권을 인증합니다.",
      status: meta["google-site-verification"] ? "green" : det ? "red" : "gray",
    },
    {
      key: "gsc", label: "GSC", fullName: "Google Search Console",
      desc: "실제 검색 키워드, 노출 수, 클릭 수 데이터를 제공합니다.",
      status: det?.hasSearchConsole ? "green" : det ? "orange" : "gray",
    },
    {
      key: "gbp", label: "GBP", fullName: "Google Business Profile",
      desc: "Google Maps와 지역 검색에 비즈니스를 노출합니다.",
      status: gb?.found ? "green" : gb ? "red" : "gray",
    },
    (() => {
      let status: IconStatus = "gray";
      let desc = "검색엔진과 AI 봇의 크롤링 접근을 제어합니다.";
      if (sf?.robots) {
        if (!sf.robots.exists) {
          status = "red";
          desc += "\n\nrobots.txt가 없습니다.";
        } else if (aiCrawlers && blockedBots.length > 0) {
          status = "orange";
          desc += `\n\n${blockedBots.length}개 AI 봇 차단: ${blockedBots.join(", ")}`;
        } else if (sf.robots.needsImprovement) {
          status = "orange";
        } else {
          status = "green";
        }
      }
      return { key: "robots", label: "robots", fullName: "robots.txt", desc, status };
    })(),
    (() => {
      let status: IconStatus = "gray";
      let desc = "검색엔진에게 페이지 목록을 구조화하여 제공합니다.";
      if (sf?.sitemap) {
        if (!sf.sitemap.exists) { status = "red"; desc += "\n\nsitemap.xml이 없습니다."; }
        else if (sf.sitemap.outdated || !sf.sitemap.hasLastmod) { status = "orange"; desc += "\n\nlastmod 업데이트 필요."; }
        else { status = "green"; }
      }
      return { key: "sitemap", label: "sitemap", fullName: "sitemap.xml", desc, status };
    })(),
    {
      key: "llms", label: "llms.txt", fullName: "llms.txt",
      desc: "AI 모델에게 사이트 구조를 요약합니다.",
      status: sf?.llms ? (sf.llms.exists ? "green" : "red") : "gray",
    },
    {
      key: "rss", label: "RSS", fullName: "RSS Feed",
      desc: "AI 크롤러가 최신 콘텐츠를 수집하는 데 활용합니다.",
      status: sf?.rss ? (sf.rss.exists ? "green" : "red") : "gray",
    },
  ];

  const statusDot = (s: IconStatus) =>
    s === "green" ? "bg-[var(--shell-positive)]"
    : s === "orange" ? "bg-[var(--shell-warning)]"
    : s === "red" ? "bg-[var(--shell-danger)]"
    : "bg-[var(--shell-text-soft)] animate-pulse";

  const statusBorder = (s: IconStatus) =>
    s === "green" ? "border-[var(--shell-positive)]/30"
    : s === "orange" ? "border-[var(--shell-warning)]/30"
    : s === "red" ? "border-[var(--shell-danger)]/30"
    : "border-[var(--shell-border)]";

  const statusLabel = (s: IconStatus, key: string) =>
    s === "green" ? "정상"
    : s === "orange" ? (key === "ga4" ? "미연동" : key === "gsc" ? "확인안됨" : "개선 필요")
    : s === "red" ? "미설치"
    : "확인 중...";

  const statusTextColor = (s: IconStatus) =>
    s === "green" ? "text-[var(--shell-positive)]"
    : s === "orange" ? "text-[var(--shell-warning)]"
    : s === "red" ? "text-[var(--shell-danger)]"
    : "text-[var(--shell-text-soft)]";

  const socialLinks = si?.socialLinks || {};

  const isSiteFile = (key: string) => ["robots", "sitemap", "llms"].includes(key);
  const fileContent = (key: string) => {
    if (key === "robots") return sf?.robots?.content || null;
    if (key === "sitemap") return sf?.sitemap?.content || null;
    if (key === "llms") return sf?.llms?.content || null;
    return null;
  };

  return (
    <div className="mb-3 flex items-center gap-1.5 border-b border-[var(--shell-border)] pb-2">
      <div className="flex min-w-0 flex-1 flex-wrap gap-1">
        {items.map((item) => {
          const hasFile = isSiteFile(item.key) && (fileContent(item.key) || (item.key === "robots" && aiCrawlers?.recommendedRobotsTxt));
          return (
            <div
              key={item.key}
              className={`relative flex h-7 w-7 cursor-default items-center justify-center rounded-md border bg-[var(--shell-panel-soft)] ${statusBorder(item.status)}`}
              onClick={item.key === "robots" ? onOpenRobotsModal : undefined}
              onMouseEnter={() => {
                if (hoverTimeoutRef.current) clearTimeout(hoverTimeoutRef.current);
                setHoveredIcon(item.key);
              }}
              onMouseLeave={() => {
                hoverTimeoutRef.current = setTimeout(() => setHoveredIcon(null), 150);
              }}
            >
              <span className="text-[8px] font-medium leading-none text-[var(--shell-text-muted)]">{item.label}</span>
              <span className={`absolute -right-0.5 -top-0.5 h-2 w-2 rounded-full ${statusDot(item.status)}`} />

              {hoveredIcon === item.key && (
                <div
                  className={`fixed z-[9999] ${hasFile ? "w-96" : "w-56"}`}
                  style={{ top: "var(--tt-top)", left: "var(--tt-left)" }}
                  onMouseEnter={() => { if (hoverTimeoutRef.current) clearTimeout(hoverTimeoutRef.current); }}
                  onMouseLeave={() => { hoverTimeoutRef.current = setTimeout(() => setHoveredIcon(null), 150); }}
                  ref={(el) => {
                    if (!el) return;
                    const parent = el.parentElement;
                    if (!parent) return;
                    const rect = parent.getBoundingClientRect();
                    el.style.setProperty("--tt-top", `${rect.bottom + 4}px`);
                    const maxLeft = window.innerWidth - (hasFile ? 400 : 240);
                    el.style.setProperty("--tt-left", `${Math.max(8, Math.min(rect.left, maxLeft))}px`);
                  }}
                >
                  <div className="h-1" />
                  <div className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel)] p-2.5 text-left shadow-xl">
                    <div className="mb-1.5 flex items-center justify-between">
                      <span className="text-[11px] font-semibold text-[var(--shell-text)]">{item.fullName}</span>
                      <span className={`text-[10px] font-medium ${statusTextColor(item.status)}`}>
                        {statusLabel(item.status, item.key)}
                      </span>
                    </div>
                    <div className="whitespace-pre-line text-[10px] leading-relaxed text-[var(--shell-text-muted)]">{item.desc}</div>

                    {item.key === "gbp" && gb?.found && (
                      <div className="mt-1.5 border-t border-[var(--shell-border)] pt-1.5">
                        <div className="text-[10px] font-medium text-[var(--shell-text)]">{gb.name}</div>
                        <div className="mt-0.5 flex items-center gap-1.5">
                          {gb.rating != null && <span className="text-[10px] text-yellow-400">* {gb.rating}</span>}
                          {gb.reviewCount != null && <span className="text-[10px] font-semibold text-[var(--shell-accent)]">({gb.reviewCount.toLocaleString()} reviews)</span>}
                        </div>
                        {gb.address && <div className="mt-0.5 text-[10px] text-[var(--shell-text-muted)]">{gb.address}</div>}
                      </div>
                    )}

                    {item.detail && item.key !== "gbp" && (
                      <div className="mt-1.5 whitespace-pre-line border-t border-[var(--shell-border)] pt-1.5 text-[10px] text-[var(--shell-text)]">{item.detail}</div>
                    )}

                    {hasFile && (
                      <div className="mt-2 border-t border-[var(--shell-border)] pt-2">
                        {item.key === "robots" && aiCrawlers?.recommendedRobotsTxt ? (
                          <>
                            <div className="mb-2 flex gap-1">
                              <button onClick={() => setRobotsTab("current")} className={`rounded px-2 py-0.5 text-[10px] ${robotsTab === "current" ? "bg-[var(--shell-panel-strong)] text-[var(--shell-text)]" : "text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"}`}>현재</button>
                              <button onClick={() => setRobotsTab("recommended")} className={`rounded px-2 py-0.5 text-[10px] ${robotsTab === "recommended" ? "bg-[color-mix(in_srgb,var(--shell-positive)_20%,transparent)] text-[var(--shell-positive)]" : "text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"}`}>추천</button>
                            </div>
                            <pre className="max-h-[200px] overflow-y-auto whitespace-pre-wrap rounded bg-[var(--shell-main)] p-2 text-[9px] leading-relaxed text-[var(--shell-text)]">
                              {robotsTab === "current" ? (fileContent(item.key) || "파일 없음") : aiCrawlers.recommendedRobotsTxt}
                            </pre>
                          </>
                        ) : fileContent(item.key) ? (
                          <pre className="max-h-[200px] overflow-y-auto whitespace-pre-wrap rounded bg-[var(--shell-main)] p-2 text-[9px] leading-relaxed text-[var(--shell-text)]">
                            {fileContent(item.key)}
                          </pre>
                        ) : null}
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>

      {Object.keys(socialLinks).length > 0 && (
        <div className="flex shrink-0 items-center gap-1 border-l border-[var(--shell-border)] pl-1.5">
          {Object.entries(socialLinks).map(([k, v]) => (
            <a key={k} href={v} target="_blank" rel="noopener noreferrer" title={k}
              className="flex h-7 w-7 items-center justify-center rounded-md border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] text-[9px] text-[var(--shell-text-muted)] transition-colors hover:bg-[var(--shell-panel-strong)]"
            >
              {k.slice(0, 2)}
            </a>
          ))}
        </div>
      )}
    </div>
  );
}
