import { useEffect, useMemo, useState } from "react";
import { Link, useParams } from "react-router-dom";
import { BoardSectionTabs } from "../components/BoardSectionTabs";
import {
  getDocument,
  listSeoAudits,
  listGeoProbes,
  listCompetitors,
} from "../db/boards";

const ANALYSIS_SECTIONS = [
  { key: "website", label: "웹사이트 분석" },
  { key: "media-community", label: "언론/커뮤니티" },
  { key: "keywords", label: "키워드" },
  { key: "viral", label: "바이럴" },
  { key: "competitors", label: "경쟁사" },
] as const;

type SectionKey = (typeof ANALYSIS_SECTIONS)[number]["key"];

function isSection(v?: string): v is SectionKey {
  return ANALYSIS_SECTIONS.some((s) => s.key === v);
}

function compactNumber(value?: number | null) {
  if (!value) return "0";
  if (value >= 1_000_000) return `${(value / 1_000_000).toFixed(1)}M`;
  if (value >= 1_000) return `${Math.round(value / 100) / 10}K`;
  return value.toLocaleString();
}

function sectionTitle(s: SectionKey) {
  switch (s) {
    case "website": return "웹사이트 / SEO / GEO";
    case "media-community": return "언론 / 커뮤니티 / 외부 신뢰";
    case "keywords": return "Google + Naver 키워드 레이어";
    case "viral": return "SNS / 바이럴 반응 레이어";
    case "competitors": return "경쟁사 및 시장 비교";
  }
}

function sectionDescription(s: SectionKey) {
  switch (s) {
    case "website": return "사이트 구조, 기술 신호, SEO/GEO 점수와 핵심 문제를 함께 봅니다.";
    case "media-community": return "언론, 블로그, 커뮤니티, 지도/플레이스 등 외부 신뢰 채널의 존재감을 확인합니다.";
    case "keywords": return "Google/Naver 수요, 키워드 묶음, 질문별 검색량과 AI 언급 가능성을 함께 봅니다.";
    case "viral": return "광고 데이터는 제외하고, SNS 채널 권한/초안/배포 준비 상태를 봅니다.";
    case "competitors": return "Top 경쟁사와 비교해 우리 브랜드의 SEO/GEO 상대 위치와 빈틈을 파악합니다.";
  }
}

export function AnalysisHub() {
  const { id, section } = useParams<{ id: string; section?: string }>();
  const active: SectionKey = isSection(section) ? section : "website";

  const [loading, setLoading] = useState(true);
  const [seoDoc, setSeoDoc] = useState<Record<string, any> | null>(null);
  const [geoDoc, setGeoDoc] = useState<Record<string, any> | null>(null);
  const [keywordDoc, setKeywordDoc] = useState<Record<string, any> | null>(null);
  const [competitorDoc, setCompetitorDoc] = useState<Record<string, any> | null>(null);
  const [externalDoc, setExternalDoc] = useState<Record<string, any> | null>(null);
  const [seoAudits, setSeoAudits] = useState<Array<Record<string, any>>>([]);
  const [geoProbes, setGeoProbes] = useState<Array<Record<string, any>>>([]);
  const [competitors, setCompetitors] = useState<Array<Record<string, any>>>([]);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    Promise.all([
      getDocument(id, "seo-audit"),
      getDocument(id, "geo-visibility"),
      getDocument(id, "keyword-strategy"),
      getDocument(id, "competitor-analysis"),
      getDocument(id, "external-sources-analysis"),
      getDocument(id, "product-info") as Promise<Record<string, any> | null>,
      listSeoAudits(id, 1),
      listGeoProbes(id),
      listCompetitors(id),
    ]).then(([seo, geo, kw, comp, ext, _brand, audits, probes, comps]) => {
      setSeoDoc(seo as Record<string, any>);
      setGeoDoc(geo as Record<string, any>);
      setKeywordDoc(kw as Record<string, any>);
      setCompetitorDoc(comp as Record<string, any>);
      setExternalDoc(ext as Record<string, any>);
      setSeoAudits(audits);
      setGeoProbes(probes);
      setCompetitors(comps);
      setLoading(false);
    });
  }, [id]);

  const tabs = ANALYSIS_SECTIONS.map((item) => ({
    label: item.label,
    to: `/board/${id}/analysis/${item.key}`,
  }));

  const seoScore = seoDoc?.score ?? seoAudits[0]?.score ?? 0;
  const geoScore = seoDoc?.geoScore ?? geoDoc?.geoScore ?? 0;
  const violations = seoAudits[0]?.violations ?? [];
  const recommendations = useMemo(() => {
    return violations.slice(0, 6).map((v: any) => ({
      rule: v.rule,
      message: v.message,
      severity: v.severity,
      suggestion: v.suggestion ?? "",
    }));
  }, [violations]);

  const externalSources = useMemo(() => {
    const sources = externalDoc?.sources ?? [];
    return Array.isArray(sources) ? sources : [];
  }, [externalDoc]);

  const mediaSources = useMemo(
    () => externalSources.filter((s: any) =>
      ["news", "community", "naver_blog", "naver_place", "google_maps", "wikipedia", "namuwiki"].includes(s.sourceType ?? s.source_type ?? ""),
    ),
    [externalSources],
  );

  const externalTrustScore = externalDoc?.analysis?.trustScore ?? Math.min(100, mediaSources.filter((s: any) => s.exists).length * 15);

  const classifiedKeywords = keywordDoc?.classifiedKeywords ?? keywordDoc?.classified ?? null;
  const siteKeywords = classifiedKeywords?.site ?? [];
  const competitorKeywords = classifiedKeywords?.competitor ?? [];
  const recommendedKeywords = classifiedKeywords?.recommended ?? [];

  const geoVisibility = geoDoc ?? {};
  const mentionRate = geoVisibility.mentionRate ?? 0;
  const exposureRate = geoVisibility.exposureRate ?? 0;

  const autoCompetitors = competitorDoc?.competitors ?? [];
  const allCompetitors = autoCompetitors.length > 0 ? autoCompetitors : competitors;

  if (loading) {
    return (
      <div className="flex min-h-[40vh] items-center justify-center text-[var(--shell-text-muted)]">
        데이터 로딩 중...
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-[1400px] space-y-6">
      <header className="space-y-3">
        <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">
          Analysis
        </div>
        <div className="flex flex-col gap-3 lg:flex-row lg:items-end lg:justify-between">
          <div>
            <h1 className="text-3xl font-semibold text-[var(--shell-text)]">
              {sectionTitle(active)}
            </h1>
            <p className="mt-2 max-w-3xl text-sm text-[var(--shell-text-muted)]">
              {sectionDescription(active)}
            </p>
          </div>
          <div className="flex flex-wrap gap-2">
            <Link
              to={`/board/${id}/problems`}
              className="shell-transition rounded-xl border border-[var(--shell-warning)]/30 bg-[var(--shell-warning)]/10 px-3 py-2 text-sm text-[var(--shell-warning)]"
            >
              Problems 보기
            </Link>
            <Link
              to={`/board/${id}/actions`}
              className="shell-transition rounded-xl border border-[var(--shell-accent)]/30 bg-[var(--shell-accent)]/10 px-3 py-2 text-sm text-[var(--shell-accent)]"
            >
              Action으로 넘기기
            </Link>
          </div>
        </div>
        <BoardSectionTabs items={tabs} />
      </header>

      {active === "website" && (
        <WebsiteTab
          seoScore={seoScore}
          geoScore={geoScore}
          recommendations={recommendations}
          violations={violations}
        />
      )}

      {active === "media-community" && (
        <MediaTab
          mediaSources={mediaSources}
          trustScore={externalTrustScore}
          analysis={externalDoc?.analysis ?? {}}
        />
      )}

      {active === "keywords" && (
        <KeywordsTab
          siteKeywords={siteKeywords}
          competitorKeywords={competitorKeywords}
          recommendedKeywords={recommendedKeywords}
          mentionRate={mentionRate}
          exposureRate={exposureRate}
          geoProbes={geoProbes}
        />
      )}

      {active === "viral" && <ViralTab />}

      {active === "competitors" && (
        <CompetitorsTab
          seoScore={seoScore}
          geoScore={geoScore}
          autoCompetitors={allCompetitors}
          manualCompetitors={competitors}
        />
      )}
    </div>
  );
}

/* ─── Website Tab ─── */

function WebsiteTab({
  seoScore,
  geoScore,
  recommendations,
  violations,
}: {
  seoScore: number;
  geoScore: number;
  recommendations: Array<{ rule: string; message: string; severity: string; suggestion: string }>;
  violations: Array<Record<string, any>>;
}) {
  const websiteProblems = recommendations.slice(0, 5).map((r) => `${r.rule}: ${r.message}`);

  return (
    <div className="grid gap-4 xl:grid-cols-[1.35fr,0.95fr]">
      <div className="space-y-4">
        <div className="grid gap-3 md:grid-cols-4">
          <MetricCard label="SEO 점수" value={`${seoScore}`} hint="검색엔진 이해도" />
          <MetricCard label="GEO 점수" value={`${geoScore}`} hint="생성형 엔진 가시성" />
          <MetricCard
            label="오류"
            value={`${violations.filter((v: any) => v.severity === "error").length}`}
            hint="즉시 수정 필요"
            tone="danger"
          />
          <MetricCard
            label="경고"
            value={`${violations.filter((v: any) => v.severity === "warning").length}`}
            hint="개선 권장"
            tone="warning"
          />
        </div>

        <Panel title="핵심 진단" description="기술/콘텐츠 구조에서 먼저 고쳐야 할 항목입니다.">
          <div className="space-y-3">
            {recommendations.length > 0 ? (
              recommendations.map((r, i) => (
                <div
                  key={`${r.rule}-${i}`}
                  className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3"
                >
                  <div className="flex items-center justify-between gap-3">
                    <div className="text-sm font-medium text-[var(--shell-text)]">{r.rule}</div>
                    <span
                      className={`rounded-full px-2.5 py-1 text-[11px] ${
                        r.severity === "error"
                          ? "bg-[var(--shell-danger)]/15 text-[var(--shell-danger)]"
                          : "bg-[var(--shell-warning)]/15 text-[var(--shell-warning)]"
                      }`}
                    >
                      {r.severity === "error" ? "긴급" : "경고"}
                    </span>
                  </div>
                  <div className="mt-2 text-sm text-[var(--shell-text-muted)]">{r.message}</div>
                  {r.suggestion && (
                    <div className="mt-2 text-xs text-[var(--shell-text-soft)]">{r.suggestion}</div>
                  )}
                </div>
              ))
            ) : (
              <EmptyState text="진단 결과가 아직 없습니다. SEO 분석을 실행하면 항목이 표시됩니다." />
            )}
          </div>
        </Panel>
      </div>

      <Panel title="문제점 파악" description="분석 결과를 Action으로 넘기기 전 우선순위를 정합니다.">
        <IssueList
          items={
            websiteProblems.length > 0
              ? websiteProblems
              : ["분석 데이터가 아직 수집되지 않았습니다. 온보딩 후 자동으로 채워집니다."]
          }
        />
      </Panel>
    </div>
  );
}

/* ─── Media / Community Tab ─── */

function MediaTab({
  mediaSources,
  trustScore,
  analysis,
}: {
  mediaSources: Array<Record<string, any>>;
  trustScore: number;
  analysis: Record<string, any>;
}) {
  return (
    <div className="space-y-4">
      <div className="grid gap-3 md:grid-cols-3">
        <MetricCard label="외부 신뢰 점수" value={`${trustScore}`} hint="언론/커뮤니티/위키/지도 반영" />
        <MetricCard
          label="뉴스 언급"
          value={`${mediaSources.filter((s) => (s.sourceType ?? s.source_type) === "news" && s.exists).length}`}
          hint="언론/경제지 기준"
        />
        <MetricCard
          label="커뮤니티 존재"
          value={`${mediaSources.filter((s) => (s.sourceType ?? s.source_type) !== "news" && s.exists).length}`}
          hint="블로그/커뮤니티/플레이스/지도"
        />
      </div>

      <div className="grid gap-4 xl:grid-cols-[1.25fr,1fr]">
        <Panel title="외부 소스 맵" description="언론, 커뮤니티, 위키, 지도/플레이스 등 신뢰 레이어를 한 번에 봅니다.">
          <div className="grid gap-3 md:grid-cols-2">
            {mediaSources.length > 0 ? (
              mediaSources.slice(0, 8).map((source, index) => (
                <div
                  key={`${source.sourceType ?? source.source_type}-${index}`}
                  className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3"
                >
                  <div className="flex items-center justify-between gap-3">
                    <div className="text-sm font-medium text-[var(--shell-text)]">
                      {source.sourceName ?? source.source_name ?? source.sourceType ?? "소스"}
                    </div>
                    <div className="text-[11px] text-[var(--shell-text-soft)]">
                      {source.exists ? "발견" : "없음"}
                    </div>
                  </div>
                  <div className="mt-2 text-xs text-[var(--shell-text-soft)]">
                    {source.sourceUrl ?? source.source_url ?? source.sourceType ?? ""}
                  </div>
                  {source.snippet && (
                    <div className="mt-2 text-sm text-[var(--shell-text-muted)]">{source.snippet}</div>
                  )}
                </div>
              ))
            ) : (
              <EmptyState text="외부 신뢰 소스가 아직 정리되지 않았습니다. 재분석 후 언론/커뮤니티 레이어가 채워집니다." />
            )}
          </div>
        </Panel>

        <Panel title="문제점 파악" description="신뢰 소스가 부족한 경우 GEO 추천의 근거 밀도가 떨어집니다.">
          <IssueList
            items={
              (analysis.priorityActions ?? []).length > 0
                ? analysis.priorityActions
                : [
                    "브랜드 보도자료/기사/전문가 인터뷰가 부족하면 AI 인용 근거가 약해집니다.",
                    "네이버 블로그/플레이스/지도와 같은 로컬 레이어가 비어 있으면 커뮤니티 존재감이 낮게 잡힙니다.",
                    "위키/백과/업계 협회 등 3자 출처가 없으면 외부 신뢰 점수 상승이 제한됩니다.",
                  ]
            }
          />
        </Panel>
      </div>
    </div>
  );
}

/* ─── Keywords Tab ─── */

function KeywordsTab({
  siteKeywords,
  competitorKeywords,
  recommendedKeywords,
  mentionRate,
  exposureRate,
  geoProbes,
}: {
  siteKeywords: Array<Record<string, any>>;
  competitorKeywords: Array<Record<string, any>>;
  recommendedKeywords: Array<Record<string, any>>;
  mentionRate: number;
  exposureRate: number;
  geoProbes: Array<Record<string, any>>;
}) {
  const lowMentionProbes = useMemo(
    () =>
      geoProbes
        .filter((p: any) => (p.mentioned === false || p.mentionRate < 40))
        .slice(0, 5)
        .map((p: any) => `${p.question ?? p.query ?? "질문"} - 언급률 ${p.mentionRate ?? 0}%`),
    [geoProbes],
  );

  return (
    <div className="space-y-4">
      <div className="grid gap-3 md:grid-cols-4">
        <MetricCard label="사이트 키워드" value={`${siteKeywords.length}`} hint="크롤링 기반 추출" />
        <MetricCard label="경쟁사 키워드" value={`${competitorKeywords.length}`} hint="경쟁 분석 결과" />
        <MetricCard label="AI 노출률" value={`${exposureRate}%`} hint="AI 검색 결과 노출" />
        <MetricCard label="AI 언급률" value={`${mentionRate}%`} hint="브랜드 직접 언급" />
      </div>

      <div className="grid gap-4 xl:grid-cols-[1.1fr,1.2fr,0.9fr]">
        <Panel title="사이트 키워드" description="크롤링에서 추출된 핵심 키워드입니다.">
          <KeywordList
            items={siteKeywords.slice(0, 10).map((k: any) => ({
              keyword: k.keyword ?? k,
              value: k.totalMonthlyVolume ?? k.opportunity ?? 0,
              tag: "site",
            }))}
            emptyText="사이트 키워드가 아직 없습니다."
          />
        </Panel>

        <Panel title="추천 키워드" description="AI 분석 기반으로 추천된 키워드입니다.">
          <KeywordList
            items={recommendedKeywords.slice(0, 10).map((k: any) => ({
              keyword: k.keyword ?? k,
              value: k.totalMonthlyVolume ?? k.opportunity ?? 0,
              tag: "recommended",
            }))}
            emptyText="추천 키워드가 아직 없습니다."
          />
        </Panel>

        <Panel title="문제점 파악" description="검색량은 있는데 언급이 약한 질문을 먼저 잡습니다.">
          <IssueList
            items={
              lowMentionProbes.length > 0
                ? lowMentionProbes
                : [
                    "검색량이 있는 질문이어도 브랜드 언급률이 낮으면 GEO에서 기회를 놓치고 있습니다.",
                    "Google/Naver 키워드와 AI 질문 세트가 분리되면 Action 타깃팅이 약해집니다.",
                  ]
            }
          />
        </Panel>
      </div>

      {competitorKeywords.length > 0 && (
        <Panel title="경쟁사 키워드" description="경쟁사에서 발견된 키워드로, 우리에게 부족한 영역을 나타냅니다.">
          <KeywordList
            items={competitorKeywords.slice(0, 10).map((k: any) => ({
              keyword: k.keyword ?? k,
              value: k.totalMonthlyVolume ?? k.opportunity ?? 0,
              tag: "competitor",
            }))}
            emptyText=""
          />
        </Panel>
      )}
    </div>
  );
}

