/* ─── Competitors Tab ─── */

function CompetitorsTab({
  seoScore,
  geoScore,
  autoCompetitors,
  manualCompetitors,
}: {
  seoScore: number;
  geoScore: number;
  autoCompetitors: Array<Record<string, any>>;
  manualCompetitors: Array<Record<string, any>>;
}) {
  const competitorProblems = useMemo(() => {
    const items: string[] = [];
    autoCompetitors.slice(0, 3).forEach((c: any) => {
      items.push(
        `${c.name ?? c.domain ?? "경쟁사"} - SEO ${c.seoScore ?? "?"} / GEO ${c.geoScore ?? "?"} / 종합 ${c.overallScore ?? "?"}`,
      );
    });
    if (manualCompetitors.length === 0) {
      items.push("수동 등록된 핵심 경쟁사가 아직 없습니다.");
    }
    return items;
  }, [autoCompetitors, manualCompetitors]);

  return (
    <div className="space-y-4">
      <div className="grid gap-3 md:grid-cols-3">
        <MetricCard label="우리 SEO" value={`${seoScore}`} hint="브랜드 현재 점수" />
        <MetricCard label="우리 GEO" value={`${geoScore}`} hint="브랜드 현재 점수" />
        <MetricCard
          label="비교 경쟁사"
          value={`${autoCompetitors.length || manualCompetitors.length}`}
          hint="Top 경쟁사 + 수동 등록"
        />
      </div>

      <div className="grid gap-4 xl:grid-cols-[1.2fr,1fr]">
        <Panel title="Top 경쟁사 보드" description="검색/AI 노출에서 자주 보이는 경쟁사를 우선 정렬합니다.">
          <div className="space-y-3">
            {autoCompetitors.length > 0 ? (
              autoCompetitors.slice(0, 6).map((c: any, i) => (
                <div
                  key={c.name ?? `comp-${i}`}
                  className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3"
                >
                  <div className="flex items-center justify-between gap-3">
                    <div>
                      <div className="text-sm font-medium text-[var(--shell-text)]">
                        {c.name ?? c.domain ?? "경쟁사"}
                      </div>
                      <div className="mt-1 text-xs text-[var(--shell-text-soft)]">
                        {c.domain ?? c.source ?? ""}
                      </div>
                    </div>
                    <div className="text-right text-sm text-[var(--shell-text-muted)]">
                      {c.overallScore != null && <div>종합 {c.overallScore}</div>}
                      <div className="text-xs text-[var(--shell-text-soft)]">
                        SEO {c.seoScore ?? "?"} / GEO {c.geoScore ?? "?"}
                      </div>
                    </div>
                  </div>
                </div>
              ))
            ) : (
              <EmptyState text="자동 분석으로 정리된 경쟁사 보드가 아직 없습니다." />
            )}
          </div>
        </Panel>

        <Panel title="문제점 파악" description="경쟁사 축은 GEO 방향을 잡는 데 반드시 필요합니다.">
          <IssueList items={competitorProblems} />
        </Panel>
      </div>

      <Panel title="수동 등록 경쟁사" description="고객이 중요하게 보는 경쟁사는 자동 탐지와 별개로 반드시 유지합니다.">
        <div className="space-y-3">
          {manualCompetitors.length > 0 ? (
            manualCompetitors.map((c: any) => (
              <div
                key={c.id}
                className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3"
              >
                <div className="text-sm font-medium text-[var(--shell-text)]">
                  {c.name ?? c.domain ?? "경쟁사"}
                </div>
                <div className="mt-1 text-xs text-[var(--shell-text-soft)]">
                  {c.url ?? c.domain ?? c.source ?? ""}
                </div>
                {c.description && (
                  <div className="mt-2 text-sm text-[var(--shell-text-muted)]">{c.description}</div>
                )}
              </div>
            ))
          ) : (
            <EmptyState text="수동 등록된 경쟁사가 없습니다. 고객 인풋에서 중요 경쟁사를 명시하면 재분석에 더 강하게 반영됩니다." />
          )}
        </div>
      </Panel>
    </div>
  );
}

/* ─── Shared Components ─── */

function MetricCard({
  label,
  value,
  hint,
  tone = "neutral",
}: {
  label: string;
  value: string;
  hint: string;
  tone?: "neutral" | "danger" | "warning" | "positive";
}) {
  const colorClass =
    tone === "danger"
      ? "text-[var(--shell-danger)]"
      : tone === "warning"
        ? "text-[var(--shell-warning)]"
        : tone === "positive"
          ? "text-[var(--shell-positive)]"
          : "text-[var(--shell-text)]";
  return (
    <div className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-4 shadow-[var(--shell-shadow)]">
      <div className="text-[11px] uppercase tracking-[0.12em] text-[var(--shell-text-soft)]">{label}</div>
      <div className={`mt-2 text-3xl font-semibold ${colorClass}`}>{value}</div>
      <div className="mt-2 text-xs text-[var(--shell-text-muted)]">{hint}</div>
    </div>
  );
}

function Panel({
  title,
  description,
  children,
}: {
  title: string;
  description: string;
  children: React.ReactNode;
}) {
  return (
    <section className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
      <div>
        <div className="text-lg font-semibold text-[var(--shell-text)]">{title}</div>
        <div className="mt-1 text-sm text-[var(--shell-text-muted)]">{description}</div>
      </div>
      <div className="mt-4">{children}</div>
    </section>
  );
}

function IssueList({ items }: { items: string[] }) {
  return (
    <div className="space-y-2">
      {items.length > 0 ? (
        items.map((item, i) => (
          <div
            key={`issue-${i}`}
            className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-sm text-[var(--shell-text-muted)]"
          >
            {item}
          </div>
        ))
      ) : (
        <EmptyState text="아직 정리된 문제점이 없습니다." />
      )}
    </div>
  );
}

function KeywordList({
  items,
  emptyText,
}: {
  items: Array<{ keyword: string; value?: number; tag?: string }>;
  emptyText: string;
}) {
  if (items.length === 0) {
    return <EmptyState text={emptyText} />;
  }
  return (
    <div className="space-y-2">
      {items.map((item, index) => (
        <div
          key={`${item.keyword}-${index}`}
          className="flex items-center justify-between gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2"
        >
          <div>
            <div className="text-sm font-medium text-[var(--shell-text)]">{item.keyword}</div>
            {item.tag && (
              <div className="mt-1 text-[11px] text-[var(--shell-text-soft)]">{item.tag}</div>
            )}
          </div>
          <div className="text-sm text-[var(--shell-text-muted)]">{compactNumber(item.value)}</div>
        </div>
      ))}
    </div>
  );
}

function EmptyState({ text }: { text: string }) {
  return (
    <div className="rounded-xl border border-dashed border-[var(--shell-border)] px-4 py-6 text-sm text-[var(--shell-text-soft)]">
      {text}
    </div>
  );
}
