import { useCallback, useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import {
  getBrandTruth,
  saveBrandTruth,
  listTrendSnapshots,
  getDocument,
  listReports,
} from "../db/boards";
import { useCommand } from "../hooks/useCommand";

interface BrandTruth {
  canonicalName: string;
  businessSummary: string;
  primaryCategory: string;
  coreOfferings: string[];
  positiveKeywords: string[];
  negativeKeywords: string[];
  mustWinQueries: string[];
  notes: string;
}

const EMPTY_TRUTH: BrandTruth = {
  canonicalName: "", businessSummary: "", primaryCategory: "",
  coreOfferings: [], positiveKeywords: [], negativeKeywords: [],
  mustWinQueries: [], notes: "",
};

interface SnapshotMetrics {
  mentionRate: number;
  exposureRate: number;
  weightedMentionRate: number;
  mentionCount: number;
}

interface Snapshot {
  id: string;
  capturedAt: string;
  metrics: SnapshotMetrics;
  actions: Array<{ id: string; title: string; status: string }>;
}

interface WeeklyReport {
  id: string;
  headline?: string;
  overview?: string[];
  engineBreakdown?: Array<{ engine: string; mentionRate: number; change: number }>;
  weeklyChanges?: { mentionRate?: number; exposureRate?: number; newKeywords?: number };
  createdAt?: unknown;
}

function TrendLine({ snapshots, valueKey, color }: { snapshots: Snapshot[]; valueKey: keyof SnapshotMetrics; color: string }) {
  const values = snapshots.map((s) => s.metrics[valueKey] || 0);
  const max = Math.max(...values, 1);
  const points = values.map((v, i) => {
    const x = values.length === 1 ? 50 : (i / Math.max(values.length - 1, 1)) * 100;
    const y = 100 - (v / max) * 100;
    return `${x},${y}`;
  }).join(" ");

  return (
    <svg viewBox="0 0 100 100" className="h-28 w-full overflow-visible">
      <polyline fill="none" stroke={color} strokeWidth="3" points={points} vectorEffect="non-scaling-stroke" />
      {values.map((v, i) => {
        const x = values.length === 1 ? 50 : (i / Math.max(values.length - 1, 1)) * 100;
        const y = 100 - (v / max) * 100;
        return <circle key={`${String(valueKey)}-${i}`} cx={x} cy={y} r="2.5" fill={color} />;
      })}
    </svg>
  );
}

export function Trends() {
  const { id } = useParams<{ id: string }>();
  const cmd = useCommand(id);
  const [truth, setTruth] = useState<BrandTruth>(EMPTY_TRUTH);
  const [snapshots, setSnapshots] = useState<Snapshot[]>([]);
  const [reports, setReports] = useState<WeeklyReport[]>([]);
  const [weeklyReport, setWeeklyReport] = useState<Record<string, any> | null>(null);
  const [saving, setSaving] = useState(false);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<"overview" | "truth" | "reports">("overview");

  const load = useCallback(async () => {
    if (!id) return;
    setLoading(true);
    const [bt, snaps, reps, wr] = await Promise.all([
      getBrandTruth(id).catch(() => null),
      listTrendSnapshots(id).catch(() => []),
      listReports(id, 5).catch(() => []),
      getDocument(id, "weekly-report").catch(() => null),
    ]);
    if (bt) setTruth({ ...EMPTY_TRUTH, ...(bt as unknown as BrandTruth) });
    setSnapshots(snaps as Snapshot[]);
    setReports(reps as WeeklyReport[]);
    if (wr) setWeeklyReport(wr.data as Record<string, any> ?? null);
    setLoading(false);
  }, [id]);

  useEffect(() => { load(); }, [load]);

  const handleSave = async () => {
    if (!id) return;
    setSaving(true);
    await saveBrandTruth(id, truth as unknown as Record<string, unknown>);
    setSaving(false);
  };

  const handleSnapshot = async () => {
    await cmd.execute("create_trend_snapshot");
    setTimeout(load, 2000);
  };

  const handleWeeklyReport = async () => {
    await cmd.execute("create_weekly_report");
    setTimeout(load, 3000);
  };

  const update = (patch: Partial<BrandTruth>) => setTruth((prev) => ({ ...prev, ...patch }));

  const latest = snapshots[snapshots.length - 1];
  const previous = snapshots.length > 1 ? snapshots[snapshots.length - 2] : null;
  const delta = latest && previous
    ? {
        mentionRate: latest.metrics.mentionRate - previous.metrics.mentionRate,
        exposureRate: latest.metrics.exposureRate - previous.metrics.exposureRate,
        weightedMentionRate: latest.metrics.weightedMentionRate - previous.metrics.weightedMentionRate,
      }
    : null;

  if (loading) return <div className="flex min-h-[40vh] items-center justify-center text-[var(--shell-text-muted)]">Loading...</div>;

  return (
    <div className="mx-auto max-w-[1400px] space-y-6">
      <header className="flex items-end justify-between gap-4">
        <div>
          <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">Trend</div>
          <h1 className="mt-2 text-3xl font-semibold text-[var(--shell-text)]">Brand Truth + Trend Analysis</h1>
          <p className="mt-2 text-sm text-[var(--shell-text-muted)]">Track mention rates and action impact over time.</p>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={handleWeeklyReport} disabled={cmd.isRunning} className="rounded-xl border border-[var(--shell-accent)]/30 bg-[var(--shell-accent)]/10 px-3.5 py-2.5 text-sm text-[var(--shell-accent)] disabled:opacity-50">
            {cmd.isRunning ? "Generating..." : "Weekly Report"}
          </button>
          <button onClick={handleSnapshot} disabled={cmd.isRunning} className="shell-button-primary rounded-xl px-3.5 py-2.5 text-sm font-medium disabled:opacity-50">
            {cmd.isRunning ? "Saving..." : "Save Snapshot"}
          </button>
        </div>
      </header>

      {/* Tabs */}
      <div className="flex gap-1 border-b border-[var(--shell-border)]">
        {([["overview", "Overview"], ["truth", "Brand Truth"], ["reports", "Reports"]] as const).map(([key, label]) => (
          <button key={key} onClick={() => setActiveTab(key)}
            className={`shell-transition border-b-2 px-4 py-2.5 text-xs ${activeTab === key ? "border-[var(--shell-accent)] text-[var(--shell-accent)]" : "border-transparent text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"}`}
          >{label}</button>
        ))}
      </div>

      {activeTab === "overview" && (
        <>
          <section className="grid gap-3 md:grid-cols-3">
            <TrendCard label="Mention Rate" value={`${latest?.metrics.mentionRate ?? 0}%`} hint={delta ? `${delta.mentionRate >= 0 ? "+" : ""}${delta.mentionRate}% vs prev` : "First snapshot"} snapshots={snapshots} valueKey="mentionRate" color="var(--shell-accent)" />
            <TrendCard label="Exposure Rate" value={`${latest?.metrics.exposureRate ?? 0}%`} hint={delta ? `${delta.exposureRate >= 0 ? "+" : ""}${delta.exposureRate}% vs prev` : "First snapshot"} snapshots={snapshots} valueKey="exposureRate" color="var(--shell-positive)" />
            <TrendCard label="Weighted Mention" value={`${latest?.metrics.weightedMentionRate ?? 0}%`} hint={delta ? `${delta.weightedMentionRate >= 0 ? "+" : ""}${delta.weightedMentionRate}% vs prev` : "First snapshot"} snapshots={snapshots} valueKey="weightedMentionRate" color="var(--shell-warning)" />
          </section>

          {/* Weekly report summary */}
          {weeklyReport && (
            <section className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
              <h2 className="text-sm font-medium text-[var(--shell-text)]">Latest Weekly Report</h2>
              {weeklyReport.headline && <div className="mt-2 text-lg font-semibold text-[var(--shell-text)]">{weeklyReport.headline}</div>}
              {weeklyReport.overview && Array.isArray(weeklyReport.overview) && (
                <ul className="mt-3 space-y-1">
                  {weeklyReport.overview.map((item: string, i: number) => (
                    <li key={i} className="flex items-start gap-2 text-sm text-[var(--shell-text-muted)]">
                      <span className="mt-0.5 text-[var(--shell-positive)]">*</span>{item}
                    </li>
                  ))}
                </ul>
              )}
              {weeklyReport.engineBreakdown && Array.isArray(weeklyReport.engineBreakdown) && (
                <div className="mt-4 grid gap-2 md:grid-cols-4">
                  {weeklyReport.engineBreakdown.map((eng: any) => (
                    <div key={eng.engine} className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3 text-center">
                      <div className="text-xs uppercase text-[var(--shell-text-muted)]">{eng.engine}</div>
                      <div className="mt-1 text-2xl font-semibold text-[var(--shell-text)]">{eng.mentionRate}%</div>
                      {eng.change !== 0 && (
                        <div className={`mt-0.5 text-xs ${eng.change > 0 ? "text-[var(--shell-positive)]" : "text-[var(--shell-danger)]"}`}>
                          {eng.change > 0 ? "+" : ""}{eng.change}%
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </section>
          )}

          {/* Snapshot table */}
          <section className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
            <h2 className="text-sm font-medium text-[var(--shell-text)]">Snapshot History</h2>
            <div className="mt-4 overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-[var(--shell-border)] text-left text-[var(--shell-text-soft)]">
                    <th className="py-2 pr-4">Date</th>
                    <th className="py-2 pr-4">Mention</th>
                    <th className="py-2 pr-4">Exposure</th>
                    <th className="py-2 pr-4">Weighted</th>
                    <th className="py-2 pr-4">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {snapshots.map((snap) => (
                    <tr key={snap.id} className="border-b border-[var(--shell-border)]/30 text-[var(--shell-text-muted)]">
                      <td className="whitespace-nowrap py-3 pr-4">{snap.capturedAt?.slice?.(0, 16)?.replace("T", " ") || "-"}</td>
                      <td className="py-3 pr-4">{snap.metrics.mentionRate}%</td>
                      <td className="py-3 pr-4">{snap.metrics.exposureRate}%</td>
                      <td className="py-3 pr-4">{snap.metrics.weightedMentionRate}%</td>
                      <td className="py-3 pr-4">
                        {(snap.actions || []).slice(0, 2).map((a) => (
                          <span key={a.id} className="mr-2 text-[11px] text-[var(--shell-text-soft)]">{a.title}</span>
                        ))}
                      </td>
                    </tr>
                  ))}
                  {snapshots.length === 0 && (
                    <tr><td colSpan={5} className="py-8 text-center text-[var(--shell-text-muted)]">No snapshots yet.</td></tr>
                  )}
                </tbody>
              </table>
            </div>
          </section>
        </>
      )}

      {activeTab === "truth" && (
        <div className="grid gap-4 lg:grid-cols-2">
          <section className="shell-transition space-y-3 rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
            <h2 className="text-sm font-medium text-[var(--shell-text)]">Brand Truth</h2>
            <Field label="Brand Name" value={truth.canonicalName} onChange={(v) => update({ canonicalName: v })} />
            <Field label="Business Summary" value={truth.businessSummary} onChange={(v) => update({ businessSummary: v })} multiline rows={4} />
            <div className="grid grid-cols-2 gap-3">
              <Field label="Primary Category" value={truth.primaryCategory} onChange={(v) => update({ primaryCategory: v })} />
              <Field label="Core Offerings" value={truth.coreOfferings.join(", ")} onChange={(v) => update({ coreOfferings: v.split(",").map((s) => s.trim()).filter(Boolean) })} />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <Field label="Positive Keywords" value={truth.positiveKeywords.join(", ")} onChange={(v) => update({ positiveKeywords: v.split(",").map((s) => s.trim()).filter(Boolean) })} multiline rows={3} />
              <Field label="Negative Keywords" value={truth.negativeKeywords.join(", ")} onChange={(v) => update({ negativeKeywords: v.split(",").map((s) => s.trim()).filter(Boolean) })} multiline rows={3} />
            </div>
            <Field label="Must-win Queries" value={truth.mustWinQueries.join("\n")} onChange={(v) => update({ mustWinQueries: v.split("\n").map((s) => s.trim()).filter(Boolean) })} multiline rows={4} />
            <Field label="Notes" value={truth.notes} onChange={(v) => update({ notes: v })} multiline rows={3} />
            <button onClick={handleSave} disabled={saving} className="shell-button-primary rounded-xl px-4 py-2.5 text-sm font-medium disabled:opacity-50">
              {saving ? "Saving..." : "Save Brand Truth"}
            </button>
          </section>

          <section className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
            <h2 className="text-sm font-medium text-[var(--shell-text)]">Current Summary</h2>
            <p className="mt-3 text-sm leading-relaxed text-[var(--shell-text-muted)]">
              {truth.businessSummary || "Enter your brand definition to see it reflected in auto-analysis."}
            </p>
            <div className="mt-4 flex flex-wrap gap-2">
              {truth.primaryCategory && <span className="rounded-full bg-[var(--shell-positive)]/10 px-2 py-1 text-xs text-[var(--shell-positive)]">{truth.primaryCategory}</span>}
              {truth.coreOfferings.slice(0, 6).map((item) => (
                <span key={item} className="rounded-full bg-[var(--shell-panel-soft)] px-2 py-1 text-xs text-[var(--shell-text-muted)]">{item}</span>
              ))}
            </div>
            {truth.mustWinQueries.length > 0 && (
              <div className="mt-6">
                <div className="text-[11px] text-[var(--shell-text-soft)]">Must-win Queries</div>
                <div className="mt-2 space-y-2">
                  {truth.mustWinQueries.slice(0, 5).map((q) => (
                    <div key={q} className="rounded-[12px] border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-sm text-[var(--shell-text-muted)]">{q}</div>
                  ))}
                </div>
              </div>
            )}
          </section>
        </div>
      )}

      {activeTab === "reports" && (
        <section className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
          <h2 className="text-sm font-medium text-[var(--shell-text)]">Generated Reports</h2>
          {reports.length > 0 ? (
            <div className="mt-4 space-y-3">
              {reports.map((r) => (
                <div key={r.id} className="rounded-[14px] border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4">
                  <div className="flex items-center justify-between">
                    <div className="text-sm font-medium text-[var(--shell-text)]">{r.headline || `Report ${r.id.slice(0, 8)}`}</div>
                    <div className="text-[11px] text-[var(--shell-text-muted)]">
                      {r.createdAt ? new Date((r.createdAt as any)?.toDate?.() ?? r.createdAt as string).toLocaleDateString("ko-KR") : ""}
                    </div>
                  </div>
                  {r.overview && (
                    <div className="mt-2 text-xs leading-5 text-[var(--shell-text-muted)]">
                      {r.overview.slice(0, 3).join(" | ")}
                    </div>
                  )}
                </div>
              ))}
            </div>
          ) : (
            <div className="mt-4 rounded-[14px] border border-dashed border-[var(--shell-border)] py-8 text-center text-xs text-[var(--shell-text-soft)]">
              No reports generated yet. Click "Weekly Report" to create one.
            </div>
          )}
        </section>
      )}
    </div>
  );
}

function TrendCard({ label, value, hint, snapshots, valueKey, color }: { label: string; value: string; hint: string; snapshots: Snapshot[]; valueKey: keyof SnapshotMetrics; color: string }) {
  return (
    <div className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
      <div className="text-[11px] uppercase tracking-[0.18em] text-[var(--shell-text-soft)]">{label}</div>
      <div className="mt-2 text-3xl font-semibold text-[var(--shell-text)]">{value}</div>
      <div className="mt-1 text-[11px] text-[var(--shell-text-muted)]">{hint}</div>
      {snapshots.length > 0 && <div className="mt-3"><TrendLine snapshots={snapshots} valueKey={valueKey} color={color} /></div>}
    </div>
  );
}

function Field({ label, value, onChange, multiline = false, rows = 1 }: { label: string; value: string; onChange: (v: string) => void; multiline?: boolean; rows?: number }) {
  const cls = "shell-input w-full rounded-[10px] px-3 py-2 text-sm";
  return (
    <label className="block">
      <div className="mb-1 text-[11px] text-[var(--shell-text-soft)]">{label}</div>
      {multiline ? <textarea value={value} onChange={(e) => onChange(e.target.value)} rows={rows} className={cls} /> : <input value={value} onChange={(e) => onChange(e.target.value)} className={cls} />}
    </label>
  );
}
