import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { ChevronDown, ChevronRight, Plus, Play } from "lucide-react";
import { getBoard, listGeoProbes, updateBoard } from "../db/boards";
import { useCommand } from "../hooks/useCommand";
import { flatKeywords, type Board } from "../db/collections";

type Category = "product" | "comparison" | "local" | "brand" | "howto";

const CATEGORY_LABELS: Record<Category, string> = {
  product: "제품/서비스",
  comparison: "비교",
  howto: "방법/가이드",
  local: "지역",
  brand: "브랜드",
};

const CATEGORY_OPTIONS: Category[] = ["product", "comparison", "local", "brand", "howto"];

interface GeoProbe {
  id: string;
  question: string;
  engine: string;
  category?: string;
  ourSiteMentioned?: boolean;
  ourSiteInResults?: boolean;
  [key: string]: unknown;
}

interface QuestionGroup {
  question: string;
  category: string;
  probes: GeoProbe[];
  engines: string[];
  mentionCount: number;
  exposureCount: number;
  status: "mentioned" | "not_mentioned" | "pending";
}

export function Queries() {
  const { id } = useParams<{ id: string }>();
  const [board, setBoard] = useState<Board | null>(null);
  const [probes, setProbes] = useState<GeoProbe[]>([]);
  const [loading, setLoading] = useState(true);
  const [newQuestion, setNewQuestion] = useState("");
  const [newCategory, setNewCategory] = useState<Category>("product");
  const [expandedQuestion, setExpandedQuestion] = useState<string | null>(null);
  const cmd = useCommand(id);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    Promise.all([getBoard(id), listGeoProbes(id)]).then(([b, gp]) => {
      setBoard(b);
      setProbes(gp as unknown as GeoProbe[]);
      setLoading(false);
    });
  }, [id]);

  // Group probes by question text
  const questionGroups: QuestionGroup[] = (() => {
    const map = new Map<string, GeoProbe[]>();
    for (const p of probes) {
      const q = p.question || "";
      if (!q) continue;
      const list = map.get(q) ?? [];
      list.push(p);
      map.set(q, list);
    }
    return Array.from(map.entries()).map(([question, groupProbes]) => {
      const engines = [...new Set(groupProbes.map((p) => p.engine))];
      const mentionCount = groupProbes.filter((p) => p.ourSiteMentioned).length;
      const exposureCount = groupProbes.filter((p) => p.ourSiteInResults).length;
      const category = groupProbes[0]?.category || "product";
      const hasMention = mentionCount > 0;
      const allDone = groupProbes.length > 0;
      const status: QuestionGroup["status"] = hasMention
        ? "mentioned"
        : allDone
          ? "not_mentioned"
          : "pending";
      return { question, category, probes: groupProbes, engines, mentionCount, exposureCount, status };
    });
  })();

  // Metrics
  const totalQuestions = questionGroups.length;
  const mentionedQuestions = questionGroups.filter((g) => g.status === "mentioned").length;
  const mentionRate = totalQuestions > 0 ? Math.round((mentionedQuestions / totalQuestions) * 100) : 0;
  const pendingQuestions = questionGroups.filter((g) => g.status === "pending").length;

  const handleAddQuestion = async () => {
    if (!id || !newQuestion.trim()) return;
    const formatted = `[${newCategory}] ${newQuestion.trim()}`;
    const existing = flatKeywords(board?.classifiedKeywords);
    if (existing.includes(formatted)) return;
    const updated = [...existing, formatted];
    await updateBoard(id, { classifiedKeywords: updated as any });
    setBoard((prev) => (prev ? { ...prev, classifiedKeywords: updated } : prev));
    setNewQuestion("");
  };

  const handleRunProbe = async () => {
    await cmd.execute("run_geo_probe");
    // Refresh data after execution starts
    if (id) {
      const [b, gp] = await Promise.all([getBoard(id), listGeoProbes(id)]);
      setBoard(b);
      setProbes(gp as unknown as GeoProbe[]);
    }
  };

  if (loading) {
    return (
      <div className="flex min-h-[40vh] items-center justify-center text-[var(--shell-text-muted)]">
        데이터 로딩 중...
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-[1400px] space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between gap-4">
        <div>
          <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">
            Data Collection / Queries
          </div>
          <h1 className="mt-2 text-3xl font-semibold text-[var(--shell-text)]">
            Queries
          </h1>
        </div>
        <button
          type="button"
          onClick={handleRunProbe}
          disabled={cmd.isRunning}
          className="shell-transition flex items-center gap-2 rounded-xl border border-[var(--shell-accent)]/30 bg-[var(--shell-accent)]/10 px-4 py-2 text-sm font-medium text-[var(--shell-accent)] hover:bg-[var(--shell-accent)]/20 disabled:opacity-50"
        >
          <Play className="h-4 w-4" />
          AI 시뮬레이션 실행
        </button>
      </div>

      {/* Running indicator */}
      {cmd.isRunning && (
        <div className="rounded-xl border border-[var(--shell-accent)] bg-[var(--shell-accent)]/5 px-4 py-2 text-sm text-[var(--shell-accent)]">
          <span className="mr-2 inline-flex h-2 w-2 animate-pulse rounded-full bg-[var(--shell-accent)]" />
          {cmd.message || "AI 시뮬레이션 실행 중..."}
          {cmd.progress > 0 && (
            <span className="ml-2 text-xs text-[var(--shell-text-muted)]">
              ({cmd.progress}%)
            </span>
          )}
        </div>
      )}

      {/* 4 Metric Cards */}
      <div className="grid gap-4 md:grid-cols-4">
        <MetricCard label="전체 질문" value={totalQuestions} />
        <MetricCard label="언급된 질문" value={mentionedQuestions} tone="positive" />
        <MetricCard label="언급률" value={`${mentionRate}%`} tone={mentionRate >= 30 ? "positive" : mentionRate > 0 ? "warning" : undefined} />
        <MetricCard label="대기 중 질문" value={pendingQuestions} tone={pendingQuestions > 0 ? "warning" : undefined} />
      </div>

      {/* Manual Question Add Form */}
      <section className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
        <div className="text-sm font-medium text-[var(--shell-text)]">질문 직접 추가</div>
        <div className="mt-3 flex flex-col gap-3 sm:flex-row sm:items-end">
          <div className="min-w-0 flex-1">
            <label className="mb-1 block text-xs text-[var(--shell-text-soft)]">질문</label>
            <input
              type="text"
              value={newQuestion}
              onChange={(e) => setNewQuestion(e.target.value)}
              placeholder="예: 우리 브랜드 제품의 장점은?"
              className="shell-input w-full rounded-[10px] px-3 py-2 text-sm"
              onKeyDown={(e) => {
                if (e.key === "Enter") handleAddQuestion();
              }}
            />
          </div>
          <div className="w-full sm:w-44">
            <label className="mb-1 block text-xs text-[var(--shell-text-soft)]">카테고리</label>
            <select
              value={newCategory}
              onChange={(e) => setNewCategory(e.target.value as Category)}
              className="shell-input w-full rounded-[10px] px-3 py-2 text-sm"
            >
              {CATEGORY_OPTIONS.map((cat) => (
                <option key={cat} value={cat}>
                  {CATEGORY_LABELS[cat]}
                </option>
              ))}
            </select>
          </div>
          <button
            type="button"
            onClick={handleAddQuestion}
            disabled={!newQuestion.trim()}
            className="shell-transition flex items-center gap-1.5 rounded-xl border border-[var(--shell-accent)]/30 bg-[var(--shell-accent)]/10 px-4 py-2 text-sm font-medium text-[var(--shell-accent)] hover:bg-[var(--shell-accent)]/20 disabled:opacity-50"
          >
            <Plus className="h-4 w-4" />
            직접 추가
          </button>
        </div>
      </section>

      {/* Question List */}
      <section className="space-y-2">
        {questionGroups.length === 0 && (
          <div className="shell-transition rounded-[18px] border border-dashed border-[var(--shell-border)] bg-[var(--shell-panel)] p-6 text-center text-sm text-[var(--shell-text-muted)]">
            아직 수집된 질문이 없습니다. AI 시뮬레이션을 실행하거나 직접 질문을 추가하세요.
          </div>
        )}

        {questionGroups.map((group) => {
          const isExpanded = expandedQuestion === group.question;
          return (
            <div
              key={group.question}
              className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] shadow-[var(--shell-shadow)]"
            >
              <button
                onClick={() =>
                  setExpandedQuestion(isExpanded ? null : group.question)
                }
                className="flex w-full items-center gap-3 p-4 text-left transition-colors hover:bg-[var(--shell-panel-soft)]"
              >
                {isExpanded ? (
                  <ChevronDown className="h-4 w-4 shrink-0 text-[var(--shell-text-muted)]" />
                ) : (
                  <ChevronRight className="h-4 w-4 shrink-0 text-[var(--shell-text-muted)]" />
                )}
                <div className="min-w-0 flex-1">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className="text-sm font-medium text-[var(--shell-text)]">
                      {group.question}
                    </span>
                    <CategoryBadge category={group.category} />
                  </div>
                  <div className="mt-1 flex flex-wrap items-center gap-3 text-xs text-[var(--shell-text-soft)]">
                    <span>엔진 {group.engines.length}개</span>
                    <span>언급 {group.mentionCount}/{group.probes.length}</span>
                    <span>노출 {group.exposureCount}/{group.probes.length}</span>
                  </div>
                </div>
                <StatusBadge status={group.status} />
              </button>

              {isExpanded && (
                <div className="space-y-2 border-t border-[var(--shell-border)] p-4">
                  {group.probes.map((probe) => (
                    <div
                      key={probe.id}
                      className="flex items-center justify-between gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3"
                    >
                      <div className="flex items-center gap-3">
                        <span className="text-sm font-medium uppercase tracking-[0.08em] text-[var(--shell-text-muted)]">
                          {probe.engine}
                        </span>
                      </div>
                      <div className="flex items-center gap-3 text-xs">
                        <span
                          className={
                            probe.ourSiteMentioned
                              ? "text-[var(--shell-positive)]"
                              : "text-[var(--shell-text-soft)]"
                          }
                        >
                          {probe.ourSiteMentioned ? "언급됨" : "미언급"}
                        </span>
                        <span className="text-[var(--shell-text-soft)]">|</span>
                        <span
                          className={
                            probe.ourSiteInResults
                              ? "text-[var(--shell-positive)]"
                              : "text-[var(--shell-text-soft)]"
                          }
                        >
                          {probe.ourSiteInResults ? "노출됨" : "미노출"}
                        </span>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          );
        })}
      </section>
    </div>
  );
}

// ── Sub-components ─────────────────────────────────────────

function MetricCard({
  label,
  value,
  tone,
}: {
  label: string;
  value: number | string;
  tone?: "positive" | "warning" | "danger";
}) {
  const valueColor = tone === "positive"
    ? "text-[var(--shell-positive)]"
    : tone === "warning"
      ? "text-[var(--shell-warning)]"
      : tone === "danger"
        ? "text-[var(--shell-danger)]"
        : "text-[var(--shell-text)]";

  return (
    <div className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
      <div className="text-[11px] uppercase tracking-[0.18em] text-[var(--shell-text-soft)]">
        {label}
      </div>
      <div className={`mt-2 text-3xl font-semibold ${valueColor}`}>{value}</div>
    </div>
  );
}

function CategoryBadge({ category }: { category: string }) {
  const label = CATEGORY_LABELS[category as Category] || category;
  return (
    <span className="rounded-md bg-[var(--shell-panel-soft)] px-1.5 py-0.5 text-[10px] font-medium text-[var(--shell-text-muted)] border border-[var(--shell-border)]">
      {label}
    </span>
  );
}

function StatusBadge({ status }: { status: QuestionGroup["status"] }) {
  if (status === "mentioned") {
    return (
      <span className="shrink-0 rounded-md bg-[var(--shell-positive)]/15 px-2 py-0.5 text-[11px] font-medium text-[var(--shell-positive)]">
        언급됨
      </span>
    );
  }
  if (status === "not_mentioned") {
    return (
      <span className="shrink-0 rounded-md bg-[var(--shell-danger)]/15 px-2 py-0.5 text-[11px] font-medium text-[var(--shell-danger)]">
        미언급
      </span>
    );
  }
  return (
    <span className="shrink-0 rounded-md bg-[var(--shell-warning)]/15 px-2 py-0.5 text-[11px] font-medium text-[var(--shell-warning)]">
      대기
    </span>
  );
}
