import { useState } from "react";
import { Link } from "react-router-dom";
import { ConsoleLog, type ConsoleEntry } from "../../components/ConsoleLog";
import { useCommand } from "../../hooks/useCommand";
import { updateSiteName } from "../../db/boards";
import type { LogLine } from "../../hooks/useCommand";
import type { Board } from "../../db/collections";

const STEP_LABELS: Record<string, string> = {
  crawl: "Crawl", seo: "SEO/GEO", brand: "Brand", keywords: "Keywords",
  competitors: "Competitors", geoProbe: "GEO Probe", external: "External",
  content: "Content", harness: "Synthesis", sns: "SNS",
};

interface DashboardTopBarProps {
  id: string;
  board: Board | null;
  logLines: LogLine[];
  onReanalyze: () => void;
  reanalyzing: boolean;
}

export function DashboardTopBar({ id, board, logLines, onReanalyze, reanalyzing }: DashboardTopBarProps) {
  const [showLog, setShowLog] = useState(false);
  const [editing, setEditing] = useState(false);
  const [editName, setEditName] = useState("");
  const [retrying, setRetrying] = useState<Set<string>>(new Set());
  const cmd = useCommand(id);

  const stepStatus = board?.stepStatus ?? {};
  const entries = Object.entries(stepStatus);
  const failedSteps = entries.filter(([, s]) => s === "failed");
  const runningSteps = entries.filter(([, s]) => s === "running");

  const faviconUrl = board?.domain ? `https://www.google.com/s2/favicons?domain=${board.domain}&sz=32` : null;

  const handleEditStart = () => {
    setEditName(board?.siteName || "");
    setEditing(true);
  };

  const handleEditSave = async () => {
    const name = editName.trim();
    if (name && id) await updateSiteName(id, name);
    setEditing(false);
  };

  const handleRetry = async (step: string) => {
    setRetrying((prev) => new Set(prev).add(step));
    try {
      await cmd.execute("retry_step", { step });
    } finally {
      setRetrying((prev) => { const n = new Set(prev); n.delete(step); return n; });
    }
  };

  const consoleEntries: ConsoleEntry[] = logLines.map((l, i) => ({
    id: `${l.ts}-${i}`,
    type: l.type === "step" ? "info" : l.type === "warning" ? "search" : l.type,
    message: l.message,
    timestamp: l.ts,
  }));

  return (
    <div className="space-y-3">
      <div className="shell-transition flex flex-wrap items-center gap-3 rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] px-5 py-3 shadow-[var(--shell-shadow)]">
        <div className="mr-auto flex items-center gap-3">
          {faviconUrl && <img src={faviconUrl} alt="" className="h-5 w-5 rounded" />}
          {editing ? (
            <input
              value={editName}
              onChange={(e) => setEditName(e.target.value)}
              onBlur={handleEditSave}
              onKeyDown={(e) => { if (e.key === "Enter") handleEditSave(); if (e.key === "Escape") setEditing(false); }}
              autoFocus
              className="shell-input rounded px-2 py-1 text-sm font-medium"
            />
          ) : (
            <button onClick={handleEditStart} className="text-sm font-medium text-[var(--shell-text)] hover:text-[var(--shell-accent)]" title="Click to edit">
              {board?.siteName || board?.domain || "..."}
            </button>
          )}
          <span className="text-xs text-[var(--shell-text-soft)]">{board?.domain}</span>
        </div>

        <div className="flex items-center gap-2">
          {runningSteps.length > 0 && (
            <span className="flex items-center gap-1.5 rounded-full bg-[color-mix(in_srgb,var(--shell-accent)_14%,transparent)] px-3 py-1 text-[11px] text-[var(--shell-accent)]">
              <span className="inline-block h-1.5 w-1.5 animate-pulse rounded-full bg-[var(--shell-accent)]" />
              {runningSteps.map(([s]) => STEP_LABELS[s] || s).join(", ")}
            </span>
          )}

          {failedSteps.length > 0 && (
            <span className="rounded-full bg-[color-mix(in_srgb,var(--shell-danger)_14%,transparent)] px-3 py-1 text-[11px] text-[var(--shell-danger)]">
              {failedSteps.length} failed
            </span>
          )}

          <button onClick={() => setShowLog(!showLog)}
            className="shell-transition relative rounded-lg border border-[var(--shell-border)] px-3 py-1.5 text-xs text-[var(--shell-text-muted)] hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)]"
          >
            Log
            {logLines.length > 0 && (
              <span className="absolute -right-1.5 -top-1.5 grid h-4 w-4 place-items-center rounded-full bg-[var(--shell-accent)] text-[9px] text-white">
                {logLines.length > 99 ? "99+" : logLines.length}
              </span>
            )}
          </button>

          <button onClick={onReanalyze} disabled={reanalyzing}
            className="shell-transition rounded-lg border border-[var(--shell-border)] px-3 py-1.5 text-xs text-[var(--shell-text-muted)] hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)] disabled:opacity-40"
          >
            {reanalyzing ? "..." : "Reanalyze"}
          </button>

          <Link to={`/board/${id}/manage/jobs`}
            className="shell-transition rounded-lg border border-[var(--shell-border)] px-3 py-1.5 text-xs text-[var(--shell-text-muted)] hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)]"
          >
            Manage
          </Link>
        </div>
      </div>

      {entries.length > 0 && (
        <div className="flex flex-wrap gap-2">
          {entries.map(([step, status]) => (
            <span key={step}
              className={`shell-transition flex items-center gap-1.5 rounded-lg border px-3 py-1.5 text-[11px] ${
                status === "complete" ? "border-[var(--shell-positive)]/30 bg-[color-mix(in_srgb,var(--shell-positive)_8%,transparent)] text-[var(--shell-positive)]"
                : status === "running" ? "border-[var(--shell-accent)]/30 bg-[color-mix(in_srgb,var(--shell-accent)_8%,transparent)] text-[var(--shell-accent)]"
                : status === "failed" ? "border-[var(--shell-danger)]/30 bg-[color-mix(in_srgb,var(--shell-danger)_8%,transparent)] text-[var(--shell-danger)]"
                : "border-[var(--shell-border)] text-[var(--shell-text-soft)]"
              }`}
            >
              {STEP_LABELS[step] || step}
              {status === "failed" && (
                <button onClick={() => handleRetry(step)} disabled={retrying.has(step)}
                  className="ml-1 rounded bg-[var(--shell-danger)] px-1.5 py-0.5 text-[9px] text-white hover:opacity-80 disabled:opacity-40"
                >
                  {retrying.has(step) ? "..." : "Retry"}
                </button>
              )}
            </span>
          ))}
        </div>
      )}

      {showLog && consoleEntries.length > 0 && <ConsoleLog entries={consoleEntries} />}
    </div>
  );
}
