import {
  collection,
  doc,
  addDoc,
  onSnapshot,
  serverTimestamp,
  type Unsubscribe,
  type DocumentReference,
} from "firebase/firestore";
import { db } from "../config/firebase";
import { COLLECTIONS, type CommandType, type CommandDoc } from "./collections";

export async function issueCommand(
  boardId: string,
  userId: string,
  type: CommandType,
  params: Record<string, unknown> = {},
): Promise<DocumentReference> {
  return addDoc(collection(db, COLLECTIONS.commands(boardId)), {
    type,
    status: "pending",
    params,
    progress: 0,
    message: "",
    result: null,
    error: null,
    userId,
    createdAt: serverTimestamp(),
    updatedAt: serverTimestamp(),
  });
}

export function subscribeCommand(
  boardId: string,
  cmdId: string,
  callback: (cmd: CommandDoc) => void,
): Unsubscribe {
  return onSnapshot(
    doc(db, "boards", boardId, "commands", cmdId),
    (snap) => {
      if (!snap.exists()) return;
      const data = snap.data();
      callback({
        id: snap.id,
        ...data,
        createdAt: data.createdAt?.toDate?.() ?? new Date(),
        updatedAt: data.updatedAt?.toDate?.() ?? new Date(),
      } as CommandDoc);
    },
  );
}
