import { useState } from "react";
import { DiagnosisSeoTab } from "./diagnosis/DiagnosisSeoTab";
import { DiagnosisGeoTab } from "./diagnosis/DiagnosisGeoTab";
import { DiagnosisExternalTab } from "./diagnosis/DiagnosisExternalTab";
import { DiagnosisInsightsTab } from "./diagnosis/DiagnosisInsightsTab";
import { DiagnosisGbpTab } from "./diagnosis/DiagnosisGbpTab";
import { DiagnosisGoogleTab } from "./diagnosis/DiagnosisGoogleTab";
import { DiagnosisNaverTab } from "./diagnosis/DiagnosisNaverTab";
import { DiagnosisIconBar } from "./diagnosis/DiagnosisIconBar";
import type { Board, BoardDocument, GbpReview, GoogleKeywordAnalysis, NaverKeywordAnalysis } from "../../db/collections";

type TabKey = "insights" | "gbp" | "seo" | "geo" | "google" | "naver" | "external";

const TABS: { key: TabKey; label: string }[] = [
  { key: "insights", label: "Performance" },
  { key: "gbp", label: "GBP" },
  { key: "seo", label: "SEO" },
  { key: "geo", label: "GEO" },
  { key: "google", label: "Google" },
  { key: "naver", label: "Naver" },
  { key: "external", label: "External" },
];

interface DashboardDiagnosisProps {
  seoAudit: Record<string, any> | null;
  docs: BoardDocument[];
  board: Board | null;
  gbpReviews: GbpReview[];
  googleKeywordAnalysis: GoogleKeywordAnalysis | null;
  naverKeywordAnalysis: NaverKeywordAnalysis | null;
  onOpenRobotsModal: () => void;
}

export function DashboardDiagnosis({
  seoAudit,
  docs,
  board,
  gbpReviews,
  googleKeywordAnalysis,
  naverKeywordAnalysis,
  onOpenRobotsModal,
}: DashboardDiagnosisProps) {
  const [tab, setTab] = useState<TabKey>("seo");

  const seoScore = (seoAudit as any)?.score ?? board?.seoScore ?? 0;
  const geoScore = (seoAudit as any)?.geoScore ?? board?.geoScore ?? 0;
  const gbpScore = board?.gbpDiagnosis?.score ?? null;
  const googleScore = googleKeywordAnalysis?.googleScore ?? null;
  const naverScore = naverKeywordAnalysis?.naverScore ?? null;

  const stepStatus = board?.stepStatus ?? {};
  const googleStepDone = stepStatus.keywords === "complete" || stepStatus.harness === "complete";
  const naverStepDone = googleStepDone;

  return (
    <section className="shell-transition rounded-[22px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
      <DiagnosisIconBar board={board} onOpenRobotsModal={onOpenRobotsModal} />

      <div className="flex items-center justify-between gap-3">
        <div>
          <div className="text-[11px] uppercase tracking-[0.18em] text-[var(--shell-text-soft)]">
            Diagnosis
          </div>
          <div className="mt-2 text-xl font-semibold text-[var(--shell-text)]">
            Site Analysis
          </div>
        </div>
        <div className="flex items-center gap-3">
          <ScoreBadge label="SEO" value={seoScore} />
          <ScoreBadge label="GEO" value={geoScore} />
          {gbpScore != null && <ScoreBadge label="GBP" value={gbpScore} />}
          {googleScore != null && <ScoreBadge label="Ggl" value={googleScore} />}
          {naverScore != null && <ScoreBadge label="Nav" value={naverScore} />}
        </div>
      </div>

      <div className="mt-4 flex gap-1 overflow-x-auto border-b border-[var(--shell-border)]">
        {TABS.map((t) => (
          <button
            key={t.key}
            onClick={() => setTab(t.key)}
            className={`shell-transition shrink-0 border-b-2 px-3 py-2.5 text-xs ${
              tab === t.key
                ? "border-[var(--shell-accent)] text-[var(--shell-accent)]"
                : "border-transparent text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
            }`}
          >
            {t.label}
          </button>
        ))}
      </div>

      <div className="mt-4">
        {tab === "insights" && <DiagnosisInsightsTab seoAudit={seoAudit} />}
        {tab === "gbp" && <DiagnosisGbpTab board={board} reviews={gbpReviews} />}
        {tab === "seo" && <DiagnosisSeoTab seoAudit={seoAudit} />}
        {tab === "geo" && <DiagnosisGeoTab seoAudit={seoAudit} docs={docs} />}
        {tab === "google" && <DiagnosisGoogleTab data={googleKeywordAnalysis} stepDone={googleStepDone} />}
        {tab === "naver" && <DiagnosisNaverTab data={naverKeywordAnalysis} stepDone={naverStepDone} />}
        {tab === "external" && <DiagnosisExternalTab docs={docs} />}
      </div>
    </section>
  );
}

function ScoreBadge({ label, value }: { label: string; value: number }) {
  const color =
    value >= 80
      ? "text-[var(--shell-positive)]"
      : value >= 50
        ? "text-[var(--shell-secondary)]"
        : "text-[var(--shell-danger)]";
  return (
    <div className="text-center">
      <div className={`text-2xl font-semibold ${color}`}>{value}</div>
      <div className="text-[9px] uppercase tracking-[0.16em] text-[var(--shell-text-soft)]">
        {label}
      </div>
    </div>
  );
}
