import { useState } from "react";
import type { Board, GbpReview } from "../../../db/collections";

interface DiagnosisGbpTabProps {
  board: Board | null;
  reviews: GbpReview[];
}

export function DiagnosisGbpTab({ board, reviews }: DiagnosisGbpTabProps) {
  const [expandedReview, setExpandedReview] = useState<string | null>(null);

  const gb = board?.siteInfo?.googleBusiness;
  const diag = board?.gbpDiagnosis;
  const ra = board?.reviewAnalysis;

  if (!gb?.found) {
    return (
      <div className="py-8 text-center text-sm text-[var(--shell-text-muted)]">
        Google Business Profile not detected for this site.
      </div>
    );
  }

  const sortedReviews = [...reviews].sort((a, b) => {
    if (a.publishDate && b.publishDate) return b.publishDate.localeCompare(a.publishDate);
    if (a.publishDate) return -1;
    if (b.publishDate) return 1;
    return 0;
  });

  const reviewKey = (r: GbpReview) => `${r.authorName}|${r.rating}|${r.publishDate || ""}`;

  const sevColors: Record<string, string> = {
    critical: "bg-red-500",
    high: "bg-orange-500",
    medium: "bg-yellow-500",
    low: "bg-sky-400",
    info: "bg-[var(--shell-text-soft)]",
  };

  return (
    <div className="space-y-4">
      {/* Header: name + category + rating */}
      <div className="flex items-start gap-3">
        <a
          href={gb.googleMapsUrl || "https://business.google.com"}
          target="_blank"
          rel="noopener noreferrer"
          className="grid h-9 w-9 shrink-0 place-items-center rounded-lg border border-sky-500/20 bg-sky-500/10 hover:bg-sky-500/20 transition-colors"
          title="Open Google Business Profile"
        >
          <svg viewBox="0 0 24 24" className="h-4 w-4 text-sky-400" fill="currentColor">
            <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z" />
          </svg>
        </a>
        <div className="min-w-0 flex-1">
          <div className="flex items-center justify-between">
            <div className="truncate text-sm font-semibold text-[var(--shell-text)]">{gb.name}</div>
            {gb.phone && <span className="text-xs text-[var(--shell-text-muted)]">{gb.phone}</span>}
          </div>
          <div className="mt-0.5 flex items-center justify-between text-xs text-[var(--shell-text-muted)]">
            {gb.primaryTypeDisplayName && <span className="truncate">{gb.primaryTypeDisplayName}</span>}
            {gb.address && <span className="shrink-0 truncate max-w-[50%] text-right" title={gb.address}>{gb.address}</span>}
          </div>
        </div>
      </div>

      {/* GBP GEO Score + diagnostic items */}
      {diag && (
        <div className={`rounded-xl border p-4 ${diag.score >= 80 ? "border-[var(--shell-positive)]/30" : diag.score >= 50 ? "border-[var(--shell-secondary)]/30" : "border-[var(--shell-danger)]/30"} bg-[var(--shell-panel-soft)]`}>
          <div className="mb-3 text-center">
            <div className="text-xs text-[var(--shell-text-muted)]">GBP GEO Score</div>
            <div className={`text-3xl font-bold ${diag.score >= 80 ? "text-[var(--shell-positive)]" : diag.score >= 50 ? "text-[var(--shell-secondary)]" : "text-[var(--shell-danger)]"}`}>
              {diag.score}<span className="text-xs text-[var(--shell-text-muted)]">/100</span>
            </div>
          </div>
          {diag.items && diag.items.length > 0 && (
            <div className="space-y-2 border-t border-[var(--shell-border)] pt-3">
              {diag.items.map((item) => (
                <div key={item.id} className="flex items-start gap-2 text-xs">
                  <span className={`mt-0.5 inline-block h-2 w-2 shrink-0 rounded-full ${sevColors[item.severity] || sevColors.info}`} />
                  <div className="min-w-0 flex-1">
                    <span className="text-[var(--shell-text)]">{item.title}</span>
                    <div className="mt-0.5 text-[var(--shell-text-muted)]">{item.suggestion}</div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Editorial summary */}
      {gb.editorialSummary && (
        <div className="border-l-2 border-[var(--shell-border)] pl-3 text-xs italic leading-relaxed text-[var(--shell-text-muted)]">
          "{gb.editorialSummary}"
        </div>
      )}

      {/* Reviews section */}
      {sortedReviews.length > 0 && (
        <div className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4">
          <div className="mb-2 flex items-center justify-between">
            <div className="text-sm font-medium text-[var(--shell-text)]">
              Reviews ({sortedReviews.length})
            </div>
            <div className="flex items-center gap-2 text-xs">
              <span className="text-yellow-400">
                {"*".repeat(Math.round(gb.rating ?? 0))} {gb.rating ?? "-"}
              </span>
              {gb.reviewCount != null && (
                <span className="text-[var(--shell-text-muted)]">({gb.reviewCount.toLocaleString()} total)</span>
              )}
            </div>
          </div>

          {/* Sentiment bar */}
          {ra && (
            <div className="mb-4">
              <div className="flex h-2 overflow-hidden rounded-full bg-[var(--shell-panel-strong)]">
                {ra.sentimentBreakdown.positive > 0 && (
                  <div className="bg-[var(--shell-positive)]" style={{ width: `${(ra.sentimentBreakdown.positive / (sortedReviews.length || 1)) * 100}%` }} />
                )}
                {ra.sentimentBreakdown.neutral > 0 && (
                  <div className="bg-[var(--shell-text-soft)]" style={{ width: `${(ra.sentimentBreakdown.neutral / (sortedReviews.length || 1)) * 100}%` }} />
                )}
                {ra.sentimentBreakdown.negative > 0 && (
                  <div className="bg-[var(--shell-danger)]" style={{ width: `${(ra.sentimentBreakdown.negative / (sortedReviews.length || 1)) * 100}%` }} />
                )}
              </div>
              <div className="mt-1.5 flex items-center justify-between text-[10px]">
                <div className="flex items-center gap-3">
                  <span className="text-[var(--shell-positive)]">Positive {ra.sentimentBreakdown.positive}</span>
                  <span className="text-[var(--shell-text-muted)]">Neutral {ra.sentimentBreakdown.neutral}</span>
                  <span className="text-[var(--shell-danger)]">Negative {ra.sentimentBreakdown.negative}</span>
                </div>
                {ra.recentTrend !== "unknown" && (
                  <span className={`rounded-full px-2 py-0.5 text-[10px] ${
                    ra.recentTrend === "improving"
                      ? "bg-[color-mix(in_srgb,var(--shell-positive)_12%,transparent)] text-[var(--shell-positive)]"
                      : "bg-[color-mix(in_srgb,var(--shell-danger)_12%,transparent)] text-[var(--shell-danger)]"
                  }`}>
                    {ra.recentTrend === "improving" ? "Improving" : "Declining"}
                  </span>
                )}
              </div>
              {ra.topKeywords?.length > 0 && (
                <div className="mt-2 flex flex-wrap gap-1">
                  {ra.topKeywords.map((kw) => (
                    <span key={kw.keyword} className={`rounded-full border px-2 py-0.5 text-[10px] ${
                      kw.sentiment === "positive"
                        ? "border-[var(--shell-positive)]/30 text-[var(--shell-positive)]"
                        : kw.sentiment === "negative"
                          ? "border-[var(--shell-danger)]/30 text-[var(--shell-danger)]"
                          : "border-[var(--shell-border)] text-[var(--shell-text-muted)]"
                    }`}>
                      {kw.keyword} ({kw.count})
                    </span>
                  ))}
                </div>
              )}
            </div>
          )}

          {/* Review list */}
          <div className="space-y-2">
            {sortedReviews.map((r) => {
              const rk = reviewKey(r);
              const isExpanded = expandedReview === rk;
              return (
                <div
                  key={rk}
                  className={`cursor-pointer rounded-xl border p-3 transition-colors ${
                    r.sentiment === "positive"
                      ? "border-[var(--shell-positive)]/15 bg-[color-mix(in_srgb,var(--shell-positive)_4%,transparent)]"
                      : r.sentiment === "negative"
                        ? "border-[var(--shell-danger)]/15 bg-[color-mix(in_srgb,var(--shell-danger)_4%,transparent)]"
                        : "border-[var(--shell-border)] bg-[var(--shell-panel)]"
                  }`}
                  onClick={() => setExpandedReview(isExpanded ? null : rk)}
                >
                  <div className="flex items-center gap-2 text-xs">
                    <span className="text-yellow-400">{"*".repeat(r.rating)}</span>
                    <span className={`rounded px-1.5 py-0.5 text-[10px] ${
                      r.sentiment === "positive"
                        ? "bg-[color-mix(in_srgb,var(--shell-positive)_12%,transparent)] text-[var(--shell-positive)]"
                        : r.sentiment === "negative"
                          ? "bg-[color-mix(in_srgb,var(--shell-danger)_12%,transparent)] text-[var(--shell-danger)]"
                          : "bg-[var(--shell-panel-strong)] text-[var(--shell-text-muted)]"
                    }`}>
                      {r.sentiment}
                    </span>
                    <span className="text-[var(--shell-text-muted)]">{r.authorName}</span>
                    <span className="ml-auto text-[var(--shell-text-muted)]">{r.publishDate || r.relativeTime}</span>
                  </div>
                  {r.text && (
                    <div className={`mt-1 text-xs leading-relaxed text-[var(--shell-text-muted)] ${isExpanded ? "" : "line-clamp-2"}`}>
                      {r.text}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}
