import { useState } from "react";
import { Link } from "react-router-dom";
import { ScoreGauge } from "./helpers";
import { useCommand } from "../../hooks/useCommand";
import type { Board } from "../../db/collections";

interface GeoProbeEntry {
  id: string;
  question?: string;
  category?: string;
  engine?: string;
  ourSiteMentioned?: boolean;
  ourSiteInResults?: boolean;
  mentionContext?: string;
  answer?: string;
  competitors?: Array<{ name: string; mentioned: boolean }>;
  origin?: string;
}

interface DashboardGeoProbeProps {
  id: string;
  geoProbes: GeoProbeEntry[];
  seoScore: number;
  geoScore: number;
  board: Board | null;
  onProbesChanged?: () => void;
}

const ENGINE_ORDER = ["gpt", "claude", "gemini", "perplexity"];
const CATEGORY_LABELS: Record<string, string> = {
  brand: "Brand", product: "Product", comparison: "Comparison",
  advice: "Advice", review: "Review", industry: "Industry", local: "Local",
};

export function DashboardGeoProbe({ id, geoProbes, seoScore, geoScore, board, onProbesChanged }: DashboardGeoProbeProps) {
  const [expandedQ, setExpandedQ] = useState<string | null>(null);
  const [newQuestion, setNewQuestion] = useState("");
  const [probeFilter, setProbeFilter] = useState<"all" | "user" | "strategy">("all");
  const cmd = useCommand(id);

  const stepStatus = board?.stepStatus ?? {};
  const probeRunning = stepStatus.geoProbe === "running";

  const engineMap = new Map<string, { total: number; mentioned: number; exposed: number }>();
  for (const p of geoProbes) {
    const e = p.engine ?? "unknown";
    const entry = engineMap.get(e) ?? { total: 0, mentioned: 0, exposed: 0 };
    entry.total++;
    if (p.ourSiteMentioned) entry.mentioned++;
    if (p.ourSiteInResults) entry.exposed++;
    engineMap.set(e, entry);
  }

  const engineBreakdown = ENGINE_ORDER.map((engine) => {
    const d = engineMap.get(engine);
    if (!d) return null;
    return {
      engine,
      totalQuestions: d.total,
      mentionedCount: d.mentioned,
      exposedCount: d.exposed,
      mentionRate: d.total > 0 ? Math.round((d.mentioned / d.total) * 100) : 0,
      exposureRate: d.total > 0 ? Math.round((d.exposed / d.total) * 100) : 0,
    };
  }).filter(Boolean) as Array<{ engine: string; totalQuestions: number; mentionedCount: number; exposedCount: number; mentionRate: number; exposureRate: number }>;

  const overallMentionRate = geoProbes.length > 0 ? Math.round((geoProbes.filter((p) => p.ourSiteMentioned).length / geoProbes.length) * 100) : 0;
  const overallExposureRate = geoProbes.length > 0 ? Math.round((geoProbes.filter((p) => p.ourSiteInResults).length / geoProbes.length) * 100) : 0;

  const questionGroups = new Map<string, Array<GeoProbeEntry & { engine: string }>>();
  for (const p of geoProbes) {
    const q = p.question || "Unknown";
    const list = questionGroups.get(q) ?? [];
    list.push({ ...p, engine: p.engine || "unknown" });
    questionGroups.set(q, list);
  }

  const filteredQuestions = Array.from(questionGroups.entries()).filter(([, entries]) => {
    if (probeFilter === "all") return true;
    if (probeFilter === "user") return entries.some((e) => e.origin === "user");
    return entries.some((e) => e.origin !== "user");
  });

  const handleAddQuestion = async () => {
    const q = newQuestion.trim();
    if (!q) return;
    await cmd.execute("run_geo_probe", { question: q });
    setNewQuestion("");
    onProbesChanged?.();
  };

  const handleDownloadProposal = () => {
    const report = {
      generatedAt: new Date().toISOString(),
      seoScore, geoScore, overallMentionRate, overallExposureRate,
      engineBreakdown,
      questions: Array.from(questionGroups.entries()).map(([question, entries]) => ({
        question,
        mentioned: entries.some((e) => e.ourSiteMentioned),
        engines: entries.map((e) => ({ engine: e.engine, mentioned: e.ourSiteMentioned, exposed: e.ourSiteInResults })),
      })),
    };
    const blob = new Blob([JSON.stringify(report, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `geo-probe-report-${id}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <section className="shell-transition rounded-[22px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
      <div className="flex items-center justify-between gap-3">
        <div>
          <div className="text-[11px] uppercase tracking-[0.18em] text-[var(--shell-text-soft)]">GEO Probe Visibility</div>
          <div className="mt-2 text-xl font-semibold text-[var(--shell-text)]">AI Engine Visibility</div>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={handleDownloadProposal} disabled={geoProbes.length === 0} className="shell-transition rounded-lg border border-[var(--shell-border)] px-2.5 py-1.5 text-[11px] text-[var(--shell-text-muted)] hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)] disabled:opacity-40">
            Download
          </button>
          <Link to={`/board/${id}/ai-answers`} className="text-xs uppercase tracking-[0.12em] text-[var(--shell-accent)] hover:text-[var(--shell-accent-strong)]">
            AI Answers
          </Link>
        </div>
      </div>

      {/* Progress indicator */}
      {probeRunning && (
        <div className="mt-3 rounded-xl border border-[var(--shell-accent)]/30 bg-[color-mix(in_srgb,var(--shell-accent)_6%,transparent)] px-4 py-3">
          <div className="flex items-center gap-2 text-sm text-[var(--shell-accent)]">
            <span className="inline-block h-2 w-2 animate-pulse rounded-full bg-[var(--shell-accent)]" />
            GEO Probe running...
          </div>
          <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-[var(--shell-panel-strong)]">
            <div className="h-full animate-pulse rounded-full bg-[var(--shell-accent)]" style={{ width: "60%" }} />
          </div>
        </div>
      )}

      {/* Score gauges */}
      <div className="mt-5 flex flex-wrap items-center gap-6">
        <ScoreGauge label="SEO" value={seoScore} />
        <ScoreGauge label="GEO" value={geoScore} />
        <div className="ml-auto text-right">
          <div className="text-3xl font-semibold text-[var(--shell-text)]">{overallMentionRate}%</div>
          <div className="text-xs text-[var(--shell-text-muted)]">Overall Mention Rate</div>
          <div className="mt-1 text-xs text-[var(--shell-positive)]">Exposure {overallExposureRate}%</div>
        </div>
      </div>

      {/* Engine cards */}
      <div className="mt-5 grid gap-3 md:grid-cols-4">
        {engineBreakdown.length > 0 ? (
          engineBreakdown.map((eng) => (
            <div key={eng.engine} className="shell-transition rounded-[16px] border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4">
              <div className="text-sm uppercase tracking-[0.08em] text-[var(--shell-text-muted)]">{eng.engine}</div>
              <div className="mt-2 text-3xl font-semibold text-[var(--shell-text)]">{eng.mentionRate}%</div>
              <div className="mt-1 text-xs text-[var(--shell-text-soft)]">Mentioned {eng.mentionedCount}/{eng.totalQuestions}</div>
              <div className="mt-2 text-xs text-[var(--shell-positive)]">Exposure {eng.exposureRate}%</div>
            </div>
          ))
        ) : (
          <div className="col-span-full rounded-[16px] border border-dashed border-[var(--shell-border)] px-4 py-6 text-sm text-[var(--shell-text-soft)]">
            GEO Probe results are not yet available.
          </div>
        )}
      </div>

      {/* Add question */}
      <div className="mt-5 flex items-center gap-2">
        <input
          value={newQuestion}
          onChange={(e) => setNewQuestion(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && handleAddQuestion()}
          placeholder="Add a custom probe question..."
          className="shell-input flex-1 rounded-xl px-3 py-2.5 text-sm"
        />
        <button onClick={handleAddQuestion} disabled={cmd.isRunning || !newQuestion.trim()} className="shell-button-primary rounded-xl px-4 py-2.5 text-sm font-medium disabled:opacity-40">
          {cmd.isRunning ? "..." : "Probe"}
        </button>
      </div>

      {/* Question list */}
      {questionGroups.size > 0 && (
        <div className="mt-5 border-t border-[var(--shell-border)] pt-5">
          <div className="mb-3 flex items-center justify-between">
            <div className="text-[11px] uppercase tracking-[0.14em] text-[var(--shell-text-muted)]">
              Probe Results ({filteredQuestions.length} questions)
            </div>
            <div className="flex gap-1">
              {(["all", "user", "strategy"] as const).map((f) => (
                <button key={f} onClick={() => setProbeFilter(f)}
                  className={`rounded-full px-2 py-0.5 text-[10px] ${probeFilter === f ? "bg-[var(--shell-accent-soft)] text-[var(--shell-accent)]" : "text-[var(--shell-text-muted)]"}`}
                >
                  {f === "all" ? "All" : f === "user" ? "Custom" : "Strategy"}
                </button>
              ))}
            </div>
          </div>
          <div className="max-h-[400px] space-y-2 overflow-y-auto">
            {filteredQuestions.slice(0, 20).map(([question, entries]) => {
              const mentioned = entries.some((e) => e.ourSiteMentioned);
              const expanded = expandedQ === question;
              return (
                <div key={question} className="shell-transition rounded-[14px] border border-[var(--shell-border)] bg-[var(--shell-panel-soft)]">
                  <button onClick={() => setExpandedQ(expanded ? null : question)} className="flex w-full items-center gap-3 px-4 py-3 text-left">
                    <span className={`inline-block h-2 w-2 shrink-0 rounded-full ${mentioned ? "bg-[var(--shell-positive)]" : "bg-[var(--shell-border)]"}`} />
                    <span className="flex-1 text-sm text-[var(--shell-text)]">{question}</span>
                    <span className="text-[11px] text-[var(--shell-text-soft)]">
                      {CATEGORY_LABELS[entries[0]?.category || ""] || entries[0]?.category || ""}
                    </span>
                    <div className="flex gap-1">
                      {entries.map((e) => (
                        <span key={e.engine} className={`rounded px-1.5 py-0.5 text-[9px] uppercase ${
                          e.ourSiteMentioned
                            ? "bg-[color-mix(in_srgb,var(--shell-positive)_18%,transparent)] text-[var(--shell-positive)]"
                            : "bg-[var(--shell-panel-strong)] text-[var(--shell-text-soft)]"
                        }`}>{e.engine.slice(0, 3)}</span>
                      ))}
                    </div>
                  </button>
                  {expanded && (
                    <div className="border-t border-[var(--shell-border)] px-4 py-3">
                      {entries.map((e) => (
                        <div key={e.engine} className="mb-2 last:mb-0">
                          <div className="flex items-center gap-2 text-xs">
                            <span className="font-medium uppercase text-[var(--shell-text-muted)]">{e.engine}</span>
                            {e.ourSiteMentioned && <span className="text-[var(--shell-positive)]">Mentioned</span>}
                            {e.ourSiteInResults && !e.ourSiteMentioned && <span className="text-[var(--shell-secondary)]">Exposed</span>}
                          </div>
                          {e.mentionContext && <div className="mt-1 text-xs leading-5 text-[var(--shell-text-soft)]">{e.mentionContext}</div>}
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}
    </section>
  );
}
