import { Routes, Route, Navigate } from "react-router-dom";
import { RequireAuth } from "./components/RequireAuth";
import { BoardLayout } from "./components/BoardLayout";
import { Landing } from "./pages/Landing";
import { Login } from "./pages/Login";
import { Onboarding } from "./pages/Onboarding";
import { Dashboard } from "./pages/Dashboard";
import { Queries } from "./pages/Queries";
import { AiAnswers } from "./pages/AiAnswers";
import { Problems } from "./pages/Problems";
import { Actions } from "./pages/Actions";
import { AnalysisHub } from "./pages/AnalysisHub";
import { Analytics } from "./pages/Analytics";
import { PlanPredict } from "./pages/PlanPredict";
import { CreateDeploy } from "./pages/CreateDeploy";
import { Trends } from "./pages/Trends";
import { Automation } from "./pages/Automation";
import { Manage } from "./pages/Manage";
import { Competitors } from "./pages/Competitors";
import { Documents } from "./pages/Documents";
import { Chat } from "./pages/Chat";

export function App() {
  return (
    <Routes>
      <Route path="/login" element={<Login />} />
      <Route element={<RequireAuth />}>
        <Route path="/" element={<Landing />} />
        <Route path="/onboarding/:id" element={<Onboarding />} />
        <Route path="/board/:id" element={<BoardLayout />}>
          <Route index element={<Dashboard />} />
          <Route path="queries" element={<Queries />} />
          <Route path="ai-answers" element={<AiAnswers />} />
          <Route path="problems" element={<Problems />} />
          <Route path="actions" element={<Actions />} />
          <Route path="analysis" element={<AnalysisHub />} />
          <Route path="analysis/:section" element={<AnalysisHub />} />
          <Route path="analytics" element={<Analytics />} />
          <Route path="analytics/:tab" element={<Analytics />} />
          <Route path="plan" element={<PlanPredict />} />
          <Route path="plan/:section" element={<PlanPredict />} />
          <Route path="create-deploy" element={<CreateDeploy />} />
          <Route path="create-deploy/:section" element={<CreateDeploy />} />
          <Route path="trends" element={<Trends />} />
          <Route path="automation" element={<Automation />} />
          <Route path="manage" element={<Manage />} />
          <Route path="manage/:section" element={<Manage />} />
          <Route path="competitors" element={<Competitors />} />
          <Route path="documents" element={<Documents />} />
          <Route path="documents/:docKey" element={<Documents />} />
          <Route path="chat" element={<Chat />} />
        </Route>
      </Route>
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
}
