import { useState } from "react";
import { ChevronDown, X } from "lucide-react";
import type { GoogleKeywordAnalysis } from "../../../db/collections";

interface DiagnosisGoogleTabProps {
  data: GoogleKeywordAnalysis | null;
  stepDone: boolean;
}

export function DiagnosisGoogleTab({ data, stepDone }: DiagnosisGoogleTabProps) {
  const [selectedKeyword, setSelectedKeyword] = useState<string | null>(null);

  if (!data && !stepDone) {
    return (
      <div className="py-8 text-center text-sm text-[var(--shell-text-muted)]">
        <div className="mb-2 animate-pulse">Collecting Google keyword data...</div>
        <div className="text-xs">Will start automatically after SEO analysis.</div>
      </div>
    );
  }
  if (!data) {
    return (
      <div className="py-8 text-center text-sm text-[var(--shell-text-muted)]">
        No Google keyword analysis data available.
      </div>
    );
  }

  const { metrics, presence, competitorDomains } = data;
  const hasGoogleAds = metrics.some((m) => m.averageMonthlySearches > 0);

  const googleScore: number = data.googleScore ?? (() => {
    if (presence.length === 0 && metrics.length === 0) return 0;
    const presenceScore = presence.length > 0 ? (presence.filter((p) => p.found).length / presence.length) * 100 : 0;
    const positionScores = presence.map((p) => {
      if (!p.found || p.position == null) return 0;
      if (p.position <= 3) return 90;
      if (p.position <= 10) return 70;
      if (p.position <= 20) return 50;
      return 30;
    });
    const positionScore = positionScores.length > 0 ? positionScores.reduce<number>((s, p) => s + p, 0) / positionScores.length : 0;
    return Math.min(100, Math.max(0, Math.round(0.5 * presenceScore + 0.5 * positionScore)));
  })();

  const presenceMap = new Map(presence.map((p) => [p.keyword, p]));
  const metricsMap = new Map(metrics.map((m) => [m.keyword, m]));
  const allKeywords = [...new Set([...metrics.map((m) => m.keyword), ...presence.map((p) => p.keyword)])];
  const sortedKeywords = allKeywords
    .map((kw) => ({ keyword: kw, volume: metricsMap.get(kw)?.averageMonthlySearches ?? 0, metric: metricsMap.get(kw), presence: presenceMap.get(kw) }))
    .sort((a, b) => b.volume - a.volume);

  const exposedKeywords = presence.filter((p) => p.found).length;
  const exposureRate = presence.length > 0 ? Math.round((exposedKeywords / presence.length) * 100) : 0;
  const avgPosition = (() => {
    const found = presence.filter((p) => p.found && p.position != null);
    if (found.length === 0) return null;
    return Math.round((found.reduce((sum, p) => sum + p.position!, 0) / found.length) * 10) / 10;
  })();
  const totalVolume = metrics.reduce((sum, m) => sum + m.averageMonthlySearches, 0);

  const scoreColor = googleScore >= 80 ? "text-[var(--shell-positive)]" : googleScore >= 50 ? "text-[var(--shell-secondary)]" : "text-[var(--shell-danger)]";
  const barColor = googleScore >= 80 ? "bg-[var(--shell-positive)]" : googleScore >= 50 ? "bg-[var(--shell-secondary)]" : "bg-[var(--shell-danger)]";

  const compColor = (c: string) =>
    c === "HIGH" ? "bg-[color-mix(in_srgb,var(--shell-danger)_15%,transparent)] text-[var(--shell-danger)]"
    : c === "MEDIUM" ? "bg-[color-mix(in_srgb,var(--shell-secondary)_15%,transparent)] text-[var(--shell-secondary)]"
    : "bg-[color-mix(in_srgb,var(--shell-positive)_15%,transparent)] text-[var(--shell-positive)]";
  const compLabel = (c: string) => c === "HIGH" ? "High" : c === "MEDIUM" ? "Med" : c === "LOW" ? "Low" : "-";

  return (
    <div className="space-y-4 text-sm">
      {/* Summary card */}
      <div className="flex items-center gap-4 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4">
        <div className="min-w-[60px] text-center">
          <div className={`text-3xl font-bold ${scoreColor}`}>{googleScore}</div>
          <div className="text-[10px] text-[var(--shell-text-muted)]">/ 100</div>
        </div>
        <div className="flex-1 space-y-2">
          <div className="h-1.5 overflow-hidden rounded-full bg-[var(--shell-panel-strong)]">
            <div className={`h-full rounded-full ${barColor}`} style={{ width: `${googleScore}%` }} />
          </div>
          <div className="grid grid-cols-2 gap-x-3 gap-y-1 text-xs text-[var(--shell-text-muted)]">
            <div>{presence.length} keywords, <span className="font-medium text-[var(--shell-text)]">{exposedKeywords} exposed</span> ({exposureRate}%)</div>
            <div>Avg position: <span className="font-medium text-[var(--shell-text)]">{avgPosition != null ? `#${avgPosition}` : "-"}</span></div>
            {hasGoogleAds && totalVolume > 0 && <div>Total monthly: <span className="font-medium text-[var(--shell-text)]">{totalVolume.toLocaleString()}</span></div>}
          </div>
        </div>
      </div>

      {/* Keyword table */}
      {sortedKeywords.length > 0 && (
        <div>
          <div className="mb-2 text-sm font-medium text-[var(--shell-text)]">Keyword Analysis ({sortedKeywords.length})</div>
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead>
                <tr className="border-b border-[var(--shell-border)] text-[var(--shell-text-muted)]">
                  <th className="py-2 pr-2 text-left">Keyword</th>
                  {hasGoogleAds && <th className="px-1 py-2 text-right">Volume</th>}
                  <th className="px-1 py-2 text-center">Position</th>
                  {hasGoogleAds && <th className="px-1 py-2 text-center">Competition</th>}
                  {hasGoogleAds && <th className="py-2 pl-1 text-right">CPC</th>}
                </tr>
              </thead>
              <tbody>
                {sortedKeywords.map(({ keyword, volume, metric, presence: p }) => (
                  <tr
                    key={keyword}
                    className="cursor-pointer border-b border-[var(--shell-border)]/30 hover:bg-[var(--shell-panel-soft)]"
                    onClick={() => setSelectedKeyword(keyword)}
                  >
                    <td className="max-w-[160px] truncate py-2 pr-2 text-[var(--shell-text)]">{keyword}</td>
                    {hasGoogleAds && <td className="px-1 py-2 text-right tabular-nums font-medium text-[var(--shell-text)]">{volume.toLocaleString()}</td>}
                    <td className={`px-1 py-2 text-center font-medium ${p?.found ? "text-[var(--shell-positive)]" : "text-[var(--shell-text-muted)]"}`}>
                      {p?.found ? `#${p.position}` : p ? "Not found" : "--"}
                    </td>
                    {hasGoogleAds && (
                      <td className="px-1 py-2 text-center">
                        {metric ? <span className={`rounded px-1.5 py-0.5 text-[10px] ${compColor(metric.competition)}`}>{compLabel(metric.competition)}</span> : "--"}
                      </td>
                    )}
                    {hasGoogleAds && (
                      <td className="py-2 pl-1 text-right tabular-nums text-[var(--shell-text-muted)]">
                        {metric?.highTopOfPageBidKrw ? `$${metric.highTopOfPageBidKrw.toLocaleString()}` : "--"}
                      </td>
                    )}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Competitor domains */}
      {competitorDomains?.length > 0 && (
        <details className="group" open>
          <summary className="mb-2 flex cursor-pointer items-center gap-1 text-sm font-medium text-[var(--shell-text)]">
            Google Competitors ({competitorDomains.length})
            <ChevronDown className="h-3 w-3 text-[var(--shell-text-muted)] transition-transform group-open:rotate-180" />
          </summary>
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead>
                <tr className="border-b border-[var(--shell-border)] text-[var(--shell-text-muted)]">
                  <th className="py-2 pr-1 text-left">Domain</th>
                  <th className="w-16 py-2 text-right">Appears</th>
                  <th className="w-16 py-2 text-right">Avg Rank</th>
                </tr>
              </thead>
              <tbody>
                {competitorDomains.map((c, i) => (
                  <tr key={i} className="border-b border-[var(--shell-border)]/30 hover:bg-[var(--shell-panel-soft)]">
                    <td className="max-w-[200px] truncate py-2 pr-1 text-[var(--shell-text)]">{c.domain}</td>
                    <td className="w-16 py-2 text-right tabular-nums text-[var(--shell-text-muted)]">{c.appearances}</td>
                    <td className="w-16 py-2 text-right tabular-nums text-[var(--shell-text-muted)]">#{c.avgPosition}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </details>
      )}

      {/* Keyword detail panel */}
      {selectedKeyword && (() => {
        const metric = metricsMap.get(selectedKeyword);
        const pres = presenceMap.get(selectedKeyword);
        return (
          <>
            <div className="fixed inset-0 z-40 bg-black/40" onClick={() => setSelectedKeyword(null)} />
            <div className="fixed right-0 top-0 z-50 h-full w-[380px] max-w-[90vw] overflow-y-auto border-l border-[var(--shell-border)] bg-[var(--shell-panel)]" style={{ animation: "slideInRight 0.2s ease-out" }}>
              <div className="sticky top-0 flex items-center justify-between border-b border-[var(--shell-border)] bg-[var(--shell-panel)] px-4 py-3">
                <div className="truncate text-sm font-medium text-[var(--shell-text)]">{selectedKeyword}</div>
                <button onClick={() => setSelectedKeyword(null)} className="rounded p-1 text-[var(--shell-text-muted)] hover:bg-[var(--shell-panel-soft)] hover:text-[var(--shell-text)]">
                  <X className="h-4 w-4" />
                </button>
              </div>
              <div className="space-y-4 p-4">
                {metric && (
                  <div className="grid grid-cols-3 gap-2">
                    <StatCard label="Monthly Vol" value={metric.averageMonthlySearches.toLocaleString()} />
                    <StatCard label="Competition" value={compLabel(metric.competition)} color={metric.competition === "HIGH" ? "var(--shell-danger)" : metric.competition === "MEDIUM" ? "var(--shell-secondary)" : "var(--shell-positive)"} />
                    <StatCard label="Position" value={pres?.found ? `#${pres.position}` : "N/A"} color={pres?.found ? "var(--shell-positive)" : undefined} />
                  </div>
                )}
                {pres?.competitors && pres.competitors.length > 0 && (
                  <div>
                    <div className="mb-2 text-sm font-medium text-[var(--shell-text)]">Competing Pages</div>
                    <div className="space-y-1.5">
                      {pres.competitors.slice(0, 10).map((c, i) => (
                        <div key={i} className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2">
                          <div className="flex items-center gap-2 text-xs">
                            <span className="font-medium text-[var(--shell-positive)]">#{c.position}</span>
                            <span className="text-[var(--shell-text-muted)]">{c.domain}</span>
                          </div>
                          <div className="truncate text-xs text-[var(--shell-text)]">{c.title}</div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
                {!metric && !pres && (
                  <div className="py-3 text-center text-xs text-[var(--shell-text-muted)]">No detailed data for this keyword.</div>
                )}
              </div>
            </div>
          </>
        );
      })()}
    </div>
  );
}

function StatCard({ label, value, color }: { label: string; value: string; color?: string }) {
  return (
    <div className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3 text-center">
      <div className="text-[10px] text-[var(--shell-text-muted)]">{label}</div>
      <div className="mt-1 text-lg font-bold" style={color ? { color } : { color: "var(--shell-text)" }}>{value}</div>
    </div>
  );
}
