import { useEffect, useMemo, useState, useRef } from "react";
import { useParams } from "react-router-dom";
import { listGeoProbes, getDocument } from "../db/boards";
import { useCommand, type LogLine } from "../hooks/useCommand";
import type { BoardDocument } from "../db/collections";

interface Probe {
  id: string;
  question: string;
  category: string;
  engine: string;
  status: string;
  answer: string;
  ourSiteInResults: boolean;
  ourSiteMentioned: boolean;
  ourMentionContext: string;
}

interface VisQuestion {
  question: string;
  category: string;
  engines: Array<{
    engine: string;
    inResults: boolean;
    mentioned: boolean;
    mentionContext?: string;
  }>;
}

interface EngineBreakdown {
  engine: string;
  totalQuestions: number;
  exposedCount: number;
  mentionedCount: number;
  exposureRate: number;
  mentionRate: number;
}

const ENGINE_LABELS: Record<string, string> = {
  gpt: "ChatGPT",
  openai: "ChatGPT",
  gemini: "Gemini",
  claude: "Claude",
  perplexity: "Perplexity",
};

const CATEGORY_LABELS: Record<string, string> = {
  product: "제품/서비스",
  comparison: "비교",
  howto: "방법/가이드",
  local: "지역",
  brand: "브랜드",
};

export function AiAnswers() {
  const { id } = useParams<{ id: string }>();
  const [probes, setProbes] = useState<Probe[]>([]);
  const [visDoc, setVisDoc] = useState<BoardDocument | null>(null);
  const [loading, setLoading] = useState(true);
  const [showLog, setShowLog] = useState(false);
  const cmd = useCommand(id);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    Promise.all([
      listGeoProbes(id).catch(() => []),
      getDocument(id, "geo-visibility").catch(() => null),
    ]).then(([p, v]) => {
      setProbes(p as Probe[]);
      setVisDoc(v);
      setLoading(false);
    });
  }, [id]);

  const handleRunProbe = async () => {
    await cmd.execute("run_geo_probe");
    if (id) {
      const [p, v] = await Promise.all([
        listGeoProbes(id).catch(() => []),
        getDocument(id, "geo-visibility").catch(() => null),
      ]);
      setProbes(p as Probe[]);
      setVisDoc(v);
    }
  };

  const visData = (visDoc?.data ?? {}) as Record<string, unknown>;
  const engineBreakdown = (visData.engineBreakdown ?? []) as EngineBreakdown[];
  const mentionRate = (visData.mentionRate as number) ?? 0;
  const exposureRate = (visData.exposureRate as number) ?? 0;
  const completedQuestions = (visData.completedQuestions as number) ?? 0;
  const visQuestions = (visData.questions ?? []) as VisQuestion[];

  const completed = probes.filter((p) => p.status === "completed");
  const totalAnswers = completed.length || completedQuestions;
  const recommendedCount = completed.length > 0
    ? completed.filter((p) => p.ourSiteMentioned).length
    : engineBreakdown.reduce((s, e) => s + e.mentionedCount, 0);
  const recommendedRate = totalAnswers > 0
    ? Math.round((recommendedCount / totalAnswers) * 100)
    : 0;

  const groupedFromProbes = useMemo(() => {
    const map = new Map<string, Probe[]>();
    for (const probe of probes) {
      map.set(probe.question, [...(map.get(probe.question) || []), probe]);
    }
    return [...map.entries()].map(([question, items]) => ({ question, items }));
  }, [probes]);

  const hasProbeDetails = groupedFromProbes.length > 0;
  const hasVisQuestions = visQuestions.length > 0;

  if (loading) {
    return (
      <div className="flex min-h-[40vh] items-center justify-center text-[var(--shell-text-muted)]">
        데이터 로딩 중...
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-[1400px] space-y-6">
      {/* Header */}
      <header className="flex items-end justify-between gap-4">
        <div>
          <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">
            AI Answers
          </div>
          <h1 className="mt-2 text-3xl font-semibold text-[var(--shell-text)]">
            AI 답변 시뮬레이션
          </h1>
          <p className="mt-2 text-sm text-[var(--shell-text-muted)]">
            ChatGPT, Gemini, Claude 등에서 브랜드가 답변과 출처에 포함되는지 측정합니다.
          </p>
        </div>
        <div className="flex items-center gap-2">
          {cmd.logLines.length > 0 && (
            <button
              type="button"
              onClick={() => setShowLog((v) => !v)}
              className={`flex items-center gap-1.5 rounded-xl border px-3.5 py-2.5 text-sm font-medium transition-colors ${
                showLog
                  ? "border-[var(--shell-accent)]/40 bg-[var(--shell-accent)]/10 text-[var(--shell-accent)]"
                  : "border-[var(--shell-border)] text-[var(--shell-text-muted)] hover:border-[var(--shell-accent)]/30 hover:text-[var(--shell-accent)]"
              }`}
            >
              <svg className="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">
                <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
                <polyline points="14 2 14 8 20 8" />
                <line x1="16" y1="13" x2="8" y2="13" />
                <line x1="16" y1="17" x2="8" y2="17" />
              </svg>
              로그
              <span className="rounded-md bg-[var(--shell-accent)]/15 px-1.5 py-0.5 text-[10px] tabular-nums text-[var(--shell-accent)]">
                {cmd.logLines.length}
              </span>
            </button>
          )}
          <button
            type="button"
            onClick={handleRunProbe}
            disabled={cmd.isRunning}
            className="shell-button-primary rounded-xl px-5 py-2.5 text-sm font-medium disabled:opacity-50"
          >
            {cmd.isRunning ? "시뮬레이션 중..." : "시뮬레이션 실행"}
          </button>
        </div>
      </header>

      {/* Running status */}
      {cmd.isRunning && (
        <CommandProgressPanel
          progress={cmd.progress}
          message={cmd.message}
          logLines={cmd.logLines}
        />
      )}

      {/* Failed status */}
      {cmd.isFailed && (
        <div className="shell-transition rounded-[16px] border border-[var(--shell-danger)]/40 bg-[var(--shell-danger)]/5 px-5 py-4">
          <div className="flex items-start gap-3">
            <svg className="mt-0.5 h-5 w-5 shrink-0 text-[var(--shell-danger)]" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2}>
              <circle cx="12" cy="12" r="10" />
              <line x1="15" y1="9" x2="9" y2="15" />
              <line x1="9" y1="9" x2="15" y2="15" />
            </svg>
            <div className="min-w-0 flex-1">
              <div className="text-sm font-medium text-[var(--shell-danger)]">
                시뮬레이션 실패
              </div>
              {cmd.error && (
                <p className="mt-1.5 text-xs leading-5 text-[var(--shell-text-muted)] break-all">
                  {cmd.error}
                </p>
              )}
              <button
                type="button"
                onClick={handleRunProbe}
                className="mt-3 rounded-lg border border-[var(--shell-danger)]/30 px-3 py-1.5 text-xs font-medium text-[var(--shell-danger)] transition-colors hover:bg-[var(--shell-danger)]/10"
              >
                다시 실행
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Standalone log panel (toggled via header button, visible when not running) */}
      {showLog && !cmd.isRunning && cmd.logLines.length > 0 && (
        <div className="shell-transition rounded-[16px] border border-[var(--shell-border)] bg-[var(--shell-panel)] px-5 py-4">
          <CommandLogLines logLines={cmd.logLines} maxVisible={8} />
        </div>
      )}

      {/* Metric cards */}
      <section className="grid gap-3 md:grid-cols-4">
        <MetricCard label="총 답변" value={`${totalAnswers}`} />
        <MetricCard label="언급률" value={`${mentionRate}%`} tone="accent" />
        <MetricCard label="출처 노출률" value={`${exposureRate}%`} tone="positive" />
        <MetricCard label="추천 포함률" value={`${recommendedRate}%`} tone="secondary" />
      </section>

      {/* Engine breakdown */}
      {engineBreakdown.length > 0 && (
        <section className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {engineBreakdown.map((eng) => (
            <div
              key={eng.engine}
              className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]"
            >
              <div className="flex items-center justify-between">
                <div className="text-sm font-medium text-[var(--shell-text)]">
                  {ENGINE_LABELS[eng.engine] || eng.engine}
                </div>
                <div className="text-xs text-[var(--shell-text-soft)]">
                  {eng.mentionedCount}/{eng.totalQuestions} 언급
                </div>
              </div>
              <div className="mt-3 grid grid-cols-2 gap-3">
                <MiniStat label="노출" value={`${eng.exposureRate}%`} />
                <MiniStat label="언급" value={`${eng.mentionRate}%`} />
              </div>
            </div>
          ))}
        </section>
      )}

      {/* Question groups -- prefer probes, fallback to visQuestions */}
      <section className="space-y-3">
        {hasProbeDetails ? (
          groupedFromProbes.map((group) => (
            <QuestionGroup
              key={group.question}
              question={group.question}
              items={group.items}
            />
          ))
        ) : hasVisQuestions ? (
          visQuestions.map((vq) => (
            <VisQuestionGroup key={vq.question} data={vq} />
          ))
        ) : (
          <div className="shell-transition rounded-[18px] border border-dashed border-[var(--shell-border)] bg-[var(--shell-panel)] p-8 text-center text-sm text-[var(--shell-text-muted)]">
            아직 AI 답변 측정 데이터가 없습니다. 상단의 시뮬레이션을 실행하면
            엔진별 답변이 쌓입니다.
          </div>
        )}
      </section>
    </div>
  );
}

function VisQuestionGroup({ data }: { data: VisQuestion }) {
  const [expanded, setExpanded] = useState(false);
  const mentionedEngines = data.engines.filter((e) => e.mentioned).length;

  return (
    <article className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
      <button
        type="button"
        className="flex w-full items-start justify-between gap-4 text-left"
        onClick={() => setExpanded(!expanded)}
      >
        <div>
          <div className="text-base font-medium text-[var(--shell-text)]">
            {data.question}
          </div>
          {data.category && (
            <span className="mt-1 inline-block rounded-md bg-[var(--shell-panel-soft)] px-2 py-0.5 text-[11px] text-[var(--shell-text-soft)]">
              {CATEGORY_LABELS[data.category] || data.category}
            </span>
          )}
        </div>
        <div className="flex shrink-0 items-center gap-2 text-right">
          <span className="text-xs text-[var(--shell-text-soft)]">
            {mentionedEngines}/{data.engines.length} engines
          </span>
          <svg
            className={`h-4 w-4 text-[var(--shell-text-muted)] transition-transform ${expanded ? "rotate-180" : ""}`}
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth={2}
          >
            <polyline points="6 9 12 15 18 9" />
          </svg>
        </div>
      </button>

      {expanded && (
        <div className="mt-4 grid gap-3">
          {data.engines.map((eng) => (
            <div
              key={eng.engine}
              className="shell-transition rounded-[14px] border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4"
            >
              <div className="flex items-center justify-between gap-2">
                <span className="text-xs font-medium uppercase tracking-[0.08em] text-[var(--shell-text)]">
                  {ENGINE_LABELS[eng.engine] || eng.engine}
                </span>
                <VisStatusBadge engine={eng} />
              </div>
              {eng.mentionContext && (
                <div className="mt-3 rounded-xl border border-[var(--shell-positive)]/20 bg-[var(--shell-positive)]/5 px-3 py-2 text-xs text-[var(--shell-positive)]">
                  {eng.mentionContext}
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </article>
  );
}

function VisStatusBadge({ engine }: { engine: VisQuestion["engines"][number] }) {
  if (engine.mentioned) {
    return (
      <span className="rounded-full bg-[var(--shell-positive)]/15 px-2 py-1 text-[11px] text-[var(--shell-positive)]">
        언급됨
      </span>
    );
  }
  if (engine.inResults) {
    return (
      <span className="rounded-full bg-[var(--shell-warning)]/15 px-2 py-1 text-[11px] text-[var(--shell-warning)]">
        출처만 노출
      </span>
    );
  }
  return (
    <span className="rounded-full bg-[var(--shell-danger)]/15 px-2 py-1 text-[11px] text-[var(--shell-danger)]">
      미언급
    </span>
  );
}

function QuestionGroup({
  question,
  items,
}: {
  question: string;
  items: Probe[];
}) {
  const [expanded, setExpanded] = useState(false);
  const mentionedEngines = items.filter((i) => i.ourSiteMentioned).length;
  const category = items[0]?.category || "";

  return (
    <article className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
      <button
        type="button"
        className="flex w-full items-start justify-between gap-4 text-left"
        onClick={() => setExpanded(!expanded)}
      >
        <div>
          <div className="text-base font-medium text-[var(--shell-text)]">
            {question}
          </div>
          {category && (
            <span className="mt-1 inline-block rounded-md bg-[var(--shell-panel-soft)] px-2 py-0.5 text-[11px] text-[var(--shell-text-soft)]">
              {CATEGORY_LABELS[category] || category}
            </span>
          )}
        </div>
        <div className="flex shrink-0 items-center gap-2 text-right">
          <span className="text-xs text-[var(--shell-text-soft)]">
            {mentionedEngines}/{items.length} engines
          </span>
          <svg
            className={`h-4 w-4 text-[var(--shell-text-muted)] transition-transform ${expanded ? "rotate-180" : ""}`}
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth={2}
          >
            <polyline points="6 9 12 15 18 9" />
          </svg>
        </div>
      </button>

      {expanded && (
        <div className="mt-4 grid gap-3">
          {items.map((probe) => (
            <div
              key={probe.id}
              className="shell-transition rounded-[14px] border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4"
            >
              <div className="flex items-center justify-between gap-2">
                <span className="text-xs font-medium uppercase tracking-[0.08em] text-[var(--shell-text)]">
                  {ENGINE_LABELS[probe.engine] || probe.engine}
                </span>
                <StatusBadge probe={probe} />
              </div>
              <p className="mt-3 line-clamp-3 text-sm leading-6 text-[var(--shell-text-muted)]">
                {probe.answer || "아직 수집된 답변이 없습니다."}
              </p>
              {probe.ourMentionContext && (
                <div className="mt-3 rounded-xl border border-[var(--shell-positive)]/20 bg-[var(--shell-positive)]/5 px-3 py-2 text-xs text-[var(--shell-positive)]">
                  {probe.ourMentionContext}
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </article>
  );
}

function StatusBadge({ probe }: { probe: Probe }) {
  if (probe.status === "failed") {
    return (
      <span className="rounded-full bg-[var(--shell-danger)]/15 px-2 py-1 text-[11px] text-[var(--shell-danger)]">
        실패
      </span>
    );
  }
  if (probe.ourSiteMentioned) {
    return (
      <span className="rounded-full bg-[var(--shell-positive)]/15 px-2 py-1 text-[11px] text-[var(--shell-positive)]">
        언급됨
      </span>
    );
  }
  if (probe.ourSiteInResults) {
    return (
      <span className="rounded-full bg-[var(--shell-warning)]/15 px-2 py-1 text-[11px] text-[var(--shell-warning)]">
        출처만 노출
      </span>
    );
  }
  return (
    <span className="rounded-full bg-[var(--shell-danger)]/15 px-2 py-1 text-[11px] text-[var(--shell-danger)]">
      미언급
    </span>
  );
}

function MetricCard({
  label,
  value,
  tone = "neutral",
}: {
  label: string;
  value: string;
  tone?: "neutral" | "accent" | "positive" | "secondary";
}) {
  const colorClass =
    tone === "accent"
      ? "text-[var(--shell-accent)]"
      : tone === "positive"
        ? "text-[var(--shell-positive)]"
        : tone === "secondary"
          ? "text-[var(--shell-secondary)]"
          : "text-[var(--shell-text)]";
  return (
    <div className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
      <div className="text-[11px] uppercase tracking-[0.18em] text-[var(--shell-text-soft)]">
        {label}
      </div>
      <div className={`mt-2 text-3xl font-semibold ${colorClass}`}>{value}</div>
    </div>
  );
}

function MiniStat({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-[12px] border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3">
      <div className="text-[11px] text-[var(--shell-text-soft)]">{label}</div>
      <div className="mt-1 text-xl font-semibold text-[var(--shell-text)]">
        {value}
      </div>
    </div>
  );
}

function CommandProgressPanel({
  progress,
  message,
  logLines,
}: {
  progress: number;
  message: string;
  logLines: LogLine[];
}) {
  const steps = [
    { label: "준비", threshold: 5 },
    { label: "질문 생성", threshold: 15 },
    { label: "AI 엔진 프로브", threshold: 85 },
    { label: "결과 분석", threshold: 93 },
    { label: "저장", threshold: 100 },
  ];

  const currentStepIdx = steps.findIndex((s) => progress < s.threshold);
  const activeIdx = currentStepIdx === -1 ? steps.length - 1 : currentStepIdx;

  return (
    <div className="shell-transition rounded-[16px] border border-[var(--shell-accent)]/40 bg-[var(--shell-accent-soft)] px-5 py-4">
      {/* Header */}
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-3 text-sm font-medium text-[var(--shell-accent)]">
          <span className="inline-flex h-2.5 w-2.5 animate-pulse rounded-full bg-[var(--shell-accent)]" />
          {message || "GEO 프로브 실행 중..."}
        </div>
        <span className="text-xs tabular-nums text-[var(--shell-text-soft)]">
          {progress}%
        </span>
      </div>

      {/* Progress bar */}
      <div className="mt-3 h-2 overflow-hidden rounded-full bg-[var(--shell-border)]">
        <div
          className="h-full rounded-full bg-[var(--shell-accent)] transition-all duration-500 ease-out"
          style={{ width: `${Math.max(progress, 2)}%` }}
        />
      </div>

      {/* Step indicators */}
      <div className="mt-3 flex gap-1">
        {steps.map((step, i) => (
          <div key={step.label} className="flex flex-1 flex-col items-center gap-1">
            <div
              className={`h-1.5 w-full rounded-full transition-colors duration-300 ${
                i < activeIdx
                  ? "bg-[var(--shell-accent)]"
                  : i === activeIdx
                    ? "bg-[var(--shell-accent)]/50 animate-pulse"
                    : "bg-[var(--shell-border)]"
              }`}
            />
            <span
              className={`text-[10px] transition-colors ${
                i <= activeIdx
                  ? "text-[var(--shell-accent)]"
                  : "text-[var(--shell-text-muted)]"
              }`}
            >
              {step.label}
            </span>
          </div>
        ))}
      </div>

      {/* Log lines */}
      {logLines.length > 0 && (
        <CommandLogLines logLines={logLines} maxVisible={4} />
      )}
    </div>
  );
}

function CommandLogLines({
  logLines,
  maxVisible = 4,
}: {
  logLines: LogLine[];
  maxVisible?: number;
}) {
  const [expanded, setExpanded] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  const visibleLines = expanded ? logLines : logLines.slice(-maxVisible);
  const hasMore = logLines.length > maxVisible;

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [logLines.length]);

  const typeColor: Record<string, string> = {
    info: "text-[var(--shell-text-muted)]",
    step: "text-[var(--shell-accent)]",
    warning: "text-[var(--shell-warning)]",
    error: "text-[var(--shell-danger)]",
  };

  const typePrefix: Record<string, string> = {
    info: "",
    step: "",
    warning: "WARN ",
    error: "ERR ",
  };

  return (
    <div className="mt-3 rounded-[10px] border border-[var(--shell-border)] bg-[var(--shell-main)]/60 p-3">
      <div className="flex items-center justify-between">
        <span className="text-[10px] uppercase tracking-[0.15em] text-[var(--shell-text-soft)]">
          로그
        </span>
        {hasMore && (
          <button
            type="button"
            onClick={() => setExpanded(!expanded)}
            className="text-[10px] text-[var(--shell-accent)] hover:underline"
          >
            {expanded ? "접기" : `전체 (${logLines.length})`}
          </button>
        )}
      </div>
      <div
        ref={scrollRef}
        className="mt-1.5 max-h-[160px] space-y-0.5 overflow-y-auto"
      >
        {visibleLines.map((line, i) => (
          <div
            key={`${line.ts}-${i}`}
            className={`flex items-start gap-2 text-[11px] leading-4 font-mono ${typeColor[line.type] || typeColor.info}`}
          >
            <span className="shrink-0 tabular-nums text-[var(--shell-text-muted)]/60">
              {new Date(line.ts).toLocaleTimeString("ko-KR", {
                hour: "2-digit",
                minute: "2-digit",
                second: "2-digit",
              })}
            </span>
            <span>
              {typePrefix[line.type]}
              {line.message}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}
