import { useState } from "react";
import { ChevronDown, X } from "lucide-react";
import type { NaverKeywordAnalysis } from "../../../db/collections";

interface DiagnosisNaverTabProps {
  data: NaverKeywordAnalysis | null;
  stepDone: boolean;
}

export function DiagnosisNaverTab({ data, stepDone }: DiagnosisNaverTabProps) {
  const [selectedKeyword, setSelectedKeyword] = useState<string | null>(null);

  if (!data && !stepDone) {
    return (
      <div className="py-8 text-center text-sm text-[var(--shell-text-muted)]">
        <div className="mb-2 animate-pulse">Collecting Naver keyword data...</div>
        <div className="text-xs">Will start automatically after SEO analysis.</div>
      </div>
    );
  }
  if (!data) {
    return (
      <div className="py-8 text-center text-sm text-[var(--shell-text-muted)]">
        No Naver keyword analysis data available.
      </div>
    );
  }

  const { summary, topKeywords, presenceSummary, presence, competitors } = data;
  const naverScore = data.naverScore ?? 0;
  const scoreColor = naverScore >= 80 ? "text-[var(--shell-positive)]" : naverScore >= 50 ? "text-[var(--shell-secondary)]" : "text-[var(--shell-danger)]";
  const barColor = naverScore >= 80 ? "bg-[var(--shell-positive)]" : naverScore >= 50 ? "bg-[var(--shell-secondary)]" : "bg-[var(--shell-danger)]";

  const gradeColor = (g: string) =>
    g === "A" ? "text-[var(--shell-positive)]" : g === "B" ? "text-emerald-400" : g === "C" ? "text-[var(--shell-secondary)]" : g === "D" ? "text-orange-400" : "text-[var(--shell-danger)]";
  const compChipColor = (c: string) =>
    c === "높음" || c === "High" ? "bg-[color-mix(in_srgb,var(--shell-danger)_15%,transparent)] text-[var(--shell-danger)]"
    : c === "중간" || c === "Medium" ? "bg-[color-mix(in_srgb,var(--shell-secondary)_15%,transparent)] text-[var(--shell-secondary)]"
    : "bg-[color-mix(in_srgb,var(--shell-positive)_15%,transparent)] text-[var(--shell-positive)]";

  const presenceMap = new Map((presence ?? []).map((p) => [p.keyword, p]));

  return (
    <div className="space-y-4 text-sm">
      {/* Summary card */}
      {presenceSummary ? (
        <div className="flex items-center gap-4 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4">
          <div className="min-w-[60px] text-center">
            <div className={`text-3xl font-bold ${scoreColor}`}>{naverScore || "-"}</div>
            <div className="text-[10px] text-[var(--shell-text-muted)]">/ 100</div>
          </div>
          <div className="flex-1 space-y-2">
            <div className="h-1.5 overflow-hidden rounded-full bg-[var(--shell-panel-strong)]">
              <div className={`h-full rounded-full ${barColor}`} style={{ width: `${naverScore}%` }} />
            </div>
            <div className="grid grid-cols-2 gap-x-3 gap-y-1 text-xs text-[var(--shell-text-muted)]">
              <div>{presenceSummary.totalKeywords} keywords, <span className="font-medium text-[var(--shell-text)]">{presenceSummary.exposedKeywords} exposed</span> ({presenceSummary.exposureRate}%)</div>
              <div>Mentions: <span className="font-medium text-[var(--shell-text)]">{presenceSummary.totalMentions ?? 0}</span></div>
              {presenceSummary.channelCoverage && (
                <div className="flex items-center gap-2">
                  <span className={presenceSummary.channelCoverage.blog > 0 ? "text-[var(--shell-positive)]" : ""}>Blog {presenceSummary.channelCoverage.blog}</span>
                  <span className={presenceSummary.channelCoverage.web > 0 ? "text-[var(--shell-positive)]" : ""}>Web {presenceSummary.channelCoverage.web}</span>
                  <span className={presenceSummary.channelCoverage.cafe > 0 ? "text-[var(--shell-positive)]" : ""}>Cafe {presenceSummary.channelCoverage.cafe}</span>
                </div>
              )}
            </div>
          </div>
        </div>
      ) : summary && (
        <div className="grid grid-cols-2 gap-3">
          <div className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4 text-center">
            <div className="text-xs text-[var(--shell-text-muted)]">Total Monthly Search</div>
            <div className="mt-1 text-xl font-bold text-[var(--shell-text)]">{(summary.totalMonthlySearch ?? 0).toLocaleString()}</div>
          </div>
          <div className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4 text-center">
            <div className="text-xs text-[var(--shell-text-muted)]">Avg Competition</div>
            <div className="mt-1 text-xl font-bold text-[var(--shell-text)]">{summary.avgCompetition || "-"}</div>
          </div>
        </div>
      )}

      {/* Rising trends */}
      {summary?.risingTrends && summary.risingTrends.length > 0 && (
        <div>
          <div className="mb-2 text-sm font-medium text-[var(--shell-text)]">Rising Trends</div>
          <div className="flex flex-wrap gap-1.5">
            {summary.risingTrends.map((kw) => (
              <span key={kw} className="rounded-full border border-emerald-500/20 bg-emerald-500/10 px-2.5 py-0.5 text-xs text-emerald-400">
                {kw}
              </span>
            ))}
          </div>
        </div>
      )}

      {/* Keyword table */}
      {topKeywords?.length > 0 && (
        <div>
          <div className="mb-2 text-sm font-medium text-[var(--shell-text)]">Keyword Analysis ({topKeywords.length})</div>
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead>
                <tr className="border-b border-[var(--shell-border)] text-[var(--shell-text-muted)]">
                  <th className="py-2 pr-2 text-left">Keyword</th>
                  <th className="px-1 py-2 text-right">Volume</th>
                  <th className="px-1 py-2 text-center">Blog</th>
                  <th className="px-1 py-2 text-center">Web</th>
                  <th className="px-1 py-2 text-center">Competition</th>
                  <th className="py-2 pl-1 text-center">Difficulty</th>
                </tr>
              </thead>
              <tbody>
                {topKeywords.map((k) => {
                  const vol = k.monthlySearchVolume;
                  const p = presenceMap.get(k.keyword);
                  const blogCh = p?.channels?.blog;
                  const webCh = p?.channels?.web;
                  return (
                    <tr
                      key={k.keyword}
                      className="cursor-pointer border-b border-[var(--shell-border)]/30 hover:bg-[var(--shell-panel-soft)]"
                      onClick={() => setSelectedKeyword(k.keyword)}
                    >
                      <td className="max-w-[130px] truncate py-2 pr-2 text-[var(--shell-text)]">{k.keyword}</td>
                      <td className="px-1 py-2 text-right tabular-nums font-medium text-[var(--shell-text)]">{(vol?.total || 0).toLocaleString()}</td>
                      <td className={`px-1 py-2 text-center ${blogCh?.found ? "font-medium text-[var(--shell-positive)]" : "text-[var(--shell-text-muted)]"}`}>
                        {blogCh?.found ? `#${blogCh.position}` : "--"}
                      </td>
                      <td className={`px-1 py-2 text-center ${webCh?.found ? "font-medium text-[var(--shell-positive)]" : "text-[var(--shell-text-muted)]"}`}>
                        {webCh?.found ? `#${webCh.position}` : "--"}
                      </td>
                      <td className="px-1 py-2 text-center">
                        <span className={`rounded px-1.5 py-0.5 text-[10px] ${compChipColor(k.competition)}`}>{k.competition}</span>
                      </td>
                      <td className={`py-2 pl-1 text-center font-bold ${gradeColor(k.difficultyGrade)}`}>
                        {k.difficultyGrade}
                        {k.difficultyScore != null && <span className="ml-0.5 text-[10px] font-normal text-[var(--shell-text-muted)]">({k.difficultyScore})</span>}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Naver competitors */}
      {competitors && competitors.length > 0 && (
        <details className="group" open>
          <summary className="mb-2 flex cursor-pointer items-center gap-1 text-sm font-medium text-[var(--shell-text)]">
            Naver Competitors ({competitors.length})
            <ChevronDown className="h-3 w-3 text-[var(--shell-text-muted)] transition-transform group-open:rotate-180" />
          </summary>
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead>
                <tr className="border-b border-[var(--shell-border)] text-[var(--shell-text-muted)]">
                  <th className="py-2 pr-1 text-left">Name</th>
                  <th className="w-12 py-2 text-center">Type</th>
                  <th className="w-12 py-2 text-right">Appears</th>
                  <th className="w-14 py-2 text-right">Avg Rank</th>
                </tr>
              </thead>
              <tbody>
                {competitors.map((c, i) => (
                  <tr key={i} className="border-b border-[var(--shell-border)]/30 hover:bg-[var(--shell-panel-soft)]">
                    <td className="max-w-[160px] truncate py-2 pr-1 text-[var(--shell-text)]">{c.name}</td>
                    <td className="w-12 py-2 text-center">
                      <span className={`rounded px-1.5 py-0.5 text-[10px] ${c.type === "blog" ? "bg-sky-500/15 text-sky-400" : "bg-teal-500/15 text-teal-400"}`}>
                        {c.type}
                      </span>
                    </td>
                    <td className="w-12 py-2 text-right tabular-nums text-[var(--shell-text-muted)]">{c.appearances}</td>
                    <td className="w-14 py-2 text-right tabular-nums text-[var(--shell-text-muted)]">#{c.avgPosition}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </details>
      )}

      {/* Keyword detail panel */}
      {selectedKeyword && (() => {
        const kw = topKeywords?.find((k) => k.keyword === selectedKeyword);
        const pInfo = presence?.find((p) => p.keyword === selectedKeyword);
        const maxRatio = Math.max(...(kw?.trend || []).map((t) => t.ratio), 1);

        return (
          <>
            <div className="fixed inset-0 z-40 bg-black/40" onClick={() => setSelectedKeyword(null)} />
            <div className="fixed right-0 top-0 z-50 h-full w-[380px] max-w-[90vw] overflow-y-auto border-l border-[var(--shell-border)] bg-[var(--shell-panel)]" style={{ animation: "slideInRight 0.2s ease-out" }}>
              <div className="sticky top-0 flex items-center justify-between border-b border-[var(--shell-border)] bg-[var(--shell-panel)] px-4 py-3">
                <div className="truncate text-sm font-medium text-[var(--shell-text)]">{selectedKeyword}</div>
                <button onClick={() => setSelectedKeyword(null)} className="rounded p-1 text-[var(--shell-text-muted)] hover:bg-[var(--shell-panel-soft)] hover:text-[var(--shell-text)]">
                  <X className="h-4 w-4" />
                </button>
              </div>
              <div className="space-y-5 p-4">
                {kw && (
                  <div className="grid grid-cols-4 gap-2">
                    <MiniStat label="Volume" value={(kw.monthlySearchVolume?.total || 0).toLocaleString()} sub={`PC ${(kw.monthlySearchVolume?.pc || 0).toLocaleString()} / M ${(kw.monthlySearchVolume?.mobile || 0).toLocaleString()}`} />
                    <MiniStat label="Comp" value={kw.competition || "-"} />
                    <MiniStat label="Difficulty" value={kw.difficultyGrade || "-"} />
                    <MiniStat label="Saturation" value={kw.blogSaturation?.saturationRate != null ? `${kw.blogSaturation.saturationRate}%` : "-"} />
                  </div>
                )}

                {pInfo && (
                  <div className="flex items-center gap-2 text-xs text-[var(--shell-text-muted)]">
                    <span>Exposure:</span>
                    {(["blog", "web", "cafe"] as const).map((ch) => {
                      const info = pInfo.channels?.[ch];
                      return (
                        <span key={ch} className={info?.found ? "text-[var(--shell-positive)]" : ""}>
                          {ch} {info?.found ? `#${info.position}` : "x"}
                        </span>
                      );
                    })}
                  </div>
                )}

                {/* 12-month trend */}
                {kw?.trend && kw.trend.length > 0 && (
                  <div>
                    <div className="mb-2 text-sm font-medium text-[var(--shell-text)]">12-Month Trend</div>
                    <div className="flex h-[80px] items-end gap-[3px] rounded-lg bg-[var(--shell-panel-soft)] p-2">
                      {kw.trend.map((t, i) => {
                        const h = maxRatio > 0 ? (t.ratio / maxRatio) * 100 : 0;
                        return (
                          <div key={i} className="flex flex-1 flex-col items-center justify-end" style={{ height: "100%" }}>
                            <div
                              className="w-full rounded-t bg-[var(--shell-accent)] hover:bg-[var(--shell-accent-strong)] transition-colors"
                              style={{ height: `${Math.max(h, 2)}%`, minHeight: "2px" }}
                              title={`${t.period}: ${t.ratio}`}
                            />
                            <div className="mt-1 text-[8px] text-[var(--shell-text-muted)]">{t.period?.slice(5, 7)}</div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                )}

                {/* Top blog stats */}
                {kw?.topBlogStats && (
                  <div>
                    <div className="mb-2 text-sm font-medium text-[var(--shell-text)]">Competing Blogs</div>
                    <div className="grid grid-cols-3 gap-2 text-center">
                      <MiniStat label="Avg Chars" value={`${(kw.topBlogStats.avgCharCount ?? 0).toLocaleString()}`} />
                      <MiniStat label="Avg Images" value={`${kw.topBlogStats.avgImageCount ?? 0}`} />
                      <MiniStat label="Avg Age" value={`${kw.topBlogStats.avgDaysSincePublish ?? "-"}d`} />
                    </div>
                    {kw.topBlogStats.blogs?.length > 0 && (
                      <div className="mt-2 space-y-1.5">
                        {kw.topBlogStats.blogs.map((blog, i) => (
                          <a key={i} href={blog.link} target="_blank" rel="noopener noreferrer" className="block rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 transition-colors hover:bg-[var(--shell-panel-strong)]">
                            <div className="truncate text-xs text-[var(--shell-text)]">{blog.title}</div>
                            <div className="mt-0.5 flex items-center gap-3 text-[10px] text-[var(--shell-text-muted)]">
                              <span>{blog.charCount?.toLocaleString()} chars</span>
                              <span>{blog.imageCount} imgs</span>
                            </div>
                          </a>
                        ))}
                      </div>
                    )}
                  </div>
                )}

                {/* Click metrics */}
                {kw?.clickMetrics && (
                  <div>
                    <div className="mb-2 text-sm font-medium text-[var(--shell-text)]">Click Metrics</div>
                    <div className="space-y-2 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3 text-xs">
                      <div className="flex justify-between"><span className="text-[var(--shell-text-muted)]">PC Clicks</span><span className="text-[var(--shell-text)]">{kw.clickMetrics.pcClicks?.toLocaleString()} (CTR {kw.clickMetrics.pcCtr}%)</span></div>
                      <div className="flex justify-between"><span className="text-[var(--shell-text-muted)]">Mobile Clicks</span><span className="text-[var(--shell-text)]">{kw.clickMetrics.mobileClicks?.toLocaleString()} (CTR {kw.clickMetrics.mobileCtr}%)</span></div>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </>
        );
      })()}
    </div>
  );
}

function MiniStat({ label, value, sub }: { label: string; value: string; sub?: string }) {
  return (
    <div className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-2.5 text-center">
      <div className="text-[10px] text-[var(--shell-text-muted)]">{label}</div>
      <div className="mt-0.5 text-sm font-bold text-[var(--shell-text)]">{value}</div>
      {sub && <div className="mt-0.5 text-[9px] text-[var(--shell-text-muted)]">{sub}</div>}
    </div>
  );
}
