export function ActionIcon({ title }: { title: string }) {
  const l = title.toLowerCase();
  if (l.includes("seo")) return <span className="text-sm">S</span>;
  if (l.includes("competitor")) return <span className="text-sm">C</span>;
  if (l.includes("brand")) return <span className="text-sm">B</span>;
  if (l.includes("strategy") || l.includes("marketing"))
    return <span className="text-sm">M</span>;
  if (l.includes("product")) return <span className="text-sm">P</span>;
  return <span className="text-sm">A</span>;
}

export function ScoreGauge({
  label,
  value,
}: {
  label: string;
  value: number;
}) {
  const r = 20;
  const c = 2 * Math.PI * r;
  const offset = c - (value / 100) * c;
  const color =
    value >= 90 ? "#22c55e" : value >= 50 ? "#eab308" : "#ef4444";
  const bgColor =
    value >= 90 ? "#22c55e20" : value >= 50 ? "#eab30820" : "#ef444420";

  return (
    <div className="flex flex-col items-center gap-1">
      <svg width="52" height="52" viewBox="0 0 52 52">
        <circle
          cx="26"
          cy="26"
          r={r}
          fill="none"
          stroke={bgColor}
          strokeWidth="4"
        />
        <circle
          cx="26"
          cy="26"
          r={r}
          fill="none"
          stroke={color}
          strokeWidth="4"
          strokeLinecap="round"
          strokeDasharray={c}
          strokeDashoffset={offset}
          transform="rotate(-90 26 26)"
          style={{ transition: "stroke-dashoffset 1s ease" }}
        />
        <text
          x="26"
          y="26"
          textAnchor="middle"
          dominantBaseline="central"
          className="text-[13px] font-bold"
          fill={color}
        >
          {value}
        </text>
      </svg>
      <span className="text-[8px] text-[var(--shell-text-muted)]">
        {label}
      </span>
    </div>
  );
}

export function StatusPill({ status }: { status: string }) {
  const m: Record<string, { c: string; l: string }> = {
    running: {
      c: "bg-[color-mix(in_srgb,var(--shell-accent)_20%,transparent)] text-[var(--shell-accent)]",
      l: "in progress",
    },
    queued: {
      c: "bg-[color-mix(in_srgb,var(--shell-secondary)_20%,transparent)] text-[var(--shell-secondary)]",
      l: "queued",
    },
    complete: {
      c: "bg-[color-mix(in_srgb,var(--shell-positive)_20%,transparent)] text-[var(--shell-positive)]",
      l: "done",
    },
    done: {
      c: "bg-[color-mix(in_srgb,var(--shell-positive)_20%,transparent)] text-[var(--shell-positive)]",
      l: "done",
    },
    succeeded: {
      c: "bg-[color-mix(in_srgb,var(--shell-positive)_20%,transparent)] text-[var(--shell-positive)]",
      l: "done",
    },
    failed: {
      c: "bg-[color-mix(in_srgb,var(--shell-danger)_20%,transparent)] text-[var(--shell-danger)]",
      l: "failed",
    },
    todo: {
      c: "bg-[var(--shell-panel-strong)] text-[var(--shell-text-muted)]",
      l: "todo",
    },
  };
  const s = m[status] || m.todo;
  return (
    <span
      className={`inline-block rounded px-1.5 py-0.5 text-[13px] font-medium ${s.c}`}
    >
      {s.l}
    </span>
  );
}
