import { useState } from "react";

interface DiagnosisSeoTabProps {
  seoAudit: Record<string, any> | null;
}

export function DiagnosisSeoTab({ seoAudit }: DiagnosisSeoTabProps) {
  const [expandedRule, setExpandedRule] = useState<string | null>(null);

  if (!seoAudit) {
    return (
      <div className="py-6 text-center text-sm text-[var(--shell-text-soft)]">
        SEO audit data not yet available. Run analysis to see results.
      </div>
    );
  }

  const score = (seoAudit as any).score ?? 0;
  const checks = ((seoAudit as any).checks ?? []) as Array<{
    rule: string;
    label?: string;
    status: "pass" | "warn" | "fail";
    message?: string;
    affectedPages?: string[];
  }>;

  const passCount = checks.filter((c) => c.status === "pass").length;
  const warnCount = checks.filter((c) => c.status === "warn").length;
  const failCount = checks.filter((c) => c.status === "fail").length;

  return (
    <div className="space-y-5">
      {/* Score hero */}
      <div className="flex items-center gap-6">
        <div
          className={`grid h-24 w-24 place-items-center rounded-full border-[5px] ${
            score >= 80
              ? "border-[var(--shell-positive)]"
              : score >= 50
                ? "border-[var(--shell-secondary)]"
                : "border-[var(--shell-danger)]"
          } bg-[var(--shell-panel-soft)]`}
        >
          <div className="text-3xl font-semibold text-[var(--shell-text)]">
            {score}
          </div>
        </div>
        <div>
          <div className="text-2xl font-semibold text-[var(--shell-text)]">
            SEO Score
          </div>
          <div className="mt-1 flex gap-3 text-xs">
            <span className="text-[var(--shell-positive)]">
              {passCount} passed
            </span>
            <span className="text-[var(--shell-secondary)]">
              {warnCount} warnings
            </span>
            <span className="text-[var(--shell-danger)]">
              {failCount} issues
            </span>
          </div>
        </div>
      </div>

      {/* Checks list */}
      <div className="space-y-2">
        {checks.map((check) => {
          const expanded = expandedRule === check.rule;
          return (
            <div
              key={check.rule}
              className="shell-transition rounded-[14px] border border-[var(--shell-border)] bg-[var(--shell-panel-soft)]"
            >
              <button
                onClick={() =>
                  setExpandedRule(expanded ? null : check.rule)
                }
                className="flex w-full items-center gap-3 px-4 py-3 text-left"
              >
                <span
                  className={`inline-block h-2 w-2 shrink-0 rounded-full ${
                    check.status === "pass"
                      ? "bg-[var(--shell-positive)]"
                      : check.status === "warn"
                        ? "bg-[var(--shell-secondary)]"
                        : "bg-[var(--shell-danger)]"
                  }`}
                />
                <span className="flex-1 text-sm text-[var(--shell-text)]">
                  {check.label || check.rule}
                </span>
                <span
                  className={`text-[11px] uppercase tracking-[0.12em] ${
                    check.status === "pass"
                      ? "text-[var(--shell-positive)]"
                      : check.status === "warn"
                        ? "text-[var(--shell-secondary)]"
                        : "text-[var(--shell-danger)]"
                  }`}
                >
                  {check.status}
                </span>
              </button>
              {expanded && check.message && (
                <div className="border-t border-[var(--shell-border)] px-4 py-3 text-xs leading-5 text-[var(--shell-text-soft)]">
                  {check.message}
                  {check.affectedPages &&
                    check.affectedPages.length > 0 && (
                      <div className="mt-2">
                        <div className="mb-1 text-[var(--shell-text-muted)]">
                          Affected pages:
                        </div>
                        {check.affectedPages.slice(0, 5).map((p) => (
                          <div key={p} className="text-[var(--shell-text-soft)]">
                            {p}
                          </div>
                        ))}
                      </div>
                    )}
                </div>
              )}
            </div>
          );
        })}
        {checks.length === 0 && (
          <div className="py-4 text-sm text-[var(--shell-text-soft)]">
            No SEO checks available.
          </div>
        )}
      </div>
    </div>
  );
}
