interface DiagnosisInsightsTabProps {
  seoAudit: Record<string, any> | null;
}

interface CwvMetric {
  label: string;
  key: string;
  unit: string;
  good: number;
  poor: number;
}

const CWV_METRICS: CwvMetric[] = [
  { label: "LCP", key: "lcp", unit: "s", good: 2.5, poor: 4.0 },
  { label: "INP", key: "inp", unit: "ms", good: 200, poor: 500 },
  { label: "CLS", key: "cls", unit: "", good: 0.1, poor: 0.25 },
];

export function DiagnosisInsightsTab({
  seoAudit,
}: DiagnosisInsightsTabProps) {
  const cwv = (seoAudit as any)?.cwv as
    | Record<string, number | string>
    | undefined;
  const pageCount = (seoAudit as any)?.pageCount ?? 0;
  const avgLoadTime = (seoAudit as any)?.avgLoadTime;

  return (
    <div className="space-y-5">
      {/* Summary stats */}
      <div className="grid grid-cols-3 gap-3">
        <StatCard label="Pages Analyzed" value={String(pageCount)} />
        <StatCard
          label="Avg Load Time"
          value={avgLoadTime ? `${Number(avgLoadTime).toFixed(1)}s` : "N/A"}
        />
        <StatCard
          label="Health"
          value={
            cwv
              ? Object.keys(cwv).length > 0
                ? "Data Available"
                : "N/A"
              : "Pending"
          }
        />
      </div>

      {/* CWV Metrics */}
      {cwv && Object.keys(cwv).length > 0 ? (
        <div>
          <div className="mb-3 text-[11px] uppercase tracking-[0.14em] text-[var(--shell-text-muted)]">
            Core Web Vitals
          </div>
          <div className="grid gap-3 sm:grid-cols-3">
            {CWV_METRICS.map((metric) => {
              const value = cwv[metric.key];
              if (value == null) return null;
              const numVal = Number(value);
              const status =
                numVal <= metric.good
                  ? "good"
                  : numVal <= metric.poor
                    ? "needs-improvement"
                    : "poor";
              return (
                <div
                  key={metric.key}
                  className="shell-transition rounded-[16px] border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4"
                >
                  <div className="text-[10px] uppercase tracking-[0.16em] text-[var(--shell-text-soft)]">
                    {metric.label}
                  </div>
                  <div
                    className={`mt-2 text-3xl font-semibold ${
                      status === "good"
                        ? "text-[var(--shell-positive)]"
                        : status === "needs-improvement"
                          ? "text-[var(--shell-secondary)]"
                          : "text-[var(--shell-danger)]"
                    }`}
                  >
                    {typeof value === "number" ? value.toFixed(2) : value}
                    {metric.unit}
                  </div>
                  <div className="mt-2 flex gap-1">
                    {["good", "needs-improvement", "poor"].map((s) => (
                      <div
                        key={s}
                        className={`h-1 flex-1 rounded-full ${
                          s === status
                            ? s === "good"
                              ? "bg-[var(--shell-positive)]"
                              : s === "needs-improvement"
                                ? "bg-[var(--shell-secondary)]"
                                : "bg-[var(--shell-danger)]"
                            : "bg-[var(--shell-panel-strong)]"
                        }`}
                      />
                    ))}
                  </div>
                  <div className="mt-1 text-[10px] capitalize text-[var(--shell-text-soft)]">
                    {status.replace("-", " ")}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ) : (
        <div className="rounded-[16px] border border-dashed border-[var(--shell-border)] px-4 py-8 text-center text-sm text-[var(--shell-text-soft)]">
          Core Web Vitals data not available. This data is collected during
          site analysis.
        </div>
      )}
    </div>
  );
}

function StatCard({ label, value }: { label: string; value: string }) {
  return (
    <div className="shell-transition rounded-[16px] border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4">
      <div className="text-[10px] uppercase tracking-[0.16em] text-[var(--shell-text-soft)]">
        {label}
      </div>
      <div className="mt-2 text-2xl font-semibold text-[var(--shell-text)]">
        {value}
      </div>
    </div>
  );
}
