import type { BoardDocument } from "../../../db/collections";

interface DiagnosisExternalTabProps {
  docs: BoardDocument[];
}

export function DiagnosisExternalTab({ docs }: DiagnosisExternalTabProps) {
  const externalDoc = docs.find((d) => d.key === "external-analysis");
  const data = externalDoc?.data as Record<string, any> | undefined;

  if (!data) {
    return (
      <div className="py-6 text-center text-sm text-[var(--shell-text-soft)]">
        External trust signal analysis not yet available.
      </div>
    );
  }

  const trustScore = (data.trustScore as number) ?? 0;
  const sources = (data.sources ?? []) as Array<{
    type: string;
    name?: string;
    url?: string;
    score?: number;
    summary?: string;
  }>;

  const strategies = (data.strategies ?? []) as Array<{
    title: string;
    description: string;
    impact?: string;
  }>;

  const groupedSources = new Map<string, typeof sources>();
  for (const s of sources) {
    const type = s.type || "other";
    const list = groupedSources.get(type) ?? [];
    list.push(s);
    groupedSources.set(type, list);
  }

  return (
    <div className="space-y-5">
      {/* Trust Score */}
      <div className="flex items-center gap-6">
        <div
          className={`grid h-24 w-24 place-items-center rounded-full border-[5px] ${
            trustScore >= 70
              ? "border-[var(--shell-positive)]"
              : trustScore >= 40
                ? "border-[var(--shell-secondary)]"
                : "border-[var(--shell-danger)]"
          } bg-[var(--shell-panel-soft)]`}
        >
          <div className="text-3xl font-semibold text-[var(--shell-text)]">
            {trustScore}
          </div>
        </div>
        <div>
          <div className="text-2xl font-semibold text-[var(--shell-text)]">
            Trust Score
          </div>
          <div className="mt-1 text-xs text-[var(--shell-text-muted)]">
            External citations and reference signals
          </div>
          <div className="mt-1 text-xs text-[var(--shell-text-soft)]">
            {sources.length} sources found
          </div>
        </div>
      </div>

      {/* Strategies */}
      {strategies.length > 0 && (
        <div>
          <div className="mb-3 text-[11px] uppercase tracking-[0.14em] text-[var(--shell-text-muted)]">
            Improvement Strategies
          </div>
          <div className="grid gap-3 sm:grid-cols-3">
            {strategies.slice(0, 3).map((s, i) => (
              <div
                key={i}
                className="shell-transition rounded-[14px] border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4"
              >
                <div className="text-sm font-medium text-[var(--shell-text)]">
                  {s.title}
                </div>
                <div className="mt-2 text-xs leading-5 text-[var(--shell-text-soft)]">
                  {s.description}
                </div>
                {s.impact && (
                  <div className="mt-2 text-[11px] text-[var(--shell-positive)]">
                    Impact: {s.impact}
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Sources by type */}
      {groupedSources.size > 0 && (
        <div>
          <div className="mb-3 text-[11px] uppercase tracking-[0.14em] text-[var(--shell-text-muted)]">
            External Sources
          </div>
          <div className="space-y-3">
            {Array.from(groupedSources.entries()).map(([type, items]) => (
              <div key={type}>
                <div className="mb-2 text-xs font-medium capitalize text-[var(--shell-text)]">
                  {type} ({items.length})
                </div>
                <div className="space-y-1.5">
                  {items.slice(0, 5).map((s, i) => (
                    <div
                      key={i}
                      className="shell-transition flex items-center justify-between rounded-[12px] border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2"
                    >
                      <div className="min-w-0">
                        <div className="truncate text-sm text-[var(--shell-text)]">
                          {s.name || s.url || "Source"}
                        </div>
                        {s.summary && (
                          <div className="truncate text-[11px] text-[var(--shell-text-soft)]">
                            {s.summary}
                          </div>
                        )}
                      </div>
                      {s.score != null && (
                        <span
                          className={`ml-2 shrink-0 text-xs font-medium ${
                            s.score >= 7
                              ? "text-[var(--shell-positive)]"
                              : s.score >= 4
                                ? "text-[var(--shell-secondary)]"
                                : "text-[var(--shell-danger)]"
                          }`}
                        >
                          {s.score}/10
                        </span>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}
