import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { ChevronDown, ChevronUp, Check, X, Star, Wrench, Zap } from "lucide-react";
import { listSeoAudits, getDocument } from "../db/boards";
import { useI18n } from "../i18n";

type TabKey = "aiGeo" | "health" | "checks" | "difference";

interface Violation {
  rule: string;
  file: string;
  severity: "error" | "warning";
  message: string;
  suggestion?: string;
}

interface SeoAuditData {
  score: number;
  geoScore: number;
  errors: number;
  warnings: number;
  totalViolations: number;
  violations: Violation[];
  categories: Record<string, { errors: number; warnings: number }>;
  siteChecks?: { hasLlmsTxt: boolean; hasRobotsTxt: boolean; hasSitemap: boolean; hasFeed: boolean };
}

const RULE_LABELS_KO: Record<string, string> = {
  "geo-missing-source-citations": "출처 인용 부족",
  "geo-missing-expert-quotes": "전문가 의견 없음",
  "geo-low-citation-density": "통계 데이터 부족",
  "geo-missing-author": "저자 정보 없음",
  "geo-author-not-person": "저자가 사람이 아님",
  "geo-passive-voice-excess": "수동태 과다",
  "geo-sentence-too-long": "문장 길이 초과",
  "geo-weak-lead-sentences": "약한 도입부",
  "content-too-short": "콘텐츠 부족",
  "geo-no-question-headings": "질문형 제목 없음",
  "geo-missing-faq-section": "FAQ 섹션 없음",
  "schema-org-missing": "구조화 데이터 없음",
  "geo-missing-table": "표 없음",
  "geo-missing-lists": "목록 없음",
  "geo-low-internal-links": "내부 링크 부족",
  "geo-missing-tldr": "TL;DR 없음",
  "geo-missing-summary-section": "요약 섹션 없음",
  "geo-llms-discovery": "AI 크롤러 발견성",
  "geo-answer-depth-coverage": "답변형 본문 깊이",
  "geo-question-answer-coverage": "질문 기반 정보 구조",
  "geo-evidence-citation-coverage": "근거와 외부 신뢰 신호",
  "geo-entity-schema-coverage": "엔티티 Schema 적용 범위",
  "geo-authority-signal-coverage": "전문성/권위 신호",
  "geo-freshness-coverage": "최신성 신호",
};

const TIER1_RULES = [
  "geo-llms-discovery", "geo-answer-depth-coverage", "geo-question-answer-coverage",
  "geo-evidence-citation-coverage", "geo-missing-source-citations", "geo-missing-expert-quotes", "geo-low-citation-density",
];
const TIER2_RULES = [
  "geo-entity-schema-coverage", "geo-authority-signal-coverage", "geo-missing-author",
  "geo-author-not-person", "geo-passive-voice-excess", "geo-sentence-too-long", "geo-weak-lead-sentences", "content-too-short",
];
const TIER3_RULES = [
  "geo-freshness-coverage", "geo-no-question-headings", "geo-missing-faq-section",
  "schema-org-missing", "geo-missing-table", "geo-missing-lists", "geo-low-internal-links", "geo-missing-tldr", "geo-missing-summary-section",
];

export function Analytics() {
  const { id, tab } = useParams<{ id: string; tab?: string }>();
  const { t } = useI18n();
  const [activeTab, setActiveTab] = useState<TabKey>((tab as TabKey) || "aiGeo");
  const [audit, setAudit] = useState<SeoAuditData | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    listSeoAudits(id, 1).then((audits) => {
      if (audits[0]) setAudit(audits[0] as unknown as SeoAuditData);
      setLoading(false);
    });
  }, [id]);

  const tabs: { key: TabKey; label: string }[] = [
    { key: "aiGeo", label: t("analytics.tab.aiGeo") },
    { key: "health", label: t("analytics.tab.health") },
    { key: "checks", label: t("analytics.tab.checks") },
    { key: "difference", label: "차이분석" },
  ];

  return (
    <div className="mx-auto max-w-[1400px] space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">Analytics</div>
          <h1 className="mt-2 text-3xl font-semibold text-[var(--shell-text)]">Analytics</h1>
        </div>
        {audit && (
          <div className="flex items-center gap-2">
            <span className="text-sm text-[var(--shell-text-muted)]">{t("analytics.overallScore")}:</span>
            <span className={`text-lg font-bold ${
              audit.score >= 80 ? "text-[var(--shell-positive)]"
                : audit.score >= 50 ? "text-[var(--shell-warning)]"
                  : "text-[var(--shell-danger)]"
            }`}>
              {audit.score}/100
            </span>
          </div>
        )}
      </div>

      {/* Tabs */}
      <div className="flex gap-1 border-b border-[var(--shell-border)]">
        {tabs.map((tab) => (
          <button
            key={tab.key}
            onClick={() => setActiveTab(tab.key)}
            className={`-mb-px border-b-2 px-4 py-2 text-sm transition-colors ${
              activeTab === tab.key
                ? "border-[var(--shell-secondary)] text-[var(--shell-text)]"
                : "border-transparent text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
            }`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {loading && (
        <div className="text-sm text-[var(--shell-text-muted)]">{t("analytics.loading")}</div>
      )}

      {activeTab === "aiGeo" && audit && <GeoTab audit={audit} />}
      {activeTab === "health" && audit && <HealthTab audit={audit} />}
      {activeTab === "checks" && audit && <ChecksTab audit={audit} />}
      {activeTab === "difference" && <DifferenceTab boardId={id!} />}
    </div>
  );
}

// ── GEO Tab ──

function GeoTab({ audit }: { audit: SeoAuditData }) {
  const { t } = useI18n();
  const geoScore = audit.geoScore;
  const violations = audit.violations || [];
  const firedRules = new Set(violations.map((v) => v.rule));

  const buildTierItems = (rules: string[]) =>
    rules.map((id) => ({
      id,
      present: !firedRules.has(id),
      violation: violations.find((v) => v.rule === id),
    }));

  const tier1Items = buildTierItems(TIER1_RULES);
  const tier2Items = buildTierItems(TIER2_RULES);
  const tier3Items = buildTierItems(TIER3_RULES);
  const hasTripleCombo = tier1Items.every((i) => i.present);

  const grade = geoScore >= 80 ? t("geo.score.excellent") : geoScore >= 50 ? t("geo.score.good") : t("geo.score.needsWork");
  const gradeColor = geoScore >= 80 ? "text-[var(--shell-positive)]" : geoScore >= 50 ? "text-[var(--shell-warning)]" : "text-[var(--shell-danger)]";
  const gradeBorder = geoScore >= 80 ? "border-[var(--shell-positive)]/30" : geoScore >= 50 ? "border-[var(--shell-warning)]/30" : "border-[var(--shell-danger)]/30";

  return (
    <div className="space-y-5">
      {/* Score Hero */}
      <div className={`rounded-[22px] border ${gradeBorder} bg-[var(--shell-panel)] p-6 text-center shadow-[var(--shell-shadow)]`}>
        <div className="text-xs text-[var(--shell-text-soft)]">{t("geo.title")}</div>
        <div className={`mt-1 text-5xl font-bold ${gradeColor}`}>
          {geoScore}<span className="text-lg text-[var(--shell-text-muted)]">/100</span>
        </div>
        <div className={`mt-1 text-sm font-medium ${gradeColor}`}>{grade}</div>
        <div className="mx-auto mt-2 max-w-md text-[10px] text-[var(--shell-text-soft)]">
          {t("geo.subtitle")}
        </div>
      </div>

      <TierCard
        title={t("geo.tier1.title")}
        subtitle={t("geo.tier1.subtitle")}
        maxPoints={45}
        items={tier1Items}
        icon={<Star className="h-4 w-4 text-[var(--shell-warning)]" />}
        accentVar="warning"
      />

      {hasTripleCombo && (
        <div className="rounded-[16px] border border-[var(--shell-warning)]/30 bg-[var(--shell-warning)]/5 p-3 text-center text-xs font-medium text-[var(--shell-warning)]">
          {t("geo.tripleCombo")}
        </div>
      )}

      <TierCard
        title={t("geo.tier2.title")}
        subtitle={t("geo.tier2.subtitle")}
        maxPoints={25}
        items={tier2Items}
        icon={<Wrench className="h-4 w-4 text-[var(--shell-accent)]" />}
        accentVar="accent"
      />

      <TierCard
        title={t("geo.tier3.title")}
        subtitle={t("geo.tier3.subtitle")}
        maxPoints={20}
        items={tier3Items}
        icon={<Zap className="h-4 w-4 text-[var(--shell-secondary)]" />}
        accentVar="secondary"
      />
    </div>
  );
}

function TierCard({ title, subtitle, maxPoints, items, icon, accentVar }: {
  title: string;
  subtitle: string;
  maxPoints: number;
  items: Array<{ id: string; present: boolean; violation?: Violation }>;
  icon: React.ReactNode;
  accentVar: string;
}) {
  const [expanded, setExpanded] = useState(false);
  const presentCount = items.filter((i) => i.present).length;

  return (
    <div className={`shell-transition rounded-[18px] border border-[var(--shell-${accentVar})]/20 bg-[var(--shell-panel)] shadow-[var(--shell-shadow)] overflow-hidden`}>
      <button
        onClick={() => setExpanded(!expanded)}
        className="flex w-full items-center justify-between p-4 transition-colors hover:bg-[var(--shell-panel-soft)]"
      >
        <div className="flex items-center gap-3">
          {icon}
          <div className="text-left">
            <div className="text-sm font-medium text-[var(--shell-text)]">{title}</div>
            <div className="text-[10px] text-[var(--shell-text-soft)]">{subtitle}</div>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <div className="text-right">
            <span className="text-xs text-[var(--shell-text-muted)]">{presentCount}/{items.length}</span>
            <span className="ml-1 text-[9px] text-[var(--shell-text-soft)]">({maxPoints}pt)</span>
          </div>
          {expanded
            ? <ChevronUp className="h-4 w-4 text-[var(--shell-text-muted)]" />
            : <ChevronDown className="h-4 w-4 text-[var(--shell-text-muted)]" />}
        </div>
      </button>

      {expanded && (
        <div className="space-y-2 border-t border-[var(--shell-border)] p-3">
          {items.map((item) => (
            <div
              key={item.id}
              className={`flex items-start gap-2.5 rounded-xl p-2.5 text-[11px] ${
                item.present ? "bg-[var(--shell-positive)]/5" : "bg-[var(--shell-danger)]/5"
              }`}
            >
              <span className="mt-0.5 shrink-0">
                {item.present
                  ? <Check className="h-3.5 w-3.5 text-[var(--shell-positive)]" />
                  : <X className="h-3.5 w-3.5 text-[var(--shell-danger)]" />}
              </span>
              <div className="min-w-0 flex-1">
                <div className="font-medium text-[var(--shell-text)]">
                  {RULE_LABELS_KO[item.id] || item.id}
                </div>
                {!item.present && item.violation?.suggestion && (
                  <div className="mt-0.5 text-[10px] text-[var(--shell-text-soft)]">
                    {item.violation.suggestion}
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ── Health Tab ──

function HealthTab({ audit }: { audit: SeoAuditData }) {
  const siteChecks = audit.siteChecks;
  return (
    <div className="space-y-5">
      <div className="grid gap-3 md:grid-cols-4">
        <ScoreCard label="SEO 점수" value={audit.score} />
        <ScoreCard label="GEO 점수" value={audit.geoScore} />
        <ScoreCard label="오류" value={audit.errors} tone="danger" />
        <ScoreCard label="경고" value={audit.warnings} tone="warning" />
      </div>

      {siteChecks && (
        <div className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
          <div className="text-sm font-medium text-[var(--shell-text)]">사이트 체크</div>
          <div className="mt-3 grid gap-3 md:grid-cols-4">
            {Object.entries(siteChecks).map(([key, val]) => (
              <div key={key} className="flex items-center gap-2 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2.5">
                <span className={`inline-flex h-2.5 w-2.5 rounded-full ${val ? "bg-[var(--shell-positive)]" : "bg-[var(--shell-danger)]"}`} />
                <span className="text-sm text-[var(--shell-text)]">{key.replace(/^has/, "")}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {audit.categories && Object.keys(audit.categories).length > 0 && (
        <div className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
          <div className="text-sm font-medium text-[var(--shell-text)]">카테고리별 현황</div>
          <div className="mt-3 space-y-2">
            {Object.entries(audit.categories).map(([cat, counts]) => {
              const total = counts.errors + counts.warnings;
              return (
                <div key={cat} className="flex items-center justify-between rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                  <span className="text-sm text-[var(--shell-text)]">{cat}</span>
                  <div className="flex items-center gap-3 text-xs">
                    <span className="text-[var(--shell-danger)]">{counts.errors} 오류</span>
                    <span className="text-[var(--shell-warning)]">{counts.warnings} 경고</span>
                    <span className="text-[var(--shell-text-soft)]">총 {total}</span>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

function ScoreCard({ label, value, tone }: { label: string; value: number; tone?: "danger" | "warning" }) {
  const colorClass = tone === "danger"
    ? "text-[var(--shell-danger)]"
    : tone === "warning"
      ? "text-[var(--shell-warning)]"
      : value >= 70 ? "text-[var(--shell-positive)]"
        : value >= 40 ? "text-[var(--shell-warning)]"
          : "text-[var(--shell-danger)]";
  return (
    <div className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
      <div className="text-[11px] uppercase tracking-[0.18em] text-[var(--shell-text-soft)]">{label}</div>
      <div className={`mt-2 text-3xl font-semibold ${colorClass}`}>{value}</div>
    </div>
  );
}

// ── Checks Tab ──

function ChecksTab({ audit }: { audit: SeoAuditData }) {
  const { t } = useI18n();
  const violations = audit.violations || [];

  if (violations.length === 0) {
    return (
      <div className="text-sm text-[var(--shell-text-muted)]">{t("analytics.noChecks")}</div>
    );
  }

  return (
    <div className="space-y-3">
      {violations.map((v, i) => (
        <div key={`${v.rule}-${i}`} className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-4 shadow-[var(--shell-shadow)]">
          <div className="flex items-center justify-between gap-3">
            <div className="flex items-center gap-2">
              <span className={`inline-block h-2.5 w-2.5 rounded-full ${
                v.severity === "error" ? "bg-[var(--shell-danger)]" : "bg-[var(--shell-warning)]"
              }`} />
              <span className="text-sm font-medium text-[var(--shell-text)]">
                {RULE_LABELS_KO[v.rule] || v.rule}
              </span>
            </div>
            <span className={`rounded-full px-2 py-0.5 text-[10px] ${
              v.severity === "error"
                ? "bg-[var(--shell-danger)]/15 text-[var(--shell-danger)]"
                : "bg-[var(--shell-warning)]/15 text-[var(--shell-warning)]"
            }`}>
              {v.severity === "error" ? t("rec.priority.high") : t("rec.priority.medium")}
            </span>
          </div>
          <p className="mt-2 text-xs text-[var(--shell-text-muted)]">{v.message}</p>
          {v.suggestion && (
            <div className="mt-2 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3 text-xs text-[var(--shell-text-muted)]">
              {v.suggestion}
            </div>
          )}
          {v.file && (
            <div className="mt-2 truncate text-[10px] text-[var(--shell-text-soft)]">{v.file}</div>
          )}
        </div>
      ))}
    </div>
  );
}

// ── Difference Tab ──

function DifferenceTab({ boardId }: { boardId: string }) {
  const [diffDoc, setDiffDoc] = useState<Record<string, unknown> | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getDocument(boardId, "difference-analysis").then((doc) => {
      if (doc?.data) setDiffDoc(doc.data);
      setLoading(false);
    });
  }, [boardId]);

  if (loading) {
    return <div className="text-sm text-[var(--shell-text-muted)]">로딩 중...</div>;
  }

  if (!diffDoc) {
    return (
      <div className="shell-transition rounded-[18px] border border-dashed border-[var(--shell-border)] bg-[var(--shell-panel)] p-6 text-sm text-[var(--shell-text-muted)]">
        아직 차이분석이 없습니다. 고객 인풋과 자동 감지 결과가 모두 있어야 비교할 수 있습니다.
      </div>
    );
  }

  const dimensions = (diffDoc.dimensions as Array<Record<string, unknown>>) || [];
  const overallGapScore = (diffDoc.overallGapScore as number) ?? 0;
  const summary = (diffDoc.actionPlanSummary as string) || "";

  return (
    <div className="space-y-5">
      <div className="shell-transition rounded-[22px] border border-[var(--shell-secondary)]/20 bg-[var(--shell-panel)] p-6 shadow-[var(--shell-shadow)]">
        <div className="text-xs text-[var(--shell-text-soft)]">Customer vs Web Reality</div>
        <div className="mt-1 text-4xl font-bold text-[var(--shell-text)]">
          {overallGapScore}<span className="text-lg text-[var(--shell-text-muted)]">/100</span>
        </div>
        {summary && <div className="mt-2 text-sm text-[var(--shell-text-muted)]">{summary}</div>}
      </div>

      <div className="grid gap-4 lg:grid-cols-2">
        {dimensions.map((item, i) => {
          const gapSeverity = (item.gapSeverity as number) ?? 0;
          const gapLevel = (item.gapLevel as string) || "";
          const barColor = gapSeverity >= 70
            ? "bg-[var(--shell-danger)]"
            : gapSeverity >= 35
              ? "bg-[var(--shell-warning)]"
              : "bg-[var(--shell-positive)]";
          return (
            <div key={i} className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-4 shadow-[var(--shell-shadow)]">
              <div className="flex items-center justify-between gap-3">
                <div className="text-sm font-medium text-[var(--shell-text)]">{item.dimension as string}</div>
                <span className={`rounded-full px-2 py-0.5 text-[11px] ${
                  gapLevel === "HIGH" ? "bg-[var(--shell-danger)]/15 text-[var(--shell-danger)]"
                    : gapLevel === "MEDIUM" ? "bg-[var(--shell-warning)]/15 text-[var(--shell-warning)]"
                      : "bg-[var(--shell-positive)]/15 text-[var(--shell-positive)]"
                }`}>
                  {gapLevel}
                </span>
              </div>
              <div className="mt-3 h-2 overflow-hidden rounded-full bg-[var(--shell-panel-soft)]">
                <div className={`h-full ${barColor}`} style={{ width: `${gapSeverity}%` }} />
              </div>
              <div className="mt-3 grid grid-cols-2 gap-3 text-xs">
                <div className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3">
                  <div className="text-[var(--shell-text-soft)]">고객 인식</div>
                  <div className="mt-1 text-[var(--shell-text)]">
                    {(item.customerValue as string[])?.join(", ") || "-"}
                  </div>
                </div>
                <div className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3">
                  <div className="text-[var(--shell-text-soft)]">웹 현실</div>
                  <div className="mt-1 text-[var(--shell-text)]">
                    {(item.autoDetectedValue as string[])?.join(", ") || "-"}
                  </div>
                </div>
              </div>
              {typeof item.gapDescription === "string" && (
                <div className="mt-3 text-sm text-[var(--shell-text-muted)]">{item.gapDescription}</div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}
