import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { ChevronDown, ChevronRight } from "lucide-react";
import { getDocument, listActionPreviews } from "../db/boards";
import { useCommand } from "../hooks/useCommand";

interface StructuredAction {
  title: string;
  priority: string;
  category: string;
  impact?: string;
  steps?: string[];
  difficulty?: string;
  effort?: string;
  estimatedHours?: number;
  channel?: string;
  direction?: string;
  customerApprovalRequired?: boolean;
  expectedMetric?: string;
  beforeAfterCheck?: string;
  targetQueries?: string[];
  contentBrief?: {
    workingTitle: string;
    targetKeywords: string[];
    outline: string[];
    topicsToCover: string[];
  };
  geoTactics?: string[];
  relatedKeywords?: string[];
  dataSource?: string;
}

interface ActionPreview {
  id: string;
  previewType: string;
  sourceActionTitle: string;
  beforeSnapshot: string;
  afterPreview: string;
  bestPracticeSample: string;
  notes: string[];
}

const CATEGORY_LABEL: Record<string, string> = {
  "geo-optimization": "GEO",
  "seo-technical": "SEO",
  content: "콘텐츠",
  "local-seo": "로컬",
  naver: "네이버",
};

const PRIORITY_COLOR: Record<string, string> = {
  high: "bg-[var(--shell-danger)]/20 text-[var(--shell-danger)] border border-[var(--shell-danger)]/30",
  medium: "bg-[var(--shell-warning)]/20 text-[var(--shell-warning)] border border-[var(--shell-warning)]/30",
  low: "bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)] border border-[var(--shell-border)]",
};

const DIFFICULTY_LABEL: Record<string, string> = {
  low: "쉬움",
  medium: "보통",
  hard: "어려움",
};
const CHANNEL_LABEL: Record<string, string> = {
  "customer-site": "고객 사이트",
  "customer-sns": "고객 SNS",
  "external-trust": "외부 신뢰 채널",
  marketplace: "마켓플레이스",
  measurement: "측정",
};
const DIRECTION_LABEL: Record<string, string> = {
  auto: "자동",
  "semi-auto": "반자동",
  manual: "협의",
};

const PREVIEW_TYPES = [
  { key: "schema", label: "Schema Preview" },
  { key: "meta_og", label: "Meta/OG Preview" },
  { key: "content_draft", label: "Content Draft" },
  { key: "ai_simulation", label: "AI Simulation" },
] as const;

export function Actions() {
  const { id } = useParams<{ id: string }>();
  const [structured, setStructured] = useState<StructuredAction[]>([]);
  const [previews, setPreviews] = useState<ActionPreview[]>([]);
  const [loading, setLoading] = useState(true);
  const cmd = useCommand(id);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    Promise.all([
      getDocument(id, "action-plan"),
      listActionPreviews(id),
    ]).then(([doc, pvs]) => {
      const data = (doc?.data ?? {}) as Record<string, unknown>;
      const actions = (data.structuredActions ?? data.actions ?? []) as StructuredAction[];
      setStructured(actions);
      setPreviews(pvs as unknown as ActionPreview[]);
      setLoading(false);
    });
  }, [id]);

  const handleCreatePreview = async (previewType: string) => {
    const sourceActionTitle = structured[0]?.title || "핵심 GEO 액션";
    await cmd.execute("create_action_preview", {
      previewType,
      sourceActionTitle,
    });
    if (id) {
      const pvs = await listActionPreviews(id);
      setPreviews(pvs as unknown as ActionPreview[]);
    }
  };

  if (loading) {
    return (
      <div className="flex min-h-[40vh] items-center justify-center text-[var(--shell-text-muted)]">
        데이터 로딩 중...
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-[1400px] space-y-6">
      <header>
        <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">
          Execution
        </div>
        <h1 className="mt-2 text-3xl font-semibold text-[var(--shell-text)]">
          Actions
        </h1>
        <p className="mt-2 text-sm text-[var(--shell-text-muted)]">
          AI CMO가 분석 결과를 바탕으로 만든 실행 가능한 액션과 개선
          미리보기입니다.
        </p>
      </header>

      {/* Action Preview panel */}
      <section className="shell-transition rounded-[22px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
        <div className="flex items-center justify-between gap-4">
          <div>
            <div className="text-sm font-medium text-[var(--shell-text)]">
              Action Preview
            </div>
            <div className="mt-1 text-xs text-[var(--shell-text-soft)]">
              Before/After 형태로 Schema, 메타, 콘텐츠 초안, AI 응답
              시뮬레이션을 확인합니다.
            </div>
          </div>
          <div className="flex flex-wrap gap-2">
            {PREVIEW_TYPES.map((item) => (
              <button
                key={item.key}
                type="button"
                onClick={() => handleCreatePreview(item.key)}
                disabled={cmd.isRunning}
                className="shell-transition rounded-xl border border-[var(--shell-secondary)]/30 bg-[var(--shell-secondary)]/10 px-3 py-1.5 text-xs text-[var(--shell-secondary)] disabled:opacity-50"
              >
                {item.label}
              </button>
            ))}
          </div>
        </div>

        {cmd.isRunning && (
          <div className="mt-4 rounded-xl border border-[var(--shell-accent)] bg-[var(--shell-accent-soft)] px-4 py-2 text-sm text-[var(--shell-accent)]">
            <span className="inline-flex h-2 w-2 animate-pulse rounded-full bg-[var(--shell-accent)]" />{" "}
            {cmd.message || "프리뷰 생성 중..."}
          </div>
        )}

        <div className="mt-4 space-y-3">
          {previews.length > 0 ? (
            previews.slice(0, 4).map((preview) => (
              <div
                key={preview.id}
                className="rounded-[14px] border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4"
              >
                <div className="flex items-center justify-between gap-3">
                  <div className="text-sm font-medium text-[var(--shell-text)]">
                    {preview.sourceActionTitle || "Action Preview"}
                  </div>
                  <div className="text-[11px] text-[var(--shell-text-soft)]">
                    {preview.previewType}
                  </div>
                </div>
                <div className="mt-3 grid grid-cols-1 gap-3 md:grid-cols-2">
                  <div className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-3">
                    <div className="mb-1 text-[11px] text-[var(--shell-text-soft)]">
                      Before
                    </div>
                    <div className="text-sm text-[var(--shell-text-muted)]">
                      {preview.beforeSnapshot || "기준 스냅샷"}
                    </div>
                  </div>
                  <div className="rounded-xl border border-[var(--shell-positive)]/20 bg-[var(--shell-positive)]/5 p-3">
                    <div className="mb-1 text-[11px] text-[var(--shell-positive)]">
                      After
                    </div>
                    <div className="text-sm text-[var(--shell-text)]">
                      {preview.afterPreview || "개선 결과"}
                    </div>
                  </div>
                </div>
                {preview.bestPracticeSample && (
                  <div className="mt-3 text-xs text-[var(--shell-text-soft)]">
                    모범 사례: {preview.bestPracticeSample}
                  </div>
                )}
              </div>
            ))
          ) : (
            <div className="rounded-[14px] border border-dashed border-[var(--shell-border)] px-4 py-6 text-sm text-[var(--shell-text-soft)]">
              아직 생성된 액션 프리뷰가 없습니다. 상단 버튼으로 생성하세요.
            </div>
          )}
        </div>
      </section>

      {/* Structured actions */}
      {structured.length === 0 && (
        <div className="shell-transition rounded-[18px] border border-dashed border-[var(--shell-border)] bg-[var(--shell-panel)] p-6 text-sm text-[var(--shell-text-muted)]">
          전략 분석이 끝나면 액션이 생성됩니다.
        </div>
      )}

      <div className="space-y-2">
        {structured.map((a, idx) => (
          <ActionCard key={idx} action={a} />
        ))}
      </div>
    </div>
  );
}

function ActionCard({ action }: { action: StructuredAction }) {
  const [open, setOpen] = useState(false);
  const hasDetail = !!(
    action.contentBrief ||
    action.geoTactics?.length ||
    action.steps?.length ||
    action.targetQueries?.length
  );

  return (
    <div className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] shadow-[var(--shell-shadow)]">
      <button
        onClick={() => setOpen((v) => !v)}
        className="flex w-full items-start gap-3 p-4 text-left"
      >
        {hasDetail ? (
          open ? (
            <ChevronDown className="mt-0.5 h-4 w-4 shrink-0 text-[var(--shell-text-muted)]" />
          ) : (
            <ChevronRight className="mt-0.5 h-4 w-4 shrink-0 text-[var(--shell-text-muted)]" />
          )
        ) : (
          <span className="h-4 w-4 shrink-0" />
        )}
        <div className="min-w-0 flex-1">
          <div className="flex flex-wrap items-center gap-2">
            <span
              className={`rounded px-1.5 py-0.5 text-[10px] font-medium ${PRIORITY_COLOR[action.priority] || PRIORITY_COLOR.medium}`}
            >
              {action.priority?.toUpperCase()}
            </span>
            <span className="rounded bg-[var(--shell-panel-soft)] px-1.5 py-0.5 text-[10px] text-[var(--shell-text-muted)]">
              {CATEGORY_LABEL[action.category] || action.category}
            </span>
            {action.channel && (
              <span className="rounded border border-[var(--shell-positive)]/20 bg-[var(--shell-positive)]/10 px-1.5 py-0.5 text-[10px] text-[var(--shell-positive)]">
                채널: {CHANNEL_LABEL[action.channel] || action.channel}
              </span>
            )}
            {action.direction && (
              <span className="rounded border border-[var(--shell-accent)]/20 bg-[var(--shell-accent)]/10 px-1.5 py-0.5 text-[10px] text-[var(--shell-accent)]">
                방식: {DIRECTION_LABEL[action.direction] || action.direction}
              </span>
            )}
            {action.customerApprovalRequired && (
              <span className="rounded border border-[var(--shell-warning)]/20 bg-[var(--shell-warning)]/10 px-1.5 py-0.5 text-[10px] text-[var(--shell-warning)]">
                고객 승인 필요
              </span>
            )}
            <span className="text-sm font-medium text-[var(--shell-text)]">
              {action.title}
            </span>
          </div>
          {action.impact && (
            <div className="mt-1 text-xs text-[var(--shell-text-soft)]">
              {action.impact}
            </div>
          )}

          {/* Before/After summary */}
          <div className="mt-2 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] overflow-hidden">
            <div className="grid grid-cols-2 divide-x divide-[var(--shell-border)] md:grid-cols-4">
              <div className="px-2.5 py-2">
                <div className="text-[10px] text-[var(--shell-text-soft)]">기준값</div>
                <div className="text-xs font-medium text-[var(--shell-text-muted)]">측정 전</div>
              </div>
              <div className="px-2.5 py-2">
                <div className="text-[10px] text-[var(--shell-text-soft)]">전일 대비</div>
                <div className="text-xs font-medium text-[var(--shell-text-muted)]">재측정 대기</div>
              </div>
              <div className="px-2.5 py-2">
                <div className="text-[10px] text-[var(--shell-text-soft)]">전주 대비</div>
                <div className="text-xs font-medium text-[var(--shell-text-muted)]">재측정 대기</div>
              </div>
              <div className="px-2.5 py-2">
                <div className="text-[10px] text-[var(--shell-text-soft)]">목표</div>
                <div className="text-xs font-medium text-[var(--shell-positive)]">
                  {action.expectedMetric || "AI 언급률, 인용 위치"}
                </div>
              </div>
            </div>
          </div>

          <div className="mt-1.5 flex items-center gap-3 text-[11px] text-[var(--shell-text-soft)]">
            {action.estimatedHours != null && (
              <span>약 {action.estimatedHours}시간</span>
            )}
            {(action.difficulty || action.effort) && (
              <span>
                난이도:{" "}
                {DIFFICULTY_LABEL[action.difficulty || action.effort || ""] ||
                  action.difficulty ||
                  action.effort}
              </span>
            )}
            {action.dataSource && <span>출처: {action.dataSource}</span>}
          </div>
        </div>
      </button>

      {open && hasDetail && (
        <div className="space-y-3 border-t border-[var(--shell-border)] p-4">
          {action.contentBrief && (
            <div>
              <div className="text-[11px] uppercase tracking-wider text-[var(--shell-text-soft)]">
                콘텐츠 브리프
              </div>
              <div className="mt-1 text-sm font-medium text-[var(--shell-text)]">
                {action.contentBrief.workingTitle}
              </div>
              {action.contentBrief.targetKeywords?.length > 0 && (
                <div className="mt-2 flex flex-wrap gap-1">
                  {action.contentBrief.targetKeywords.map((k) => (
                    <span
                      key={k}
                      className="rounded bg-[var(--shell-secondary)]/15 px-1.5 py-0.5 text-[10px] text-[var(--shell-secondary)]"
                    >
                      {k}
                    </span>
                  ))}
                </div>
              )}
              {action.contentBrief.outline?.length > 0 && (
                <div className="mt-2">
                  <div className="text-[11px] text-[var(--shell-text-soft)]">
                    핵심 H2 구조
                  </div>
                  <ol className="mt-0.5 list-inside list-decimal space-y-0.5 text-xs text-[var(--shell-text-muted)]">
                    {action.contentBrief.outline.map((o, i) => (
                      <li key={i}>{o}</li>
                    ))}
                  </ol>
                </div>
              )}
            </div>
          )}

          {action.geoTactics && action.geoTactics.length > 0 && (
            <div>
              <div className="text-[11px] uppercase tracking-wider text-[var(--shell-text-soft)]">
                GEO 룰 적용
              </div>
              <ul className="mt-1 space-y-0.5 text-xs text-[var(--shell-text-muted)]">
                {action.geoTactics.map((t, i) => (
                  <li key={i}>{t}</li>
                ))}
              </ul>
            </div>
          )}

          {action.targetQueries && action.targetQueries.length > 0 && (
            <div>
              <div className="text-[11px] uppercase tracking-wider text-[var(--shell-text-soft)]">
                개선 대상 질문
              </div>
              <ul className="mt-1 list-inside list-disc space-y-0.5 text-xs text-[var(--shell-text-muted)]">
                {action.targetQueries.map((q, i) => (
                  <li key={i}>{q}</li>
                ))}
              </ul>
            </div>
          )}

          {action.steps && action.steps.length > 0 && (
            <div>
              <div className="text-[11px] uppercase tracking-wider text-[var(--shell-text-soft)]">
                실행 단계
              </div>
              <ol className="mt-1 list-inside list-decimal space-y-0.5 text-xs text-[var(--shell-text-muted)]">
                {action.steps.map((s, i) => (
                  <li key={i}>{s}</li>
                ))}
              </ol>
            </div>
          )}

          {action.relatedKeywords && action.relatedKeywords.length > 0 && (
            <div className="flex flex-wrap items-center gap-1 border-t border-[var(--shell-border)] pt-2">
              <span className="text-[11px] text-[var(--shell-text-soft)]">
                관련 키워드:
              </span>
              {action.relatedKeywords.map((k) => (
                <span
                  key={k}
                  className="rounded bg-[var(--shell-panel-soft)] px-1.5 py-0.5 text-[10px] text-[var(--shell-text-soft)]"
                >
                  {k}
                </span>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}
