import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { BoardSectionTabs } from "../components/BoardSectionTabs";
import {
  getDocument,
  listActionPreviews,
  listActionRuns,
} from "../db/boards";
import { useCommand } from "../hooks/useCommand";
import type { BoardDocument } from "../db/collections";

interface ActionPreview {
  id: string;
  title?: string;
  platform?: string;
  status?: string;
  body?: string;
  createdAt?: string;
}

interface ActionRun {
  id: string;
  title?: string;
  platform?: string;
  status?: string;
  publishedAt?: string;
  url?: string;
  createdAt?: string;
}

export function CreateDeploy() {
  const { id, section } = useParams<{ id: string; section?: string }>();
  const activeTab = section || "content";
  const cmd = useCommand(id);

  const [actionPlan, setActionPlan] = useState<BoardDocument | null>(null);
  const [previews, setPreviews] = useState<ActionPreview[]>([]);
  const [runs, setRuns] = useState<ActionRun[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    Promise.all([
      getDocument(id, "action-plan").catch(() => null),
      listActionPreviews(id).catch(() => []),
      listActionRuns(id).catch(() => []),
    ]).then(([plan, pv, rn]) => {
      setActionPlan(plan);
      setPreviews(pv as ActionPreview[]);
      setRuns(rn as ActionRun[]);
      setLoading(false);
    });
  }, [id]);

  const handleGenerate = async () => {
    await cmd.execute("generate_sns_drafts");
    if (id) {
      const [plan, pv, rn] = await Promise.all([
        getDocument(id, "action-plan").catch(() => null),
        listActionPreviews(id).catch(() => []),
        listActionRuns(id).catch(() => []),
      ]);
      setActionPlan(plan);
      setPreviews(pv as ActionPreview[]);
      setRuns(rn as ActionRun[]);
    }
  };

  const tabs = [
    { label: "Content", to: `/board/${id}/create-deploy/content` },
    { label: "Deploy", to: `/board/${id}/create-deploy/deploy` },
    { label: "Calendar", to: `/board/${id}/create-deploy/calendar` },
  ];

  if (loading) {
    return (
      <div className="flex min-h-[40vh] items-center justify-center text-[var(--shell-text-muted)]">
        데이터 로딩 중...
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-[1400px] space-y-6">
      <header className="flex items-end justify-between gap-4">
        <div>
          <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">
            Create &amp; Deploy
          </div>
          <h1 className="mt-2 text-3xl font-semibold text-[var(--shell-text)]">
            콘텐츠 생성 및 배포
          </h1>
          <p className="mt-2 text-sm text-[var(--shell-text-muted)]">
            AI가 생성한 콘텐츠 초안을 확인하고 배포 상태를 관리합니다.
          </p>
        </div>
        <button
          type="button"
          onClick={handleGenerate}
          disabled={cmd.isRunning}
          className="shell-button-primary rounded-xl px-4 py-2.5 text-sm font-medium disabled:opacity-50"
        >
          {cmd.isRunning ? "생성 중..." : "콘텐츠 생성"}
        </button>
      </header>

      {/* Running indicator */}
      {cmd.isRunning && (
        <div className="shell-transition rounded-[16px] border border-[var(--shell-accent)]/40 bg-[var(--shell-accent-soft)] px-5 py-4">
          <div className="flex items-center gap-3 text-sm font-medium text-[var(--shell-accent)]">
            <span className="inline-flex h-2.5 w-2.5 animate-pulse rounded-full bg-[var(--shell-accent)]" />
            {cmd.message || "콘텐츠를 생성하고 있습니다..."}
          </div>
          <div className="mt-3 h-2 overflow-hidden rounded-full bg-[var(--shell-border)]">
            <div
              className="h-full rounded-full bg-[var(--shell-accent)] transition-all duration-500 ease-out"
              style={{ width: `${Math.max(cmd.progress, 2)}%` }}
            />
          </div>
        </div>
      )}

      {/* Action plan summary */}
      {actionPlan?.body && (
        <section className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
          <div className="text-[11px] uppercase tracking-[0.18em] text-[var(--shell-text-soft)]">
            Action Plan
          </div>
          <p className="mt-3 whitespace-pre-wrap text-sm leading-6 text-[var(--shell-text-muted)]">
            {actionPlan.body}
          </p>
        </section>
      )}

      <BoardSectionTabs items={tabs} />

      {/* Tab content */}
      {activeTab === "content" && (
        <ContentTab previews={previews} />
      )}
      {activeTab === "deploy" && (
        <DeployTab runs={runs} />
      )}
      {activeTab === "calendar" && (
        <CalendarTab />
      )}
    </div>
  );
}

/* ── Content tab ───────────────────────────────────────── */

function ContentTab({ previews }: { previews: ActionPreview[] }) {
  if (previews.length === 0) {
    return (
      <div className="shell-transition rounded-[18px] border border-dashed border-[var(--shell-border)] bg-[var(--shell-panel)] p-8 text-center text-sm text-[var(--shell-text-muted)]">
        아직 생성된 콘텐츠가 없습니다. 상단의 "콘텐츠 생성" 버튼으로 AI
        초안을 만들어 보세요.
      </div>
    );
  }

  return (
    <section className="grid gap-4 md:grid-cols-2">
      {previews.map((preview) => (
        <article
          key={preview.id}
          className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]"
        >
          <div className="flex items-start justify-between gap-3">
            <div className="min-w-0">
              <div className="text-base font-medium text-[var(--shell-text)]">
                {preview.title || "제목 없음"}
              </div>
              {preview.platform && (
                <span className="mt-1 inline-block rounded-md bg-[var(--shell-panel-soft)] px-2 py-0.5 text-[11px] text-[var(--shell-text-soft)]">
                  {preview.platform}
                </span>
              )}
            </div>
            {preview.status && (
              <span
                className={`shrink-0 rounded-full px-2.5 py-1 text-[11px] ${
                  preview.status === "ready"
                    ? "bg-[var(--shell-positive)]/15 text-[var(--shell-positive)]"
                    : "bg-[var(--shell-warning)]/15 text-[var(--shell-warning)]"
                }`}
              >
                {preview.status === "ready" ? "준비됨" : preview.status}
              </span>
            )}
          </div>
          {preview.body && (
            <p className="mt-3 line-clamp-4 text-sm leading-6 text-[var(--shell-text-muted)]">
              {preview.body}
            </p>
          )}
        </article>
      ))}
    </section>
  );
}

/* ── Deploy tab ────────────────────────────────────────── */

function DeployTab({ runs }: { runs: ActionRun[] }) {
  if (runs.length === 0) {
    return (
      <div className="shell-transition rounded-[18px] border border-dashed border-[var(--shell-border)] bg-[var(--shell-panel)] p-8 text-center text-sm text-[var(--shell-text-muted)]">
        아직 배포 기록이 없습니다.
      </div>
    );
  }

  return (
    <section className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-[var(--shell-border)] text-left text-[var(--shell-text-soft)]">
              <th className="py-2 pr-4">제목</th>
              <th className="py-2 pr-4">플랫폼</th>
              <th className="py-2 pr-4">상태</th>
              <th className="py-2 pr-4">배포일</th>
            </tr>
          </thead>
          <tbody>
            {runs.map((run) => (
              <tr
                key={run.id}
                className="border-b border-[var(--shell-border)]/30 text-[var(--shell-text-muted)]"
              >
                <td className="py-3 pr-4">
                  {run.url ? (
                    <a
                      href={run.url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="text-[var(--shell-accent)] hover:underline"
                    >
                      {run.title || run.id}
                    </a>
                  ) : (
                    run.title || run.id
                  )}
                </td>
                <td className="py-3 pr-4">{run.platform || "-"}</td>
                <td className="py-3 pr-4">
                  <span
                    className={`rounded-full px-2 py-0.5 text-[11px] ${
                      run.status === "published"
                        ? "bg-[var(--shell-positive)]/15 text-[var(--shell-positive)]"
                        : run.status === "failed"
                          ? "bg-[var(--shell-danger)]/15 text-[var(--shell-danger)]"
                          : "bg-[var(--shell-warning)]/15 text-[var(--shell-warning)]"
                    }`}
                  >
                    {run.status || "대기"}
                  </span>
                </td>
                <td className="whitespace-nowrap py-3 pr-4">
                  {run.publishedAt
                    ? String(run.publishedAt).slice(0, 16).replace("T", " ")
                    : "-"}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </section>
  );
}

/* ── Calendar tab (placeholder) ────────────────────────── */

function CalendarTab() {
  return (
    <div className="shell-transition rounded-[18px] border border-dashed border-[var(--shell-border)] bg-[var(--shell-panel)] p-8 text-center text-sm text-[var(--shell-text-muted)]">
      콘텐츠 캘린더 뷰는 준비 중입니다.
    </div>
  );
}
