import { useEffect, useState, useRef } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { subscribeBoard } from "../db/boards";
import type { Board, CommandDoc } from "../db/collections";
import {
  collection,
  query,
  where,
  orderBy,
  limit,
  onSnapshot,
} from "firebase/firestore";
import { db } from "../config/firebase";

type Phase = "intro" | "crawling" | "analyzing" | "done" | "failed";

const STEP_LABELS: Record<string, string> = {
  crawl: "사이트 수집",
  seo: "SEO 분석",
  brand: "브랜드 분석",
  keywords: "키워드 분석",
  competitors: "경쟁사 분석",
  geoProbe: "GEO 프로브",
  external: "외부 소스 분석",
  sns: "SNS 분석",
  content: "콘텐츠 분석",
  harness: "종합 분석",
};

export function Onboarding() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [phase, setPhase] = useState<Phase>("intro");
  const [board, setBoard] = useState<Board | null>(null);
  const [cmdProgress, setCmdProgress] = useState(0);
  const [cmdMessage, setCmdMessage] = useState("");
  const [cmdError, setCmdError] = useState<string | null>(null);
  const fallbackRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (!id) return;

    const introTimer = setTimeout(() => {
      setPhase((prev) => (prev === "intro" ? "crawling" : prev));
    }, 1500);

    const unsubBoard = subscribeBoard(id, (b) => {
      if (!b) return;
      setBoard(b);

      if (b.status === "complete") {
        setPhase("done");
        setTimeout(() => navigate(`/board/${id}`, { replace: true }), 800);
      } else if (b.status === "failed") {
        setPhase("failed");
      } else if (b.status === "analyzing") {
        setPhase("analyzing");
      } else if (b.status === "crawling") {
        setPhase("crawling");
      }
    });

    const cmdQuery = query(
      collection(db, "boards", id, "commands"),
      where("type", "==", "onboard"),
      orderBy("createdAt", "desc"),
      limit(1),
    );
    const unsubCmd = onSnapshot(cmdQuery, (snap) => {
      if (snap.empty) return;
      const data = snap.docs[0].data() as Omit<CommandDoc, "id">;
      setCmdProgress(data.progress ?? 0);
      setCmdMessage(data.message ?? "");
      if (data.status === "failed") {
        setCmdError(data.error ?? "알 수 없는 오류가 발생했습니다.");
        setPhase("failed");
      }
      if (data.status === "complete") {
        setPhase("done");
        setTimeout(() => navigate(`/board/${id}`, { replace: true }), 800);
      }
    });

    fallbackRef.current = setTimeout(() => {
      navigate(`/board/${id}`, { replace: true });
    }, 180_000);

    return () => {
      clearTimeout(introTimer);
      if (fallbackRef.current) clearTimeout(fallbackRef.current);
      unsubBoard();
      unsubCmd();
    };
  }, [id, navigate]);

  const activeSteps = board?.stepStatus
    ? Object.entries(board.stepStatus).filter(([, s]) => s && s !== "idle")
    : [];

  const completedStepCount = activeSteps.filter(([, s]) => s === "complete").length;
  const totalStepCount = Math.max(activeSteps.length, 1);
  const stepPct = Math.round((completedStepCount / totalStepCount) * 100);
  const displayPct = phase === "done" ? 100 : Math.max(cmdProgress, stepPct);

  return (
    <div className="flex min-h-screen flex-col items-center justify-center bg-[var(--shell-main)] px-4 text-[var(--shell-text)]">
      <div className="w-full max-w-md text-center">
        <div className="text-[11px] uppercase tracking-[0.24em] text-[var(--shell-text-soft)]">
          Your AI Chief Marketing Officer
        </div>

        {phase === "intro" && (
          <div className="mt-8">
            <div className="flex justify-center">
              <div className="flex gap-1.5">
                {[0, 1, 2].map((i) => (
                  <div
                    key={i}
                    className="h-2 w-2 rounded-full bg-[var(--shell-accent)] animate-pulse"
                    style={{ animationDelay: `${i * 200}ms` }}
                  />
                ))}
              </div>
            </div>
            <p className="mt-6 text-sm text-[var(--shell-text-muted)]">
              사이트 분석을 준비하고 있습니다...
            </p>
          </div>
        )}

        {(phase === "crawling" || phase === "analyzing" || phase === "done") && (
          <div className="mt-8 space-y-6">
            <div className="flex items-baseline justify-center gap-1">
              <span className="text-4xl font-light tabular-nums">
                {displayPct}
              </span>
              <span className="text-lg text-[var(--shell-text-soft)]">%</span>
            </div>

            <div className="mx-auto w-full max-w-xs">
              <div className="h-1 overflow-hidden rounded-full bg-[var(--shell-panel-strong)]">
                <div
                  className="h-full rounded-full bg-[var(--shell-accent)] transition-all duration-500 ease-out"
                  style={{ width: `${Math.max(displayPct, 3)}%` }}
                />
              </div>
            </div>

            {activeSteps.length > 0 && (
              <div className="mx-auto max-w-xs space-y-2">
                {activeSteps.map(([step, status]) => (
                  <div key={step} className="flex items-center gap-2 text-xs">
                    <span
                      className={`inline-flex h-2 w-2 shrink-0 rounded-full ${
                        status === "complete"
                          ? "bg-[var(--shell-positive)]"
                          : status === "running"
                            ? "bg-[var(--shell-accent)] animate-pulse"
                            : status === "failed"
                              ? "bg-[var(--shell-danger)]"
                              : "bg-[var(--shell-border)]"
                      }`}
                    />
                    <span className="text-[var(--shell-text-muted)]">
                      {STEP_LABELS[step] ?? step}
                    </span>
                  </div>
                ))}
              </div>
            )}

            {cmdMessage && (
              <p className="text-sm text-[var(--shell-text-muted)]">{cmdMessage}</p>
            )}

            <p className="text-sm text-[var(--shell-text-soft)]">
              {phase === "done"
                ? "수집 완료! 보드를 열고 있습니다..."
                : phase === "analyzing"
                  ? "데이터를 분석하고 있습니다"
                  : "사이트의 모든 페이지를 수집하고 있습니다"}
            </p>
          </div>
        )}

        {phase === "failed" && (
          <div className="mt-8 space-y-6">
            <div className="mx-auto flex h-14 w-14 items-center justify-center rounded-full border border-[var(--shell-danger)]/30 bg-[var(--shell-danger)]/10 text-[var(--shell-danger)]">
              !
            </div>
            <p className="text-sm text-[var(--shell-danger)]">
              {cmdError ?? "분석 중 오류가 발생했습니다."}
            </p>
            <button
              onClick={() => navigate("/", { replace: true })}
              className="shell-transition rounded-2xl border border-[var(--shell-border)] px-6 py-3 text-sm text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
            >
              돌아가기
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
