import { useCallback, useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { BoardSectionTabs } from "../components/BoardSectionTabs";
import {
  getBoard,
  getCustomerProfile,
  saveCustomerProfile,
  listCustomerMaterials,
} from "../db/boards";
import { useCommand } from "../hooks/useCommand";
import type { Board, StepName, StepStatus } from "../db/collections";

// ── Section routing ──────────────────────────────────────

const MANAGE_SECTIONS = [
  { key: "customer-input", label: "Customer Input" },
  { key: "jobs", label: "Jobs" },
  { key: "settings", label: "Settings" },
] as const;

type SectionKey = (typeof MANAGE_SECTIONS)[number]["key"];

function isSection(v?: string): v is SectionKey {
  return MANAGE_SECTIONS.some((s) => s.key === v);
}

// ── Step display helpers ─────────────────────────────────

const STEP_LABELS: Record<StepName, string> = {
  crawl: "Crawl",
  seo: "SEO Audit",
  brand: "Brand Analysis",
  keywords: "Keyword Strategy",
  competitors: "Competitor Analysis",
  geoProbe: "GEO Probe",
  external: "External Sources",
  sns: "SNS Analysis",
  content: "Content Analysis",
  harness: "Harness",
};

function statusColor(status: StepStatus): string {
  switch (status) {
    case "idle":
      return "bg-[var(--shell-text-muted)]/15 text-[var(--shell-text-muted)]";
    case "pending":
      return "bg-[var(--shell-warning)]/15 text-[var(--shell-warning)]";
    case "running":
      return "bg-[var(--shell-accent)]/15 text-[var(--shell-accent)]";
    case "complete":
      return "bg-[var(--shell-positive)]/15 text-[var(--shell-positive)]";
    case "failed":
      return "bg-[var(--shell-danger)]/15 text-[var(--shell-danger)]";
  }
}

function statusLabel(status: StepStatus): string {
  switch (status) {
    case "idle":
      return "Idle";
    case "pending":
      return "Pending";
    case "running":
      return "Running";
    case "complete":
      return "Complete";
    case "failed":
      return "Failed";
  }
}

// ── Customer profile form state ──────────────────────────

interface CustomerProfileForm {
  companyName: string;
  industry: string;
  targetAudience: string;
  keyServices: string;
  desiredQueries: string;
  notes: string;
}

const EMPTY_PROFILE: CustomerProfileForm = {
  companyName: "",
  industry: "",
  targetAudience: "",
  keyServices: "",
  desiredQueries: "",
  notes: "",
};

// ── Main component ───────────────────────────────────────

export function Manage() {
  const { id, section } = useParams<{ id: string; section?: string }>();
  const active: SectionKey = isSection(section) ? section : "customer-input";
  const cmd = useCommand(id);

  const tabs = MANAGE_SECTIONS.map((item) => ({
    label: item.label,
    to: `/board/${id}/manage/${item.key}`,
  }));

  return (
    <div className="mx-auto max-w-[1400px] space-y-6">
      <header className="space-y-3">
        <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">
          Manage
        </div>
        <h1 className="text-3xl font-semibold text-[var(--shell-text)]">
          {active === "customer-input" && "Customer Input"}
          {active === "jobs" && "Jobs"}
          {active === "settings" && "Settings"}
        </h1>
        <BoardSectionTabs items={tabs} />
      </header>

      {active === "customer-input" && <CustomerInputTab boardId={id!} />}
      {active === "jobs" && <JobsTab boardId={id!} cmd={cmd} />}
      {active === "settings" && <SettingsTab boardId={id!} cmd={cmd} />}
    </div>
  );
}

// ── Customer Input Tab ───────────────────────────────────

function CustomerInputTab({ boardId }: { boardId: string }) {
  const [form, setForm] = useState<CustomerProfileForm>(EMPTY_PROFILE);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const [materials, setMaterials] = useState<Array<Record<string, unknown>>>([]);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    Promise.all([getCustomerProfile(boardId), listCustomerMaterials(boardId)])
      .then(([profile, mats]) => {
        if (cancelled) return;
        if (profile) {
          setForm({
            companyName: (profile.companyName as string) ?? "",
            industry: (profile.industry as string) ?? "",
            targetAudience: (profile.targetAudience as string) ?? "",
            keyServices: (profile.keyServices as string) ?? "",
            desiredQueries: (profile.desiredQueries as string) ?? "",
            notes: (profile.notes as string) ?? "",
          });
        }
        setMaterials(mats);
        setLoading(false);
      })
      .catch(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [boardId]);

  const handleChange = useCallback(
    (field: keyof CustomerProfileForm, value: string) => {
      setForm((prev) => ({ ...prev, [field]: value }));
      setSaved(false);
    },
    [],
  );

  const handleSave = useCallback(async () => {
    setSaving(true);
    try {
      await saveCustomerProfile(boardId, { ...form });
      setSaved(true);
    } catch {
      // save failed silently
    } finally {
      setSaving(false);
    }
  }, [boardId, form]);

  if (loading) {
    return (
      <div className="flex min-h-[30vh] items-center justify-center text-[var(--shell-text-muted)]">
        Loading...
      </div>
    );
  }

  return (
    <div className="space-y-5">
      <section className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
        <div className="text-lg font-semibold text-[var(--shell-text)]">
          Customer Profile
        </div>
        <p className="mt-1 text-sm text-[var(--shell-text-muted)]">
          Fill in your company details so the analysis engine can tailor results
          to your business.
        </p>

        <div className="mt-5 grid gap-4 md:grid-cols-2">
          <FormField
            label="Company Name"
            value={form.companyName}
            onChange={(v) => handleChange("companyName", v)}
            placeholder="e.g. Acme Corp"
          />
          <FormField
            label="Industry"
            value={form.industry}
            onChange={(v) => handleChange("industry", v)}
            placeholder="e.g. B2B SaaS, Healthcare, E-commerce"
          />
          <FormField
            label="Target Audience"
            value={form.targetAudience}
            onChange={(v) => handleChange("targetAudience", v)}
            placeholder="e.g. SMB marketing managers in Korea"
          />
          <FormField
            label="Key Services"
            value={form.keyServices}
            onChange={(v) => handleChange("keyServices", v)}
            placeholder="e.g. SEO consulting, content marketing"
          />
          <div className="md:col-span-2">
            <FormField
              label="Desired Queries"
              value={form.desiredQueries}
              onChange={(v) => handleChange("desiredQueries", v)}
              placeholder="Queries you want to rank for, one per line"
              multiline
            />
          </div>
          <div className="md:col-span-2">
            <FormField
              label="Notes"
              value={form.notes}
              onChange={(v) => handleChange("notes", v)}
              placeholder="Any additional context for the analysis engine"
              multiline
            />
          </div>
        </div>

        <div className="mt-5 flex items-center gap-3">
          <button
            onClick={handleSave}
            disabled={saving}
            className="shell-button-primary rounded-xl px-4 py-2.5 text-sm font-medium disabled:opacity-50"
          >
            {saving ? "Saving..." : "Save Profile"}
          </button>
          {saved && (
            <span className="text-sm text-[var(--shell-positive)]">
              Saved successfully
            </span>
          )}
        </div>
      </section>

      {materials.length > 0 && (
        <section className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
          <div className="text-lg font-semibold text-[var(--shell-text)]">
            Uploaded Materials
          </div>
          <p className="mt-1 text-sm text-[var(--shell-text-muted)]">
            Files and documents provided by the customer.
          </p>
          <div className="mt-4 space-y-2">
            {materials.map((mat, i) => (
              <div
                key={(mat.id as string) ?? i}
                className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-sm text-[var(--shell-text)]"
              >
                {(mat.name as string) ??
                  (mat.fileName as string) ??
                  (mat.title as string) ??
                  `Material ${i + 1}`}
              </div>
            ))}
          </div>
        </section>
      )}
    </div>
  );
}

// ── Jobs Tab ─────────────────────────────────────────────

function JobsTab({
  boardId,
  cmd,
}: {
  boardId: string;
  cmd: ReturnType<typeof useCommand>;
}) {
  const [board, setBoard] = useState<Board | null>(null);
  const [loading, setLoading] = useState(true);
  const [retrying, setRetrying] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    getBoard(boardId)
      .then((b) => {
        if (!cancelled) {
          setBoard(b);
          setLoading(false);
        }
      })
      .catch(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [boardId]);

  const handleRetry = useCallback(
    async (stepName: StepName) => {
      setRetrying(stepName);
      try {
        await cmd.execute("retry_step", { step: stepName });
      } finally {
        setRetrying(null);
      }
    },
    [cmd],
  );

  if (loading) {
    return (
      <div className="flex min-h-[30vh] items-center justify-center text-[var(--shell-text-muted)]">
        Loading...
      </div>
    );
  }

  if (!board) {
    return (
      <div className="flex min-h-[30vh] items-center justify-center text-[var(--shell-text-muted)]">
        Board not found.
      </div>
    );
  }

  const stepEntries = Object.entries(STEP_LABELS) as [StepName, string][];

  return (
    <div className="space-y-5">
      <section className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
        <div className="text-lg font-semibold text-[var(--shell-text)]">
          Step Status
        </div>
        <p className="mt-1 text-sm text-[var(--shell-text-muted)]">
          Current status of each analysis step. You can retry failed steps.
        </p>

        <div className="mt-4 space-y-2">
          {stepEntries.map(([stepName, label]) => {
            const status: StepStatus =
              board.stepStatus[stepName] ?? "idle";
            const isFailed = status === "failed";
            const isRetrying = retrying === stepName;

            return (
              <div
                key={stepName}
                className="flex items-center justify-between gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3"
              >
                <div className="flex items-center gap-3">
                  <span className="text-sm font-medium text-[var(--shell-text)]">
                    {label}
                  </span>
                  <span
                    className={`rounded-full px-2.5 py-1 text-[11px] font-medium ${statusColor(status)}`}
                  >
                    {statusLabel(status)}
                  </span>
                </div>

                {isFailed && (
                  <button
                    onClick={() => handleRetry(stepName)}
                    disabled={isRetrying || cmd.isRunning}
                    className="shell-button-primary rounded-xl px-4 py-2.5 text-sm font-medium disabled:opacity-50"
                  >
                    {isRetrying ? "Retrying..." : "Retry"}
                  </button>
                )}
              </div>
            );
          })}
        </div>
      </section>

      {cmd.isRunning && (
        <section className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
          <div className="text-sm font-medium text-[var(--shell-text)]">
            Command in progress
          </div>
          {cmd.message && (
            <p className="mt-1 text-sm text-[var(--shell-text-muted)]">
              {cmd.message}
            </p>
          )}
          {cmd.progress > 0 && (
            <div className="mt-3 h-2 w-full overflow-hidden rounded-full bg-[var(--shell-panel-soft)]">
              <div
                className="h-full rounded-full bg-[var(--shell-accent)] transition-all"
                style={{ width: `${Math.min(cmd.progress, 100)}%` }}
              />
            </div>
          )}
        </section>
      )}
    </div>
  );
}

// ── Settings Tab ─────────────────────────────────────────

function SettingsTab({
  boardId,
  cmd,
}: {
  boardId: string;
  cmd: ReturnType<typeof useCommand>;
}) {
  const [board, setBoard] = useState<Board | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    getBoard(boardId)
      .then((b) => {
        if (!cancelled) {
          setBoard(b);
          setLoading(false);
        }
      })
      .catch(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [boardId]);

  const handleReanalyze = useCallback(async () => {
    await cmd.execute("onboard");
  }, [cmd]);

  if (loading) {
    return (
      <div className="flex min-h-[30vh] items-center justify-center text-[var(--shell-text-muted)]">
        Loading...
      </div>
    );
  }

  if (!board) {
    return (
      <div className="flex min-h-[30vh] items-center justify-center text-[var(--shell-text-muted)]">
        Board not found.
      </div>
    );
  }

  return (
    <div className="space-y-5">
      <section className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
        <div className="text-lg font-semibold text-[var(--shell-text)]">
          Board Information
        </div>
        <p className="mt-1 text-sm text-[var(--shell-text-muted)]">
          Basic information about this board.
        </p>

        <div className="mt-4 space-y-3">
          <InfoRow label="URL" value={board.url} />
          <InfoRow label="Domain" value={board.domain} />
          <InfoRow label="Site Name" value={board.siteName} />
          <InfoRow label="Status" value={board.status} />
          <InfoRow
            label="Created"
            value={board.createdAt.toLocaleDateString("ko-KR", {
              year: "numeric",
              month: "long",
              day: "numeric",
            })}
          />
          {board.completedAt && (
            <InfoRow
              label="Completed"
              value={board.completedAt.toLocaleDateString("ko-KR", {
                year: "numeric",
                month: "long",
                day: "numeric",
              })}
            />
          )}
        </div>
      </section>

      <section className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
        <div className="text-lg font-semibold text-[var(--shell-text)]">
          Actions
        </div>
        <p className="mt-1 text-sm text-[var(--shell-text-muted)]">
          Re-run the full onboarding analysis pipeline from scratch.
        </p>

        <div className="mt-4">
          <button
            onClick={handleReanalyze}
            disabled={cmd.isRunning}
            className="shell-button-primary rounded-xl px-4 py-2.5 text-sm font-medium disabled:opacity-50"
          >
            {cmd.isRunning ? "Running..." : "재분석"}
          </button>
        </div>

        {cmd.isRunning && (
          <div className="mt-4">
            {cmd.message && (
              <p className="text-sm text-[var(--shell-text-muted)]">
                {cmd.message}
              </p>
            )}
            {cmd.progress > 0 && (
              <div className="mt-2 h-2 w-full overflow-hidden rounded-full bg-[var(--shell-panel-soft)]">
                <div
                  className="h-full rounded-full bg-[var(--shell-accent)] transition-all"
                  style={{ width: `${Math.min(cmd.progress, 100)}%` }}
                />
              </div>
            )}
          </div>
        )}

        {cmd.isComplete && (
          <p className="mt-3 text-sm text-[var(--shell-positive)]">
            Analysis complete.
          </p>
        )}

        {cmd.isFailed && cmd.error && (
          <p className="mt-3 text-sm text-[var(--shell-danger)]">
            {cmd.error}
          </p>
        )}
      </section>
    </div>
  );
}

// ── Shared components ────────────────────────────────────

function FormField({
  label,
  value,
  onChange,
  placeholder,
  multiline = false,
}: {
  label: string;
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  multiline?: boolean;
}) {
  return (
    <div>
      <label className="mb-1 block text-sm font-medium text-[var(--shell-text)]">
        {label}
      </label>
      {multiline ? (
        <textarea
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          rows={4}
          className="shell-input w-full rounded-[10px] px-3 py-2 text-sm"
        />
      ) : (
        <input
          type="text"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          className="shell-input w-full rounded-[10px] px-3 py-2 text-sm"
        />
      )}
    </div>
  );
}

function InfoRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex items-baseline justify-between gap-4 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
      <span className="text-sm text-[var(--shell-text-muted)]">{label}</span>
      <span className="text-right text-sm font-medium text-[var(--shell-text)]">
        {value}
      </span>
    </div>
  );
}
