import type { BoardDocument } from "../../../db/collections";

interface DiagnosisGeoTabProps {
  seoAudit: Record<string, any> | null;
  docs: BoardDocument[];
}

const GEO_DIMENSIONS = [
  { key: "citations", label: "Citations & References" },
  { key: "expertQuotes", label: "Expert Quotes" },
  { key: "depth", label: "Content Depth" },
  { key: "balance", label: "Perspective Balance" },
  { key: "authority", label: "Authority Signals" },
  { key: "readability", label: "Readability" },
  { key: "faqQuality", label: "FAQ Quality" },
  { key: "answerCapsule", label: "Answer Capsule" },
];

export function DiagnosisGeoTab({ seoAudit, docs }: DiagnosisGeoTabProps) {
  const geoScore = (seoAudit as any)?.geoScore ?? 0;
  const geoChecks = ((seoAudit as any)?.geoChecks ?? []) as Array<{
    rule: string;
    label?: string;
    status: "pass" | "warn" | "fail";
    message?: string;
    score?: number;
  }>;
  const contentDoc = docs.find((d) => d.key === "content-analysis");
  const dimensions =
    (contentDoc?.data as any)?.dimensions ?? ({} as Record<string, number>);

  return (
    <div className="space-y-5">
      {/* GEO Score */}
      <div className="flex items-center gap-6">
        <div
          className={`grid h-24 w-24 place-items-center rounded-full border-[5px] ${
            geoScore >= 80
              ? "border-[var(--shell-positive)]"
              : geoScore >= 50
                ? "border-[var(--shell-secondary)]"
                : "border-[var(--shell-danger)]"
          } bg-[var(--shell-panel-soft)]`}
        >
          <div className="text-3xl font-semibold text-[var(--shell-text)]">
            {geoScore}
          </div>
        </div>
        <div>
          <div className="text-2xl font-semibold text-[var(--shell-text)]">
            GEO Score
          </div>
          <div className="mt-1 text-xs text-[var(--shell-text-muted)]">
            LLM content quality for AI search engines
          </div>
        </div>
      </div>

      {/* Dimensions */}
      {Object.keys(dimensions).length > 0 && (
        <div>
          <div className="mb-3 text-[11px] uppercase tracking-[0.14em] text-[var(--shell-text-muted)]">
            Content Quality Dimensions
          </div>
          <div className="grid gap-2 sm:grid-cols-2">
            {GEO_DIMENSIONS.map((dim) => {
              const val = dimensions[dim.key] as number | undefined;
              if (val == null) return null;
              return (
                <div
                  key={dim.key}
                  className="shell-transition flex items-center justify-between rounded-[14px] border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3"
                >
                  <span className="text-sm text-[var(--shell-text)]">
                    {dim.label}
                  </span>
                  <div className="flex items-center gap-2">
                    <div className="h-1.5 w-16 overflow-hidden rounded-full bg-[var(--shell-panel-strong)]">
                      <div
                        className={`h-full rounded-full ${
                          val >= 70
                            ? "bg-[var(--shell-positive)]"
                            : val >= 40
                              ? "bg-[var(--shell-secondary)]"
                              : "bg-[var(--shell-danger)]"
                        }`}
                        style={{ width: `${val}%` }}
                      />
                    </div>
                    <span
                      className={`text-xs font-medium ${
                        val >= 70
                          ? "text-[var(--shell-positive)]"
                          : val >= 40
                            ? "text-[var(--shell-secondary)]"
                            : "text-[var(--shell-danger)]"
                      }`}
                    >
                      {val}
                    </span>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* GEO Checks */}
      {geoChecks.length > 0 && (
        <div>
          <div className="mb-3 text-[11px] uppercase tracking-[0.14em] text-[var(--shell-text-muted)]">
            GEO Checks ({geoChecks.length})
          </div>
          <div className="max-h-[300px] space-y-2 overflow-y-auto">
            {geoChecks.map((check) => (
              <div
                key={check.rule}
                className="shell-transition flex items-center gap-3 rounded-[14px] border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3"
              >
                <span
                  className={`inline-block h-2 w-2 shrink-0 rounded-full ${
                    check.status === "pass"
                      ? "bg-[var(--shell-positive)]"
                      : check.status === "warn"
                        ? "bg-[var(--shell-secondary)]"
                        : "bg-[var(--shell-danger)]"
                  }`}
                />
                <span className="flex-1 text-sm text-[var(--shell-text)]">
                  {check.label || check.rule}
                </span>
                {check.message && (
                  <span className="text-[11px] text-[var(--shell-text-soft)]">
                    {check.message.slice(0, 60)}
                  </span>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {geoChecks.length === 0 && Object.keys(dimensions).length === 0 && (
        <div className="py-6 text-center text-sm text-[var(--shell-text-soft)]">
          GEO analysis data not yet available.
        </div>
      )}
    </div>
  );
}
