import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { getBoard } from "../db/boards";
import { useCommand } from "../hooks/useCommand";
import type { Board, CommandType, StepStatus } from "../db/collections";

interface AutomationCard {
  title: string;
  description: string;
  command: CommandType;
  cycle: string;
  relatedStep?: string;
}

const AUTOMATIONS: AutomationCard[] = [
  {
    title: "자동 시뮬레이션",
    description:
      "AI 엔진(ChatGPT, Gemini, Claude 등)에서 브랜드 노출 여부를 자동으로 측정합니다.",
    command: "run_geo_probe",
    cycle: "매일",
    relatedStep: "geoProbe",
  },
  {
    title: "자동 문제 분석",
    description:
      "SEO/GEO 최적화 문제를 자동으로 분석하고 액션 플랜을 업데이트합니다.",
    command: "onboard",
    cycle: "매주",
    relatedStep: "crawl",
  },
  {
    title: "자동 콘텐츠 생성",
    description:
      "분석 결과를 바탕으로 SNS 콘텐츠 초안을 자동으로 생성합니다.",
    command: "generate_sns_drafts",
    cycle: "매주",
    relatedStep: "content",
  },
  {
    title: "트렌드 스냅샷",
    description:
      "현재 시점의 언급률, 노출률 등 핵심 지표를 스냅샷으로 기록합니다.",
    command: "create_trend_snapshot",
    cycle: "매일",
  },
];

function stepStatusLabel(status: StepStatus | undefined): {
  text: string;
  className: string;
} {
  switch (status) {
    case "complete":
      return {
        text: "완료",
        className:
          "bg-[var(--shell-positive)]/15 text-[var(--shell-positive)]",
      };
    case "running":
      return {
        text: "실행 중",
        className: "bg-[var(--shell-accent)]/15 text-[var(--shell-accent)]",
      };
    case "pending":
      return {
        text: "대기",
        className: "bg-[var(--shell-warning)]/15 text-[var(--shell-warning)]",
      };
    case "failed":
      return {
        text: "실패",
        className: "bg-[var(--shell-danger)]/15 text-[var(--shell-danger)]",
      };
    default:
      return {
        text: "미실행",
        className: "bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)]",
      };
  }
}

export function Automation() {
  const { id } = useParams<{ id: string }>();
  const cmd = useCommand(id);
  const [board, setBoard] = useState<Board | null>(null);
  const [loading, setLoading] = useState(true);
  const [runningCommand, setRunningCommand] = useState<CommandType | null>(
    null,
  );

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    getBoard(id)
      .catch(() => null)
      .then((b) => {
        setBoard(b);
        setLoading(false);
      });
  }, [id]);

  const handleRun = async (command: CommandType) => {
    setRunningCommand(command);
    await cmd.execute(command);
    if (id) {
      const b = await getBoard(id).catch(() => null);
      setBoard(b);
    }
    setRunningCommand(null);
  };

  if (loading) {
    return (
      <div className="flex min-h-[40vh] items-center justify-center text-[var(--shell-text-muted)]">
        데이터 로딩 중...
      </div>
    );
  }

  const stepStatus = board?.stepStatus ?? {};

  return (
    <div className="mx-auto max-w-[1400px] space-y-6">
      <header>
        <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">
          Automation
        </div>
        <h1 className="mt-2 text-3xl font-semibold text-[var(--shell-text)]">
          자동화
        </h1>
        <p className="mt-2 text-sm text-[var(--shell-text-muted)]">
          정기적으로 실행되는 자동화 작업을 관리하고 수동 실행할 수 있습니다.
        </p>
      </header>

      {/* Running indicator */}
      {cmd.isRunning && (
        <div className="shell-transition rounded-[16px] border border-[var(--shell-accent)]/40 bg-[var(--shell-accent-soft)] px-5 py-4">
          <div className="flex items-center gap-3 text-sm font-medium text-[var(--shell-accent)]">
            <span className="inline-flex h-2.5 w-2.5 animate-pulse rounded-full bg-[var(--shell-accent)]" />
            {cmd.message || "작업을 실행하고 있습니다..."}
          </div>
          <div className="mt-3 h-2 overflow-hidden rounded-full bg-[var(--shell-border)]">
            <div
              className="h-full rounded-full bg-[var(--shell-accent)] transition-all duration-500 ease-out"
              style={{ width: `${Math.max(cmd.progress, 2)}%` }}
            />
          </div>
        </div>
      )}

      {/* Automation cards */}
      <section className="grid gap-4 md:grid-cols-2">
        {AUTOMATIONS.map((auto) => {
          const status = auto.relatedStep
            ? stepStatusLabel(
                stepStatus[auto.relatedStep as keyof typeof stepStatus],
              )
            : stepStatusLabel(undefined);
          const isThisRunning =
            cmd.isRunning && runningCommand === auto.command;

          return (
            <article
              key={auto.command}
              className="shell-transition rounded-[18px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]"
            >
              <div className="flex items-start justify-between gap-3">
                <div className="min-w-0">
                  <div className="flex items-center gap-2">
                    <h2 className="text-base font-semibold text-[var(--shell-text)]">
                      {auto.title}
                    </h2>
                    <span
                      className={`rounded-full px-2.5 py-1 text-[11px] ${status.className}`}
                    >
                      {status.text}
                    </span>
                  </div>
                  <p className="mt-2 text-sm leading-6 text-[var(--shell-text-muted)]">
                    {auto.description}
                  </p>
                </div>
              </div>

              <div className="mt-4 flex items-center justify-between">
                <span className="rounded-md bg-[var(--shell-panel-soft)] px-2.5 py-1 text-[11px] text-[var(--shell-text-soft)]">
                  주기: {auto.cycle}
                </span>
                <button
                  type="button"
                  onClick={() => handleRun(auto.command)}
                  disabled={cmd.isRunning}
                  className="shell-button-primary rounded-xl px-4 py-2.5 text-sm font-medium disabled:opacity-50"
                >
                  {isThisRunning ? "실행 중..." : "지금 실행"}
                </button>
              </div>
            </article>
          );
        })}
      </section>
    </div>
  );
}
