import { useState } from "react";
import { Link } from "react-router-dom";
import {
  flatKeywords,
  type Board,
  type BoardDocument,
  type ClassifiedKeywords,
  type KeywordMetrics,
  type StrategyKeywords,
} from "../../db/collections";
import { addKeyword, removeKeyword } from "../../db/boards";

type KwTab = "page" | "site" | "competitor" | "recommended" | "local" | "strategy";
type CompSourceTab = "all" | "naver" | "llm" | "geo" | "local";

interface DashboardBrandProps {
  id: string;
  board: Board | null;
  docs: BoardDocument[];
  competitors: Array<Record<string, any>>;
  onCompetitorHover?: (index: number | null, pos?: { x: number; y: number }) => void;
}

export function DashboardBrand({ id, board, docs, competitors, onCompetitorHover }: DashboardBrandProps) {
  const [kwTab, setKwTab] = useState<KwTab>("page");
  const [compTab, setCompTab] = useState<CompSourceTab>("all");
  const [addingKw, setAddingKw] = useState<string | null>(null);
  const [newKw, setNewKw] = useState("");

  const brandDoc = docs.find((d) => d.key === "product-info");
  const keywordDoc = docs.find((d) => d.key === "keyword-analysis");
  const brandData = brandDoc?.data as Record<string, any> | undefined;
  const pageKeywords = flatKeywords(board?.classifiedKeywords);

  const classified = board?.classifiedKeywords;
  const isClassified = classified && !Array.isArray(classified);
  const ck = isClassified ? (classified as ClassifiedKeywords) : null;

  const siteKws = ck?.site ?? (keywordDoc?.data as any)?.site ?? [];
  const competitorKws = ck?.competitor ?? (keywordDoc?.data as any)?.competitor ?? [];
  const recommendedKws = ck?.recommended ?? [];
  const localKws = ck?.local ?? [];
  const strategy = ck?.strategy as StrategyKeywords | null | undefined;

  const summaryText =
    board?.siteInfo?.description || brandDoc?.body || board?.siteName || "Brand summary will appear here.";

  const handleAddKw = async (category: "site" | "competitor" | "recommended" | "local") => {
    const kw = newKw.trim();
    if (!kw || !id) return;
    await addKeyword(id, category, kw);
    setNewKw("");
    setAddingKw(null);
  };

  const handleRemoveKw = async (category: "site" | "competitor" | "recommended" | "local", entry: KeywordMetrics) => {
    if (!id) return;
    await removeKeyword(id, category, entry as any);
  };

  const filteredCompetitors = competitors.filter((c: any) => {
    if (compTab === "all") return true;
    const s = c.source ?? "";
    if (compTab === "naver") return s === "naver";
    if (compTab === "llm") return s === "web-search" || s === "google-serp";
    if (compTab === "geo") return s === "geo-probe";
    if (compTab === "local") return s === "gbp" || s === "local-search";
    return true;
  });

  const KW_TABS: Array<{ key: KwTab; label: string }> = [
    { key: "page", label: "Keywords" },
    { key: "site", label: "Site" },
    { key: "competitor", label: "Competitor" },
    { key: "recommended", label: "Recommended" },
    { key: "local", label: "Local" },
    { key: "strategy", label: "Strategy" },
  ];

  return (
    <section className="shell-transition overflow-hidden rounded-[22px] border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 shadow-[var(--shell-shadow)]">
      <div className="text-[11px] uppercase tracking-[0.18em] text-[var(--shell-text-soft)]">
        Brand Analysis
      </div>

      <div className="mt-4 grid gap-6 xl:grid-cols-[1.2fr,1fr]">
        {/* Summary */}
        <div>
          <div className="text-xl font-semibold text-[var(--shell-text)]">{board?.siteName || "..."}</div>
          {brandData?.industry && (
            <span className="mt-1 inline-block rounded-full border border-[var(--shell-border)] px-2.5 py-0.5 text-[11px] text-[var(--shell-text-muted)]">
              {String(brandData.industry)}
            </span>
          )}
          <div className="mt-3 text-sm leading-7 text-[var(--shell-text)]">{summaryText}</div>
          {brandData?.usp && Array.isArray(brandData.usp) && brandData.usp.length > 0 && (
            <div className="mt-4">
              <div className="mb-2 text-[11px] uppercase tracking-[0.14em] text-[var(--shell-text-muted)]">USP</div>
              <div className="space-y-1.5">
                {(brandData.usp as string[]).map((u, i) => (
                  <div key={i} className="flex items-start gap-2 text-sm text-[var(--shell-text)]">
                    <span className="mt-0.5 text-[var(--shell-positive)]">*</span>
                    {u}
                  </div>
                ))}
              </div>
            </div>
          )}
          <div className="mt-4 text-xs text-[var(--shell-text-soft)]">
            <Link to={`/board/${id}/manage/customer-input`} className="hover:text-[var(--shell-accent)]">Brand Truth 편집</Link>
          </div>
        </div>

        {/* Keyword tabs */}
        <div>
          <div className="flex gap-0.5 overflow-x-auto border-b border-[var(--shell-border)]">
            {KW_TABS.map(({ key, label }) => (
              <button
                key={key}
                onClick={() => { setKwTab(key); setAddingKw(null); }}
                className={`shell-transition shrink-0 border-b-2 px-2.5 py-2 text-[11px] ${
                  kwTab === key
                    ? "border-[var(--shell-accent)] text-[var(--shell-accent)]"
                    : "border-transparent text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
                }`}
              >
                {label}
              </button>
            ))}
          </div>

          <div className="mt-3 max-h-[320px] space-y-1 overflow-y-auto">
            {kwTab === "page" && <KeywordList items={pageKeywords.map((kw) => ({ keyword: kw }))} showMetrics={false} />}
            {kwTab === "site" && <KeywordListEditable items={siteKws} category="site" adding={addingKw === "site"} onStartAdd={() => setAddingKw("site")} newKw={newKw} setNewKw={setNewKw} onAdd={handleAddKw} onRemove={handleRemoveKw} />}
            {kwTab === "competitor" && <KeywordListEditable items={competitorKws} category="competitor" adding={addingKw === "competitor"} onStartAdd={() => setAddingKw("competitor")} newKw={newKw} setNewKw={setNewKw} onAdd={handleAddKw} onRemove={handleRemoveKw} />}
            {kwTab === "recommended" && <KeywordListEditable items={recommendedKws} category="recommended" adding={addingKw === "recommended"} onStartAdd={() => setAddingKw("recommended")} newKw={newKw} setNewKw={setNewKw} onAdd={handleAddKw} onRemove={handleRemoveKw} />}
            {kwTab === "local" && <KeywordListEditable items={localKws} category="local" adding={addingKw === "local"} onStartAdd={() => setAddingKw("local")} newKw={newKw} setNewKw={setNewKw} onAdd={handleAddKw} onRemove={handleRemoveKw} />}
            {kwTab === "strategy" && <StrategyView strategy={strategy} />}
          </div>
        </div>
      </div>

      {/* Competitors */}
      {competitors.length > 0 && (
        <div className="mt-6 border-t border-[var(--shell-border)] pt-5">
          <div className="mb-3 flex items-center justify-between">
            <div className="text-[11px] uppercase tracking-[0.14em] text-[var(--shell-text-muted)]">Competitors</div>
            <Link to={`/board/${id}/competitors`} className="text-xs text-[var(--shell-accent)] hover:text-[var(--shell-accent-strong)]">All</Link>
          </div>
          <div className="mb-3 flex gap-1">
            {(["all", "naver", "llm", "geo", "local"] as CompSourceTab[]).map((t) => (
              <button
                key={t}
                onClick={() => setCompTab(t)}
                className={`rounded-full px-2.5 py-1 text-[10px] transition-colors ${
                  compTab === t
                    ? "bg-[var(--shell-accent-soft)] text-[var(--shell-accent)]"
                    : "text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
                }`}
              >
                {t === "all" ? "All" : t === "naver" ? "Naver" : t === "llm" ? "LLM" : t === "geo" ? "GEO" : "Local"}
              </button>
            ))}
          </div>
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5">
            {filteredCompetitors.slice(0, 5).map((c: any, i) => (
              <div
                key={c.id || i}
                className="shell-transition rounded-[14px] border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3"
                onMouseEnter={(e) => onCompetitorHover?.(i, { x: e.clientX, y: e.clientY })}
                onMouseLeave={() => onCompetitorHover?.(null)}
              >
                <div className="flex items-center gap-2">
                  <span className="grid h-7 w-7 shrink-0 place-items-center rounded-md bg-[var(--shell-secondary-soft)] text-xs text-[var(--shell-secondary)]">{i + 1}</span>
                  <div className="min-w-0">
                    <div className="truncate text-sm text-[var(--shell-text)]">{c.name}</div>
                    <div className="truncate text-[11px] text-[var(--shell-text-soft)]">{c.domain}</div>
                  </div>
                </div>
                {c.source && (
                  <div className="mt-2">
                    <span className="rounded-full bg-[var(--shell-panel-strong)] px-2 py-0.5 text-[9px] text-[var(--shell-text-muted)]">{c.source}</span>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}
    </section>
  );
}

function KeywordList({ items, showMetrics = true }: { items: Array<{ keyword: string; naver?: any; google?: any; overallDifficulty?: number; custom?: boolean }>; showMetrics?: boolean }) {
  if (items.length === 0) return <div className="py-4 text-sm text-[var(--shell-text-soft)]">No keywords yet.</div>;
  return (
    <>
      {items.slice(0, 20).map((kw, i) => (
        <div key={kw.keyword + i} className="flex items-center justify-between gap-2 rounded-lg px-1 py-1.5 text-sm hover:bg-[var(--shell-panel-soft)]">
          <span className="flex items-center gap-2 text-[var(--shell-text)]">
            <span className="text-[var(--shell-text-soft)]">{String(i + 1).padStart(2, "0")}</span>
            {kw.keyword}
            {kw.custom && <span className="rounded bg-[var(--shell-accent-soft)] px-1 text-[9px] text-[var(--shell-accent)]">custom</span>}
          </span>
          {showMetrics && (kw.naver?.monthlySearchVolume || kw.google?.monthlySearchVolume || kw.overallDifficulty != null) && (
            <div className="flex items-center gap-2 text-[11px] text-[var(--shell-text-muted)]">
              {kw.naver?.monthlySearchVolume != null && <span>N:{kw.naver.monthlySearchVolume.toLocaleString()}</span>}
              {kw.google?.monthlySearchVolume != null && <span>G:{kw.google.monthlySearchVolume.toLocaleString()}</span>}
              {kw.overallDifficulty != null && (
                <div className="flex items-center gap-1">
                  <div className="h-1 w-8 overflow-hidden rounded-full bg-[var(--shell-panel-strong)]">
                    <div className={`h-full rounded-full ${kw.overallDifficulty >= 70 ? "bg-[var(--shell-danger)]" : kw.overallDifficulty >= 40 ? "bg-[var(--shell-secondary)]" : "bg-[var(--shell-positive)]"}`} style={{ width: `${kw.overallDifficulty}%` }} />
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      ))}
    </>
  );
}

function KeywordListEditable({
  items, category, adding, onStartAdd, newKw, setNewKw, onAdd, onRemove,
}: {
  items: KeywordMetrics[];
  category: "site" | "competitor" | "recommended" | "local";
  adding: boolean;
  onStartAdd: () => void;
  newKw: string;
  setNewKw: (v: string) => void;
  onAdd: (cat: "site" | "competitor" | "recommended" | "local") => void;
  onRemove: (cat: "site" | "competitor" | "recommended" | "local", entry: KeywordMetrics) => void;
}) {
  if (items.length === 0 && !adding) {
    return (
      <div className="py-4 text-center text-sm text-[var(--shell-text-soft)]">
        No {category} keywords.
        <button onClick={onStartAdd} className="ml-2 text-[var(--shell-accent)]">+ Add</button>
      </div>
    );
  }
  return (
    <>
      {items.slice(0, 20).map((kw, i) => (
        <div key={kw.keyword + i} className="group flex items-center justify-between gap-2 rounded-lg px-1 py-1.5 text-sm hover:bg-[var(--shell-panel-soft)]">
          <span className="flex items-center gap-2 text-[var(--shell-text)]">
            <span className="text-[var(--shell-text-soft)]">{String(i + 1).padStart(2, "0")}</span>
            {kw.keyword}
            {kw.custom && <span className="rounded bg-[var(--shell-accent-soft)] px-1 text-[9px] text-[var(--shell-accent)]">custom</span>}
            {kw.region && <span className="rounded bg-[var(--shell-panel-strong)] px-1 text-[9px] text-[var(--shell-text-muted)]">{kw.region}</span>}
          </span>
          <div className="flex items-center gap-2">
            {(kw.naver?.monthlySearchVolume || kw.google?.monthlySearchVolume) && (
              <span className="text-[11px] text-[var(--shell-text-muted)]">
                {kw.naver?.monthlySearchVolume != null && `N:${kw.naver.monthlySearchVolume.toLocaleString()}`}
                {kw.naver?.monthlySearchVolume != null && kw.google?.monthlySearchVolume != null && " "}
                {kw.google?.monthlySearchVolume != null && `G:${kw.google.monthlySearchVolume.toLocaleString()}`}
              </span>
            )}
            <button onClick={() => onRemove(category, kw)} className="hidden text-[var(--shell-danger)] group-hover:block" title="Remove">x</button>
          </div>
        </div>
      ))}
      {adding ? (
        <div className="mt-1 flex items-center gap-1">
          <input
            value={newKw}
            onChange={(e) => setNewKw(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && onAdd(category)}
            placeholder="Add keyword..."
            autoFocus
            className="shell-input flex-1 rounded-lg px-2 py-1.5 text-sm"
          />
          <button onClick={() => onAdd(category)} className="rounded-lg bg-[var(--shell-accent)] px-2 py-1.5 text-xs text-white">Add</button>
        </div>
      ) : (
        <button onClick={onStartAdd} className="mt-1 text-xs text-[var(--shell-accent)]">+ Add keyword</button>
      )}
    </>
  );
}

function StrategyView({ strategy }: { strategy?: StrategyKeywords | null }) {
  if (!strategy) return <div className="py-4 text-sm text-[var(--shell-text-soft)]">No strategy data.</div>;

  const phases: Array<{ key: string; label: string; items: string[]; tiers?: KeywordMetrics[] }> = [
    { key: "short", label: "Short-term", items: strategy.shortTerm || [], tiers: strategy.tiers?.shortTerm },
    { key: "mid", label: "Mid-term", items: strategy.midTerm || [], tiers: strategy.tiers?.midTerm },
    { key: "long", label: "Long-term", items: strategy.longTerm || [], tiers: strategy.tiers?.longTerm },
  ];

  return (
    <div className="space-y-3">
      {phases.map((phase) => (
        <div key={phase.key}>
          <div className="mb-1 text-[11px] font-medium uppercase tracking-[0.12em] text-[var(--shell-text-muted)]">{phase.label} ({phase.items.length})</div>
          {phase.items.length > 0 ? (
            <div className="space-y-0.5">
              {phase.items.slice(0, 8).map((kw, i) => {
                const tier = phase.tiers?.find((t) => t.keyword === kw);
                return (
                  <div key={kw + i} className="flex items-center justify-between rounded-lg px-1 py-1 text-sm hover:bg-[var(--shell-panel-soft)]">
                    <span className="text-[var(--shell-text)]">{kw}</span>
                    {tier?.overallDifficulty != null && (
                      <div className="flex items-center gap-1">
                        <div className="h-1 w-6 overflow-hidden rounded-full bg-[var(--shell-panel-strong)]">
                          <div className={`h-full rounded-full ${tier.overallDifficulty >= 70 ? "bg-[var(--shell-danger)]" : tier.overallDifficulty >= 40 ? "bg-[var(--shell-secondary)]" : "bg-[var(--shell-positive)]"}`} style={{ width: `${tier.overallDifficulty}%` }} />
                        </div>
                        <span className="text-[10px] text-[var(--shell-text-muted)]">{tier.overallDifficulty}</span>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          ) : (
            <div className="text-xs text-[var(--shell-text-soft)]">No keywords in this phase.</div>
          )}
        </div>
      ))}
      {strategy.highPriorityActions && strategy.highPriorityActions.length > 0 && (
        <div className="border-t border-[var(--shell-border)] pt-2">
          <div className="mb-1 text-[11px] font-medium uppercase tracking-[0.12em] text-[var(--shell-text-muted)]">High Priority</div>
          {strategy.highPriorityActions.slice(0, 5).map((a) => (
            <div key={a.keyword} className="flex items-center justify-between rounded-lg px-1 py-1 text-sm hover:bg-[var(--shell-panel-soft)]">
              <span className="text-[var(--shell-text)]">{a.keyword}</span>
              <span className="text-[10px] text-[var(--shell-text-muted)]">{a.totalMonthlyVolume.toLocaleString()}/mo</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
